function isProviderConfigKey(key) {
  return Object.prototype.hasOwnProperty.call(providerLabels, key);
}

function normalizeModelTimeoutOverrides(raw) {
  let source = raw;
  if (typeof source === "string") {
    try { source = JSON.parse(source || "{}"); } catch (_error) { source = {}; }
  }
  if (!source || typeof source !== "object" || Array.isArray(source)) return {};
  const result = {};
  Object.entries(source).forEach(([key, value]) => {
    if (!isProviderConfigKey(key)) return;
    const timeout = Math.round(Number(value));
    if (Number.isFinite(timeout) && timeout >= 5 && timeout <= 600) result[key] = timeout;
  });
  return result;
}

function normalizeModelTokenLimitOverrides(raw) {
  let source = raw;
  if (typeof source === "string") {
    try { source = JSON.parse(source || "{}"); } catch (_error) { source = {}; }
  }
  if (!source || typeof source !== "object" || Array.isArray(source)) return {};
  const result = {};
  Object.entries(source).forEach(([key, value]) => {
    if (!isProviderConfigKey(key)) return;
    const tokenLimit = Math.round(Number(value));
    if (Number.isFinite(tokenLimit) && tokenLimit >= 256 && tokenLimit <= 2000000) result[key] = tokenLimit;
  });
  return result;
}

function normalizeModelFallbackOverrides(raw) {
  let source = raw;
  if (typeof source === "string") {
    try { source = JSON.parse(source || "{}"); } catch (_error) { source = {}; }
  }
  if (!source || typeof source !== "object" || Array.isArray(source)) return {};
  const result = {};
  Object.entries(source).forEach(([key, value]) => {
    const providerId = String(value || "").trim();
    if (isProviderConfigKey(key) && providerId) result[key] = providerId;
  });
  return result;
}

