function providerNeedsLowLatency(key) {
  const guide = providerGuides[key] || {};
  return guide.preference === "speed" || ["direct", "conditional"].includes(guide.passiveImpact || "");
}

function normalizeProviderConfigMode(value) {
  const text = String(value || "").trim().toLowerCase();
  const aliases = {
    fast: "quick",
    simple: "quick",
    "快速": "quick",
    "快速配置": "quick",
    precise: "precision",
    advanced: "precision",
    "精准": "precision",
    "精准配置": "precision",
    "分流": "precision",
  };
  const normalized = aliases[text] || text;
  return normalized === "precision" ? "precision" : "quick";
}

function inferProviderConfigMode(overview = state.overview || {}) {
  const settings = overview.settings || {};
  const explicit = String(settings.provider_config_mode || "").trim();
  if (explicit) return normalizeProviderConfigMode(explicit);
  const providers = {
    ...(overview.providers || {}),
    ...(state.providerDraft || {}),
  };
  const hasPrecisionProvider = Object.keys(providerLabels)
    .some((key) => !quickProviderKeys.has(key) && !alwaysVisibleProviderKeys.has(key) && visibleConfigKey(key) && Boolean(providers[key]));
  return hasPrecisionProvider ? "precision" : "quick";
}

function currentProviderConfigMode() {
  return normalizeProviderConfigMode(state.providerConfigMode || inferProviderConfigMode());
}

function providerAllowedInCurrentMode(key) {
  if (alwaysVisibleProviderKeys.has(key)) return true;
  const mode = currentProviderConfigMode();
  return mode === "quick" ? quickProviderKeys.has(key) : !quickProviderKeys.has(key);
}

function syncProviderConfigModeControls() {
  const mode = currentProviderConfigMode();
  const quick = mode === "quick";
  document.querySelectorAll("[data-provider-config-mode]").forEach((button) => {
    button.classList.toggle("active", button.dataset.providerConfigMode === mode);
  });
  const toolbar = document.querySelector(".provider-toolbar");
  toolbar?.classList.toggle("is-quick-mode", quick);
  const filter = document.getElementById("providerFilter");
  if (filter && quick) filter.value = "";
  document.querySelectorAll("[data-provider-mode]").forEach((button) => {
    const active = button.dataset.providerMode === (state.providerMode || "all");
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  const hint = document.getElementById("providerConfigModeHint");
  if (hint) {
    const tokenCostHint = "插件功能通常会携带较多动态上下文，Token 缓存命中率可能较低，请结合调用频率和预算合理规划模型。";
    hint.textContent = quick
      ? `${tokenCostHint} 快速配置显示通用场景模型；插件识图、夹层阅读视觉和通用嵌入模型各自独立。`
      : `${tokenCostHint} 精准配置显示各任务单独 Provider；独立识图与通用嵌入不会跟随文本模型改写。`;
  }
}

function setProviderConfigMode(mode, { render = true } = {}) {
  state.providerConfigMode = normalizeProviderConfigMode(mode);
  if (state.providerConfigMode === "quick") {
    state.providerMode = "all";
    state.providerFilter = "";
    const filter = document.getElementById("providerFilter");
    if (filter) filter.value = "";
  }
  syncProviderConfigModeControls();
  if (render) renderProviders();
}

function isPrivateReadingAvailable() {
  return Boolean(state.overview?.private_reading?.available);
}

function toBool(value) {
  if (typeof value === "string") {
    const text = value.trim().toLowerCase();
    if (["true", "1", "yes", "y", "on", "enable", "enabled", "启用", "开启", "开", "是"].includes(text)) return true;
    if (["false", "0", "no", "n", "off", "disable", "disabled", "停用", "关闭", "关", "否", ""].includes(text)) return false;
  }
  return Boolean(value);
}

function normalizeFeatureDraft(features = {}) {
  return Object.fromEntries(Object.entries(features || {}).map(([key, value]) => [key, toBool(value)]));
}

function featureDraftFromOverview(overview = {}) {
  const draft = normalizeFeatureDraft(overview.features || {});
  hiddenCompatibilityConfigKeys.forEach((key) => {
    delete draft[key];
  });
  const settings = overview.settings || {};
  Object.keys(draft).forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(settings, key)) {
      draft[key] = toBool(settings[key]);
    }
  });
  const settingBackedFeatureKeys = [
    "enable_auto_user_profile_creation",
    "enable_multi_persona_mode",
    "enable_body_monitor_integration",
    "enable_rest_reply_simulation",
    "enable_busy_reply_gate",
    "enable_segmented_proactive_reply",
    "enable_worldview_perception",
    "enable_group_injection_guard",
    "enable_group_persona_denoise",
    "auto_voice_enabled",
    "enable_tts_local_playback",
    "enable_tts_local_playback_live_only",
    "enable_tts_live_subtitle_sync",
    "group_repeat_count_distinct_users_only",
  ];
  settingBackedFeatureKeys.forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(settings, key)) {
      draft[key] = toBool(settings[key]);
    }
  });
  return draft;
}

function featureDraftSignature(draft = {}) {
  return JSON.stringify(
    Object.entries(draft || {})
      .map(([key, value]) => [String(key), toBool(value)])
      .sort(([left], [right]) => left.localeCompare(right)),
  );
}

function cloneFeatureStateValue(value) {
  if (value === undefined) return undefined;
  if (typeof structuredClone === "function") {
    try {
      return structuredClone(value);
    } catch (_error) {}
  }
  return JSON.parse(JSON.stringify(value));
}

function syncFeatureDraftFromOverview(overview = {}) {
  state.featureDraft = featureDraftFromOverview(overview);
  state.featureDraftBaseline = featureDraftSignature(state.featureDraft);
  state.featureAuxiliaryDraft = {
    proactive_intensity_preset: String(overview?.settings?.proactive_intensity_preset || "off"),
  };
  state.featureAuxiliaryDirty = false;
  state.featureDetailDirty = false;
  state.featureDetailBaseline = null;
  state.featureDetailParamDraft = {};
}

function beginFeatureDetailSession(featureKey) {
  const key = String(featureKey || "").trim();
  if (!key || state.featureDetailBaseline?.key === key) return;
  state.featureDetailBaseline = {
    key,
    featureDraft: cloneFeatureStateValue(state.featureDraft || {}),
    settings: cloneFeatureStateValue(state.overview?.settings || {}),
    providers: cloneFeatureStateValue(state.overview?.providers || {}),
    providerDraft: cloneFeatureStateValue(state.providerDraft || {}),
    imageApiEndpointDraft: cloneFeatureStateValue(state.imageApiEndpointDraft),
    formSignature: "",
  };
  state.featureDetailParamDraft = {};
  state.featureDetailDirty = false;
}

function rememberFeatureParamDraft(control, { allowPhotoReferenceCatalog = false } = {}) {
  const key = String(control?.dataset?.featureParam || "").trim();
  if (!key) return;
  if (key === "photo_reference_catalog" && !allowPhotoReferenceCatalog) return;
  const value = collectSettingValue(key, control);
  state.featureDetailParamDraft = {
    ...(state.featureDetailParamDraft || {}),
    [key]: value,
  };
  if (isProviderConfigKey(key)) {
    const providerValue = String(value || "").trim();
    state.providerDraft = { ...(state.providerDraft || {}), [key]: providerValue };
    if (state.overview) {
      state.overview.providers = state.overview.providers || {};
      state.overview.providers[key] = providerValue;
    }
    return;
  }
  const isFeatureOnly = Object.prototype.hasOwnProperty.call(state.featureDraft || {}, key)
    && !Object.prototype.hasOwnProperty.call(state.overview?.settings || {}, key);
  if (state.overview && !isFeatureOnly) {
    state.overview.settings = state.overview.settings || {};
    state.overview.settings[key] = value;
  }
  if (Object.prototype.hasOwnProperty.call(state.featureDraft || {}, key)) {
    state.featureDraft[key] = toBool(value);
  }
}

function featureDetailFormSignature(root = document) {
  const key = String(state.selectedFeatureKey || state.featureDetailBaseline?.key || "").trim();
  if (!key) return null;
  const page = root?.querySelector?.(".feature-detail-page");
  if (!page) return null;
  const toggle = page.querySelector("[data-feature-detail-toggle]");
  const params = {};
  page.querySelectorAll("[data-feature-param]").forEach((input) => {
    const paramKey = String(input.dataset.featureParam || "").trim();
    if (!paramKey) return;
    const value = collectSettingValue(paramKey, input);
    params[paramKey] = paramKey === "photo_reference_catalog"
      ? photoReferenceCatalogSignature(value)
      : value;
  });
  return JSON.stringify({
    key,
    enabled: toggle ? Boolean(toggle.checked) : toBool(state.featureDraft?.[key]),
    params,
  });
}

function captureFeatureDetailBaselineFromDom(root = document) {
  const baseline = state.featureDetailBaseline;
  if (!baseline || baseline.formSignature) return;
  const signature = featureDetailFormSignature(root);
  if (signature === null) return;
  baseline.formSignature = signature;
  state.featureDetailDirty = false;
}

function refreshFeatureDetailDirty() {
  const baseline = state.featureDetailBaseline;
  if (!baseline || !state.selectedFeatureKey) {
    state.featureDetailDirty = false;
    return false;
  }
  const current = featureDetailFormSignature();
  if (current === null || !baseline.formSignature) {
    return Boolean(state.featureDetailDirty);
  }
  state.featureDetailDirty = current !== baseline.formSignature;
  return state.featureDetailDirty;
}

function restoreFeatureDetailSession() {
  const baseline = state.featureDetailBaseline;
  if (!baseline) return;
  state.featureDraft = cloneFeatureStateValue(baseline.featureDraft || {});
  if (state.overview) {
    state.overview.settings = cloneFeatureStateValue(baseline.settings || {});
    state.overview.providers = cloneFeatureStateValue(baseline.providers || {});
  }
  state.providerDraft = cloneFeatureStateValue(baseline.providerDraft || {});
  state.imageApiEndpointDraft = cloneFeatureStateValue(baseline.imageApiEndpointDraft);
  state.featureDetailParamDraft = {};
}

function hasUnsavedFeatureChanges() {
  refreshFeatureDetailDirty();
  return state.featureAuxiliaryDirty
    || state.featureDetailDirty
    || featureDraftSignature(state.featureDraft || {}) !== String(state.featureDraftBaseline || "");
}

function hasUnsavedChanges() {
  return hasUnsavedFeatureChanges() || hasUnsavedModuleFormChanges() || hasUnsavedTtsProviderChanges();
}

function hasUnsavedTtsProviderChanges() {
  const draft = state.ttsProviderDraft || {};
  const saved = state.overview?.settings || {};
  const strategyChanged = Object.entries(draft).some(([key, value]) => {
    const current = saved[key];
    if (typeof value === "boolean" || typeof current === "boolean") return Boolean(value) !== Boolean(current);
    return String(value ?? "").trim() !== String(current ?? "").trim();
  });
  return strategyChanged || Object.keys(state.ttsProviderConfigDrafts || {}).length > 0;
}

function discardUnsavedTtsProviderChanges() {
  state.ttsProviderDraft = {};
  state.ttsProviderConfigDrafts = {};
  state.ttsProviderCreateOpen = false;
  state.ttsProviderCreateId = "";
}

function markFeatureDetailDirty() {
  state.featureDetailDirty = true;
  syncFeatureFooterAction();
  if (featureDetailDirtyRefreshScheduled) return;
  featureDetailDirtyRefreshScheduled = true;
  const refresh = () => {
    featureDetailDirtyRefreshScheduled = false;
    refreshFeatureDetailDirty();
    syncFeatureFooterAction();
  };
  if (typeof queueMicrotask === "function") queueMicrotask(refresh);
  else Promise.resolve().then(refresh);
}

function leaveFeatureDetail(control = null) {
  if (
    state.featureDetailSubpage === "photo_reference_library"
    && (photoReferenceManagerBusy() || state.photoReferenceAddDialogOpen)
  ) {
    showToast(state.photoReferenceSubmitting ? "参考图正在处理，请稍候" : "请先关闭参考图配置窗口", "error");
    return false;
  }
  if (state.featureDetailSubpage === "photo_reference_library") {
    state.featureDetailSubpage = "";
    state.photoReferenceManagerDraft = null;
    renderFeatureSwitches();
    return true;
  }
  if (refreshFeatureDetailDirty()) {
    if (control instanceof HTMLButtonElement) {
      const confirmed = requireSecondClick(
        control,
        "discard-feature-detail",
        "当前功能还有未保存的更改，再次点击放弃",
        "再次点击放弃更改",
      );
      if (!confirmed) return false;
    } else {
      const confirmed = window.confirm("当前功能还有未保存的更改。返回将放弃这些更改，确定返回吗？");
      if (!confirmed) return false;
    }
    restoreFeatureDetailSession();
  }
  state.featureDetailDirty = false;
  state.featureDetailBaseline = null;
  state.featureDetailParamDraft = {};
  state.featureDetailSubpage = "";
  state.photoReferenceManagerDraft = null;
  state.photoReferenceLibraryStatus = null;
  state.selectedFeatureKey = "";
  renderFeatureSwitches();
  return true;
}

function discardAllFeatureChanges() {
  if (photoReferenceManagerBusy()) {
    showToast("参考图正在处理，请稍候", "error");
    return false;
  }
  restoreFeatureDetailSession();
  state.featureAuxiliaryDirty = false;
  state.featureDetailDirty = false;
  state.featureDetailBaseline = null;
  state.featureDetailSubpage = "";
  state.photoReferenceManagerDraft = null;
  state.photoReferenceLibraryStatus = null;
  state.selectedFeatureKey = "";
  syncFeatureDraftFromOverview(state.overview || {});
  syncFeatureFooterAction();
  return true;
}

function imageCompanionInstalled() {
  return state.overview?.companion_plugins?.image?.installed === true;
}

function naiImageInstalled() {
  return state.overview?.companion_plugins?.nai?.installed === true;
}

function anyImageGeneratorInstalled() {
  return imageCompanionInstalled() || naiImageInstalled();
}

function realityCompanionInstalled() {
  return state.overview?.companion_plugins?.reality?.installed === true;
}

function contentCompanionInstalled() {
  return state.overview?.companion_plugins?.content?.installed === true;
}

function syncExternalCompanionVisibility() {
  const imageInstalled = imageCompanionInstalled();
  const anyImageInstalled = anyImageGeneratorInstalled();
  const imageRuntimeTab = document.querySelector('.tab[data-tab="image"]');
  const imageRuntimePanel = document.getElementById("panel-image");
  if (imageRuntimeTab) imageRuntimeTab.hidden = !imageInstalled;
  if (imageRuntimePanel) imageRuntimePanel.hidden = !imageInstalled;
  if (!imageInstalled && state.activeTab === "image") {
    document.querySelector('.tab[data-tab="dashboard"]')?.click();
  }
  const imageTab = document.getElementById("modelsImageTab");
  const imagePane = document.getElementById("modelsImagePane");
  if (imageTab) imageTab.hidden = !imageInstalled;
  if (imagePane && !imageInstalled) imagePane.hidden = true;
  if (!imageInstalled && state.modelsSection === "image") state.modelsSection = "providers";
  if (!anyImageInstalled && state.featureDomainFilter === "image_generation") {
    state.featureDomainFilter = "all";
  }

  const realityInstalled = realityCompanionInstalled();
  const realityTab = document.querySelector('.tab[data-tab="reality"]');
  const realityPanel = document.getElementById("panel-reality");
  if (realityTab) realityTab.hidden = !realityInstalled;
  if (realityPanel) realityPanel.hidden = !realityInstalled;
  if (!realityInstalled) {
    state.realityTouch = null;
    state.realityTouchError = "";
    if (state.activeTab === "reality") {
      document.querySelector('.tab[data-tab="dashboard"]')?.click();
    }
  }
  if (!anyImageInstalled && state.troubleshootingCategory === "image_generation") {
    state.troubleshootingCategory = "all";
  }

  const creativeInstalled = contentCompanionInstalled();
  const creativeTab = document.querySelector('.tab[data-tab="creative"]');
  const creativePanel = document.getElementById("panel-creative");
  if (creativeTab) creativeTab.hidden = !creativeInstalled;
  if (creativePanel) creativePanel.hidden = !creativeInstalled;
  if (!creativeInstalled && state.activeTab === "creative") {
    document.querySelector('.tab[data-tab="dashboard"]')?.click();
  }
}

const pluginIntegrationAvailabilityRules = {
  enable_photo_text_action: () => anyImageGeneratorInstalled(),
  enable_experimental_bluetooth_wakeup: () => realityCompanionInstalled(),
  enable_yesterday_screen_diary_context: () => Boolean(state.overview?.screen_companion?.available),
  enable_livingmemory_integration: () => Boolean(state.overview?.livingmemory?.compatible_available || state.overview?.livingmemory?.available || state.overview?.livingmemory?.memory_companion_active),
  enable_bilibili_integration: () => Boolean(state.overview?.bilibili?.available),
  enable_bilibili_boredom_watch: () => Boolean(state.overview?.bilibili?.available),
  enable_qzone_integration: () => state.overview?.qzone?.platform_supported !== false,
  enable_qzone_life_publish: () => state.overview?.qzone?.platform_supported !== false,
  enable_qzone_generated_image_publish: () => imageCompanionInstalled() && state.overview?.qzone?.platform_supported !== false,
  enable_qzone_comment_inbox: () => state.overview?.qzone?.platform_supported !== false,
  enable_qzone_emotional_vent_publish: () => Boolean(state.overview?.qzone?.available && toBool(state.featureDraft?.enable_emotion_simulation)),
  enable_creative_writing: () => true,
  enable_creative_cover_generation: () => true,
  CREATIVE_MODEL_PROVIDER_ID: () => true,
  CREATIVE_PROVIDER_ID: () => true,
  CREATIVE_OUTLINE_PROVIDER_ID: () => true,
  CREATIVE_REVIEW_PROVIDER_ID: () => true,
};

function unavailablePluginIntegrationOwner(key) {
  if (pluginIntegrationAvailabilityRules[key]) {
    return pluginIntegrationAvailabilityRules[key]() ? "" : key;
  }
  for (const [featureKey, settingKeys] of Object.entries(featureSettingGroups || {})) {
    if (!pluginIntegrationAvailabilityRules[featureKey]) continue;
    if ((settingKeys || []).includes(key) && !pluginIntegrationAvailabilityRules[featureKey]()) {
      return featureKey;
    }
  }
  return "";
}

function visibleConfigKey(key) {
  if (hiddenCompatibilityConfigKeys.has(key)) return false;
  if (unavailablePluginIntegrationOwner(key) && !legacyConfigGraceKeys.has(key)) return false;
  return isPrivateReadingAvailable() || !privateReadingConfigKeys.has(key);
}

