// These panels register window globals rather than ES module exports. Load
// them as classic scripts so cross-origin plugin Page containers do not make
// import() resolve relative paths against about:blank. Preserve AstrBot's
// signed asset token from the app.js URL.
const optionalScriptBaseUrl = (() => {
  const current = String(document.currentScript?.src || "").trim();
  if (current) return current;
  const appScript = Array.from(document.scripts || [])
    .reverse()
    .find((script) => /\/app\.js(?:[?#]|$)/.test(String(script?.src || "")));
  return String(appScript?.src || document.baseURI || window.location.href || "");
})();

function loadOptionalClassicScript(relativePath, retry = 0) {
  return new Promise((resolve, reject) => {
    let assetUrl;
    try {
      const base = new URL(optionalScriptBaseUrl, document.baseURI || window.location.href);
      assetUrl = new URL(relativePath, base);
      const assetToken = base.searchParams.get("asset_token");
      if (assetToken && !assetUrl.searchParams.has("asset_token")) {
        assetUrl.searchParams.set("asset_token", assetToken);
      }
      if (retry > 0) assetUrl.searchParams.set("retry", String(retry));
    } catch (error) {
      reject(error);
      return;
    }
    const script = document.createElement("script");
    script.src = assetUrl.href;
    script.async = true;
    script.dataset.privateCompanionOptional = "1";
    script.onload = () => resolve(true);
    script.onerror = () => {
      script.remove();
      reject(new Error(`页面模块脚本加载失败：${assetUrl.pathname}`));
    };
    document.head.appendChild(script);
  });
}

const optionalModuleLoaders = {
  providerTree: [
    () => loadOptionalClassicScript("./js/panels/provider-tree.js?v=20260804-private-reading-capability-v1&manual=provider-input-v2&layout=v2", 0),
    () => loadOptionalClassicScript("./js/panels/provider-tree.js?v=20260804-private-reading-capability-v1&manual=provider-input-v2&layout=v2", 1),
    () => loadOptionalClassicScript("./js/panels/provider-tree.js?v=20260804-private-reading-capability-v1&manual=provider-input-v2&layout=v2", 2),
  ],
  qzonePanel: [
    () => loadOptionalClassicScript("./js/panels/qzone-panel.js?v=20260810-qzone-classic-loader-v1", 0),
    () => loadOptionalClassicScript("./js/panels/qzone-panel.js?v=20260810-qzone-classic-loader-v1", 1),
    () => loadOptionalClassicScript("./js/panels/qzone-panel.js?v=20260810-qzone-classic-loader-v1", 2),
  ],
};

const optionalModuleGlobals = {
  providerTree: "PrivateCompanionProviderTree",
  qzonePanel: "PrivateCompanionQzonePanel",
};

function loadOptionalModule(name) {
  const globalName = optionalModuleGlobals[name];
  if (globalName && window[globalName]) return Promise.resolve(true);
  const loaders = optionalModuleLoaders[name];
  if (!loaders) return Promise.reject(new Error(`未知页面模块：${name}`));
  if (state.lazyScripts[name]) return state.lazyScripts[name];
  delete state.lazyScriptErrors[name];
  const attempt = Number(state.lazyScriptAttempts[name] || 0);
  const loader = loaders[Math.min(attempt, loaders.length - 1)];
  state.lazyScriptAttempts[name] = attempt + 1;
  const pending = Promise.resolve()
    .then(loader)
    .then(() => {
      if (globalName && !window[globalName]) {
        throw new Error(`页面模块未注册兼容出口：${name}`);
      }
      return true;
    })
    .catch((error) => {
      state.lazyScriptErrors[name] = error?.message || `页面模块加载失败：${name}`;
      if (state.lazyScripts[name] === pending) delete state.lazyScripts[name];
      throw error;
    });
  state.lazyScripts[name] = pending;
  return pending;
}

function runWhenIdle(callback, timeout = 1200) {
  if (typeof window.requestIdleCallback === "function") {
    return window.requestIdleCallback(callback, { timeout });
  }
  return window.setTimeout(callback, Math.min(360, timeout));
}

function cancelIdleTask(handle) {
  if (!handle) return;
  if (typeof window.cancelIdleCallback === "function") {
    window.cancelIdleCallback(handle);
  } else {
    window.clearTimeout(handle);
  }
}

function cancelUserGroupPrefetch() {
  if (state.userGroupPrefetchTimer) {
    window.clearTimeout(state.userGroupPrefetchTimer);
    state.userGroupPrefetchTimer = null;
  }
  if (state.userGroupPrefetchIdleHandle) {
    cancelIdleTask(state.userGroupPrefetchIdleHandle);
    state.userGroupPrefetchIdleHandle = null;
  }
}

function scheduleUserGroupPrefetch(callback, delay = 1600) {
  cancelUserGroupPrefetch();
  state.userGroupPrefetchTimer = window.setTimeout(() => {
    state.userGroupPrefetchTimer = null;
    state.userGroupPrefetchIdleHandle = runWhenIdle(() => {
      state.userGroupPrefetchIdleHandle = null;
      callback();
    }, 1200);
  }, delay);
}

function scheduleDailyOutfitHydration(force = false) {
  const outfit = state.overview?.daily_outfit || {};
  const key = String(outfit.image_data_url || "");
  const image = document.getElementById("dailyOutfitLogo");
  if (!force && key && state.dailyOutfitHydrateKey === key && image?.dataset.source === key) return;
  if (state.dailyOutfitHydrateTimer) cancelIdleTask(state.dailyOutfitHydrateTimer);
  state.dailyOutfitHydrateTimer = runWhenIdle(() => {
    state.dailyOutfitHydrateTimer = null;
    state.dailyOutfitHydrateKey = key;
    hydrateDailyOutfitLogo().catch(() => {});
  }, 1600);
}

function storedPagePersonaId() {
  try {
    return String(sessionStorage.getItem(PAGE_PERSONA_STORAGE_KEY) || "").trim();
  } catch (_error) {
    return "";
  }
}

function selectedPagePersonaId() {
  const selected = String(state.selectedPersonaId || "").trim();
  if (selected) return selected;
  const stored = storedPagePersonaId();
  if (stored) return stored;
  return String(state.multiPersona?.current || "").trim();
}

function persistSelectedPagePersonaId(personaId) {
  const value = String(personaId || "").trim();
  state.selectedPersonaId = value;
  try {
    if (value) sessionStorage.setItem(PAGE_PERSONA_STORAGE_KEY, value);
    else sessionStorage.removeItem(PAGE_PERSONA_STORAGE_KEY);
  } catch (_error) {
    // Embedded WebViews may disable sessionStorage; in-memory state still works.
  }
}

function personaConfigEditingEnabled() {
  const selected = selectedPagePersonaId();
  const primary = String(state.multiPersona?.primary || state.overview?.multi_persona?.primary || "").trim();
  return Boolean(
    state.multiPersona?.enabled
    && selected
    && primary
    && selected !== primary
    && state.personaConfigState
    && state.personaConfigState.persona_id === selected
    && state.personaConfigState.is_primary === false,
  );
}

function personaConfigSource(key) {
  const sources = state.personaConfigState?.sources;
  if (!sources || typeof sources !== "object") return "";
  return String(sources[String(key || "")] || "").trim();
}

function personaConfigIsOverride(key) {
  const identityKeys = new Set([
    "bot_name",
    "plugin_specific_persona_id",
    "persona_id",
    "persona_display_name",
  ]);
  return personaConfigEditingEnabled()
    && !identityKeys.has(String(key || ""))
    && personaConfigSource(key) === "persona";
}

function personaSourceBadgeHtml(key, { compact = false } = {}) {
  if (!state.multiPersona?.enabled || !state.personaConfigState) return "";
  const source = personaConfigSource(key);
  if (!source) return "";
  const isPrimaryPersona = state.personaConfigState?.is_primary === true;
  const label = source === "persona" ? "独立设置" : isPrimaryPersona ? "主人格配置" : "跟随主人格";
  const className = source === "persona" ? "persona-setting-source persona" : "persona-setting-source primary";
  const compactLabel = source === "persona" ? "独立" : isPrimaryPersona ? "主人格" : "跟随";
  return `<span class="${className}" data-persona-setting-source="${escapeHtml(source)}" title="${escapeHtml(label)}">${compact ? compactLabel : label}</span>`;
}

function personaSettingValuesEqual(left, right) {
  if (Object.is(left, right)) return true;
  try {
    return JSON.stringify(left) === JSON.stringify(right);
  } catch (_error) {
    return String(left) === String(right);
  }
}

function personaConfigBaselineValue(key) {
  const settings = state.personaConfigState?.settings;
  if (settings && Object.prototype.hasOwnProperty.call(settings, key) && settings[key] !== "***") return settings[key];
  const overview = state.overview || {};
  if (Object.prototype.hasOwnProperty.call(overview.settings || {}, key)) return overview.settings[key];
  if (Object.prototype.hasOwnProperty.call(overview.features || {}, key)) return overview.features[key];
  if (Object.prototype.hasOwnProperty.call(overview.providers || {}, key)) return overview.providers[key];
  return undefined;
}

function flattenFeatureSavePayload(payload = {}) {
  return {
    ...(payload.features && typeof payload.features === "object" ? payload.features : {}),
    ...(payload.settings && typeof payload.settings === "object" ? payload.settings : {}),
    ...(payload.providers && typeof payload.providers === "object" ? payload.providers : {}),
  };
}

function personaDirtyChangesFromPayload(payload = {}) {
  if (!personaConfigEditingEnabled()) return {};
  const flat = flattenFeatureSavePayload(payload);
  const changes = {};
  Object.entries(flat).forEach(([key, value]) => {
    if (!personaConfigSource(key)) return;
    const baseline = personaConfigBaselineValue(key);
    if (!personaSettingValuesEqual(value, baseline)) changes[key] = cloneFeatureStateValue(value);
  });
  return changes;
}

function personaCommonBaselineValue(section, key) {
  const baseline = state.personaCommonBaseline?.[section];
  if (baseline && Object.prototype.hasOwnProperty.call(baseline, key)) return baseline[key];
  return undefined;
}

function commonDirtyPayloadFromPayload(payload = {}) {
  if (!personaConfigEditingEnabled()) return null;
  const output = { features: {}, settings: {}, providers: {} };
  ["features", "settings", "providers"].forEach((section) => {
    const values = payload?.[section];
    if (!values || typeof values !== "object") return;
    Object.entries(values).forEach(([key, value]) => {
      if (personaConfigSource(key)) return;
      const baseline = personaCommonBaselineValue(section, key);
      if (!personaSettingValuesEqual(value, baseline)) output[section][key] = cloneFeatureStateValue(value);
    });
  });
  return Object.fromEntries(Object.entries(output).filter(([, values]) => Object.keys(values).length));
}

function applyPersonaConfigState(configState, { mergeOverview = true } = {}) {
  if (!configState || typeof configState !== "object") return null;
  state.personaConfigState = configState;
  state.personaConfigError = "";
  if (mergeOverview && state.overview && !configState.is_primary) {
    const settings = { ...(state.overview.settings || {}) };
    const providers = { ...(state.overview.providers || {}) };
    Object.entries(configState.settings || {}).forEach(([key, value]) => {
      // The API redacts sensitive values. Keep the overview value in that
      // case so a read-only refresh can never turn a secret into "***".
      if (value === "***") return;
      settings[key] = cloneFeatureStateValue(value);
      if (isProviderConfigKey(key)) providers[key] = cloneFeatureStateValue(value);
    });
    state.overview.settings = settings;
    state.overview.providers = providers;
    syncFeatureDraftFromOverview(state.overview);
  }
  return configState;
}

async function loadPersonaConfigState(personaId = selectedPagePersonaId(), { render = false } = {}) {
  const selected = String(personaId || "").trim();
  if (!selected || !state.multiPersona?.enabled) {
    state.personaConfigState = null;
    state.personaConfigError = "";
    return null;
  }
  state.personaConfigLoading = true;
  try {
    const result = await fetchJson(`/persona/config-state?persona_id=${encodeURIComponent(selected)}`, { dedupe: false });
    if (selected !== selectedPagePersonaId()) return result;
    applyPersonaConfigState(result);
    if (render) renderConfig();
    return result;
  } catch (error) {
    state.personaConfigState = null;
    state.personaConfigError = error?.message || "读取人格配置状态失败";
    throw error;
  } finally {
    state.personaConfigLoading = false;
  }
}

async function savePersonaScopedFeatureChanges(payload, control = null, successMessage = "已保存人格配置") {
  const changes = personaDirtyChangesFromPayload(payload);
  const commonPayload = commonDirtyPayloadFromPayload(payload);
  if (!Object.keys(changes).length && !commonPayload) return false;
  const personaId = selectedPagePersonaId();
  const expectedRevision = Number(state.personaConfigState?.revision);
  if (Object.keys(changes).length && (!Number.isFinite(expectedRevision) || expectedRevision < 0)) {
    showToast("人格配置版本不可用，请刷新后重试", "error");
    return false;
  }
  setPersonaOperationBusy(true);
  setActionBusy(control, true);
  try {
    let result = null;
    if (Object.keys(changes).length) {
      result = await postJson("/persona/settings/update", {
        persona_id: personaId,
        changes,
        follow_primary_keys: [],
        expected_revision: expectedRevision,
      });
      if (!result || result.ok === false) throw new Error(result?.message || "人格配置保存失败");
      applyPersonaConfigState(result);
    }
    if (commonPayload) {
      const commonResult = await fetchJson("/settings/update", {
        method: "POST",
        body: JSON.stringify(commonPayload),
      });
      if (commonResult && commonResult.plugin && commonResult.features) {
        applyOverviewData(commonResult);
        if (state.personaConfigState) applyPersonaConfigState(state.personaConfigState);
      }
    }
    state.featureDraftBaseline = featureDraftSignature(state.featureDraft || {});
    state.featureDetailDirty = false;
    state.featureAuxiliaryDirty = false;
    state.featureDetailParamDraft = {};
    showToast(successMessage);
    renderConfig();
    return true;
  } catch (error) {
    const message = String(error?.message || error || "人格配置保存失败");
    if (/revision|版本|其他页面修改|冲突/i.test(message)) {
      showToast("人格配置保存冲突，当前草稿已保留；刷新配置状态后再重试", "error");
    } else {
      showToast(`人格配置保存失败：${message}`, "error");
    }
    state.personaConfigError = message;
    return false;
  } finally {
    setActionBusy(control, false);
    syncFeatureFooterAction();
  }
}

async function followPersonaSetting(key, control = null) {
  const settingKey = String(key || "").trim();
  if (!settingKey || !personaConfigIsOverride(settingKey)) return false;
  const expectedRevision = Number(state.personaConfigState?.revision);
  if (!Number.isFinite(expectedRevision) || expectedRevision < 0) {
    showToast("人格配置版本不可用，请刷新后重试", "error");
    return false;
  }
  setActionBusy(control, true);
  try {
    const result = await postJson("/persona/settings/update", {
      persona_id: selectedPagePersonaId(),
      changes: {},
      follow_primary_keys: [settingKey],
      expected_revision: expectedRevision,
    });
    if (!result || result.ok === false) throw new Error(result?.message || "恢复跟随失败");
    applyPersonaConfigState(result);
    showToast("已恢复跟随主人格");
    renderConfig();
    return true;
  } catch (error) {
    const message = String(error?.message || error || "恢复跟随失败");
    showToast(/revision|版本|其他页面修改|冲突/i.test(message) ? "恢复跟随发生版本冲突，草稿已保留" : `恢复跟随失败：${message}`, "error");
    return false;
  } finally {
    setActionBusy(control, false);
    setPersonaOperationBusy(false);
  }
}

function scopePagePersonaRequest(path, options, method) {
  const selectedPersonaId = selectedPagePersonaId();
  if (/^\/(?:persona\/(?:migrate|config-state|config\/create|settings\/update|config\/detach-(?:preview|apply))|roleplay\/personas)(?:[/?]|$)/.test(path)) {
    return { path, options };
  }
  if (method === "GET") {
    if (!selectedPersonaId) return { path, options };
    const url = new URL(path, "https://astrbot-plugin-page.local/");
    url.searchParams.set("_persona_id", selectedPersonaId);
    return { path: `${url.pathname}${url.search}`, options };
  }
  let payload = options.body || {};
  if (typeof payload === "string") {
    try {
      payload = JSON.parse(payload || "{}");
    } catch (_error) {
      payload = {};
    }
  }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) payload = {};
  const personaId = String(payload._persona_id || selectedPersonaId || "").trim();
  if (!personaId) return { path, options };
  return {
    path,
    options: { ...options, body: JSON.stringify({ ...payload, _persona_id: personaId }) },
  };
}

function personaScopedPostPayload(path, body) {
  if (path !== "/settings/update" || !personaConfigEditingEnabled()) return null;
  let payload = body;
  if (typeof payload === "string") {
    try { payload = JSON.parse(payload || "{}"); } catch (_error) { return null; }
  }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return null;
  const flat = flattenFeatureSavePayload(payload);
  const keys = Object.keys(flat);
  if (!keys.length || keys.some((key) => !personaConfigSource(key))) return null;
  const changes = personaDirtyChangesFromPayload(payload);
  if (!Object.keys(changes).length) return { skipped: true };
  const revision = Number(state.personaConfigState?.revision);
  if (!Number.isFinite(revision) || revision < 0) throw new Error("人格配置版本不可用，请刷新后重试");
  return {
    persona_id: selectedPagePersonaId(),
    changes,
    follow_primary_keys: [],
    expected_revision: revision,
  };
}

function fetchJson(path, options = {}) {
  const requestOptions = { ...options };
  const dedupe = requestOptions.dedupe !== false;
  delete requestOptions.dedupe;
  const method = (requestOptions.method || "GET").toUpperCase();
  const scoped = scopePagePersonaRequest(path, requestOptions, method);
  const requestKey = method === "GET" && dedupe ? `${method}:${scoped.path}` : "";
  if (requestKey && inFlightGetRequests.has(requestKey)) {
    return inFlightGetRequests.get(requestKey);
  }
  const request = performJsonRequest(scoped.path, scoped.options, method);
  if (!requestKey) return request;
  const trackedRequest = request.finally(() => {
    if (inFlightGetRequests.get(requestKey) === trackedRequest) {
      inFlightGetRequests.delete(requestKey);
    }
  });
  inFlightGetRequests.set(requestKey, trackedRequest);
  return trackedRequest;
}

async function performJsonRequest(path, options, method) {
  const bridge = await getReadyPageBridge();
  let payload;

  if (bridge && typeof bridge.apiGet === "function" && typeof bridge.apiPost === "function") {
    payload = await bridgeRequest(bridge, path, method, options.body);
  } else if (isHttpApiMode()) {
    const response = await fetch(httpApiRequestUrl(path), {
      cache: "no-store",
      credentials: "same-origin",
      headers: options.body ? { "Content-Type": "application/json" } : undefined,
      ...options,
    });
    const text = await response.text();
    try {
      payload = text ? JSON.parse(text) : {};
    } catch (error) {
      throw new Error(response.ok ? "返回内容不是 JSON" : `HTTP ${response.status}: ${text.slice(0, 120)}`);
    }
    if (!response.ok) throw new Error(payload.error || `HTTP ${response.status}`);
  } else {
    throw new Error("未检测到 AstrBot 官方插件 Page 桥接，请从 AstrBot 后台的插件拓展页打开");
  }

  payload = normalizeResponse(payload);
  if (!payload.success) throw new Error(payload.error || "请求失败");
  return payload.data;
}

function getBridge() {
  if (window.AstrBotPluginPage) return window.AstrBotPluginPage;
  try {
    if (window.parent && window.parent !== window && window.parent.AstrBotPluginPage) {
      return window.parent.AstrBotPluginPage;
    }
  } catch (error) {
    return null;
  }
  return null;
}

function isDebugHttpMode() {
  return new URLSearchParams(window.location.search).get("debug_http") === "1";
}

function standaloneRuntimeConfig() {
  const standalone = window.__PRIVATE_COMPANION_STANDALONE__;
  if (standalone === true) return {};
  if (standalone && typeof standalone === "object") return standalone;

  const candidates = [
    window.__PRIVATE_COMPANION_WEBUI__,
    window.__PRIVATE_COMPANION_WEBUI_CONFIG__,
  ];
  return candidates.find((candidate) => {
    if (!candidate || typeof candidate !== "object") return false;
    return candidate.standalone === true || String(candidate.mode || "").toLowerCase() === "standalone";
  }) || null;
}

function isStandaloneHttpMode() {
  if (standaloneHttpModeDetected !== undefined) return standaloneHttpModeDetected;
  if (standaloneRuntimeConfig()) {
    standaloneHttpModeDetected = true;
    return standaloneHttpModeDetected;
  }
  const mode = document.querySelector(`meta[name="${STANDALONE_MODE_META}"]`)?.content;
  standaloneHttpModeDetected = String(mode || "").trim().toLowerCase() === "standalone";
  return standaloneHttpModeDetected;
}

function isHttpApiMode() {
  return isStandaloneHttpMode() || isDebugHttpMode();
}

function standaloneHttpApiBase() {
  const config = standaloneRuntimeConfig() || {};
  const configured = config.apiBase || config.api_base;
  const metaBase = document.querySelector(`meta[name="${STANDALONE_API_BASE_META}"]`)?.content;
  return String(configured || metaBase || STANDALONE_HTTP_API).trim() || STANDALONE_HTTP_API;
}

function httpApiRequestUrl(path) {
  const base = isStandaloneHttpMode() ? standaloneHttpApiBase() : HTTP_API;
  return `${String(base).replace(/\/+$/, "")}/${String(path || "").replace(/^\/+/, "")}`;
}

function pageApiAssetUrl(value) {
  const raw = String(value || "").trim();
  if (!raw || !isStandaloneHttpMode() || /^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(raw)) return raw;
  const base = standaloneHttpApiBase().replace(/\/+$/, "");
  if (raw === base || raw.startsWith(`${base}/`)) return raw;
  if (raw === HTTP_API || raw.startsWith(`${HTTP_API}/`)) {
    return `${base}${raw.slice(HTTP_API.length)}`;
  }
  return `${base}/${raw.replace(/^\/+/, "")}`;
}

function isUsableBridge(bridge) {
  return Boolean(bridge && typeof bridge.apiGet === "function" && typeof bridge.apiPost === "function");
}

async function getPageBridge(timeoutMs = 2500) {
  if (isUsableBridge(cachedPageBridge)) return cachedPageBridge;

  const bridge = getBridge();
  if (isUsableBridge(bridge)) {
    cachedPageBridge = bridge;
    return cachedPageBridge;
  }

  if (isHttpApiMode()) return null;

  if (!pageBridgeProbePromise) {
    pageBridgeProbePromise = waitForBridge(timeoutMs)
      .then((resolvedBridge) => {
        if (isUsableBridge(resolvedBridge)) {
          cachedPageBridge = resolvedBridge;
          return cachedPageBridge;
        }
        return null;
      })
      .finally(() => {
        pageBridgeProbePromise = null;
      });
  }

  return pageBridgeProbePromise;
}

async function getReadyPageBridge(timeoutMs = 2500) {
  if (isHttpApiMode()) return null;
  const bridge = await getPageBridge(timeoutMs);
  if (!bridge || typeof bridge.ready !== "function") return bridge;
  if (!pageBridgeReadyPromise) {
    pageBridgeReadyPromise = Promise.resolve()
      .then(() => bridge.ready())
      .then(() => {
        cachedPageBridge = bridge;
        return bridge;
      })
      .catch((error) => {
        pageBridgeReadyPromise = null;
        throw error;
      });
  }
  return pageBridgeReadyPromise;
}

async function waitForBridge(timeoutMs = 2500) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const bridge = getBridge();
    if (bridge && typeof bridge.apiGet === "function" && typeof bridge.apiPost === "function") {
      return bridge;
    }
    await new Promise((resolve) => setTimeout(resolve, 80));
  }
  return getBridge();
}

async function bridgeRequest(bridge, path, method, body) {
  const url = new URL(path, "https://astrbot-plugin-page.local/");
  const routePath = url.pathname.replace(/^\/+/, "");
  const endpointCandidates = bridgeEndpointCandidates(routePath);
  const errors = [];

  if (method === "GET") {
    const params = Object.fromEntries(url.searchParams.entries());
    for (const candidate of endpointCandidates) {
      try {
        const payload = await bridge.apiGet(candidate.endpoint, Object.keys(params).length ? params : undefined);
        if (isRouteMissingPayload(payload)) {
          errors.push(payload.message || payload.error || "未找到该路由");
          continue;
        }
        cachedPageEndpointStyle = candidate.style;
        return payload;
      } catch (error) {
        if (isRouteMissingError(error)) {
          errors.push(error.message || String(error));
          continue;
        }
        throw error;
      }
    }
    throw new Error(errors[0] || "未找到可用的页面 API 路由");
  }

  let payload = body || {};
  if (typeof payload === "string") {
    try {
      payload = JSON.parse(payload);
    } catch (error) {
      payload = {};
    }
  }
  for (const candidate of endpointCandidates) {
    try {
      const result = await bridge.apiPost(candidate.endpoint, payload);
      if (isRouteMissingPayload(result)) {
        errors.push(result.message || result.error || "未找到该路由");
        continue;
      }
      cachedPageEndpointStyle = candidate.style;
      return result;
    } catch (error) {
      if (isRouteMissingError(error)) {
        errors.push(error.message || String(error));
        continue;
      }
      throw error;
    }
  }
  throw new Error(errors[0] || "未找到可用的页面 API 路由");
}

function normalizeResponse(payload) {
  if (payload && typeof payload === "object" && Object.prototype.hasOwnProperty.call(payload, "success")) {
    return payload;
  }
  if (payload && typeof payload === "object") {
    const status = String(payload.status || "").trim().toLowerCase();
    if (["error", "fail", "failed"].includes(status) || payload.ok === false) {
      return {
        success: false,
        error: payload.message || payload.error || "请求失败",
        data: payload.data || {},
      };
    }
  }
  return { success: true, data: payload };
}

function bridgeEndpointCandidates(routePath) {
  const cleanRoute = String(routePath || "").replace(/^\/+/, "");
  const byStyle = {
    cached: cachedPageEndpointStyle ? endpointForStyle(cachedPageEndpointStyle, cleanRoute) : "",
    page: `${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`,
    bare: cleanRoute,
    slash: `/${cleanRoute}`,
    full: `${PAGE_PLUGIN_NAME}/${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`,
    fullSlash: `/${PAGE_PLUGIN_NAME}/${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`,
  };
  const ordered = [
    ["cached", byStyle.cached],
    ["page", byStyle.page],
    ["bare", byStyle.bare],
    ["slash", byStyle.slash],
    ["full", byStyle.full],
    ["fullSlash", byStyle.fullSlash],
  ];
  const seen = new Set();
  return ordered
    .map(([style, endpoint]) => ({ style: style === "cached" ? cachedPageEndpointStyle : style, endpoint: String(endpoint || "").replace(/\/+/g, "/") }))
    .filter((item) => item.style && item.endpoint && !seen.has(item.endpoint) && seen.add(item.endpoint));
}

function endpointForStyle(style, routePath) {
  const cleanRoute = String(routePath || "").replace(/^\/+/, "");
  switch (style) {
    case "page":
      return `${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`;
    case "bare":
      return cleanRoute;
    case "slash":
      return `/${cleanRoute}`;
    case "full":
      return `${PAGE_PLUGIN_NAME}/${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`;
    case "fullSlash":
      return `/${PAGE_PLUGIN_NAME}/${PAGE_ENDPOINT_PREFIX}/${cleanRoute}`;
    default:
      return "";
  }
}

function isRouteMissingPayload(payload) {
  if (!payload || typeof payload !== "object") return false;
  const text = `${payload.error || ""} ${payload.message || ""} ${payload.detail || ""}`.toLowerCase();
  return /未找到.*路由|route.*not.*found|not.*found.*route|404/.test(text);
}

function isRouteMissingError(error) {
  const text = String(error?.message || error || "").toLowerCase();
  return /未找到.*路由|route.*not.*found|not.*found.*route|http\s*404|\b404\b/.test(text);
}

function postJson(path, body) {
  const personaPayload = personaScopedPostPayload(path, body);
  if (personaPayload) {
    if (personaPayload.skipped) return Promise.resolve({ ok: true, skipped: true });
    return fetchJson("/persona/settings/update", { method: "POST", body: JSON.stringify(personaPayload) });
  }
  return fetchJson(path, { method: "POST", body: JSON.stringify(body) });
}

function promiseWithTimeout(promise, timeoutMs, message = "请求超时") {
  const limit = Number(timeoutMs);
  if (!Number.isFinite(limit) || limit <= 0) return promise;
  let timer = null;
  const timeout = new Promise((_, reject) => {
    timer = window.setTimeout(() => reject(new Error(message)), limit);
  });
  return Promise.race([Promise.resolve(promise), timeout]).finally(() => {
    if (timer !== null) window.clearTimeout(timer);
  });
}

function downloadJson(filename, data) {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function unwrapConfigPackagePayload(value) {
  let current = value;
  for (let index = 0; index < 8; index += 1) {
    if (!current || typeof current !== "object" || Array.isArray(current)) return current;
    if (current.kind === "private_companion_config_backup" || (current.overview && (current.users || current.groups))) return current;
    const next = current.package || current.data || current.payload || current.result;
    if (!next || typeof next !== "object" || Array.isArray(next) || next === current) return current;
    current = next;
  }
  return current;
}

function formatBackupTime(value) {
  const timestamp = Number(value || 0);
  if (!timestamp) return "未知时间";
  return new Date(timestamp * 1000).toLocaleString();
}

function selectedConfigExportSections() {
  const sections = [...document.querySelectorAll("[data-export-section]")]
    .filter((input) => input.checked)
    .map((input) => input.dataset.exportSection)
    .filter(Boolean);
  return sections.length ? sections : ["basic", "relations", "food_skills"];
}

function allowConfigChecksumMismatch() {
  return Boolean($("#configAllowChecksumMismatch")?.checked);
}

function migrationDiffText(item) {
  const added = Number(item?.added || 0);
  const overwritten = Number(item?.overwritten || 0);
  const unchanged = Number(item?.unchanged || 0);
  return `新增 ${added} · 覆盖 ${overwritten} · 不变 ${unchanged}`;
}

function migrationSectionLabel(value) {
  return {
    basic: "基础配置",
    relations: "关系/群资料",
    food_skills: "候选菜单/技能",
    providers: "模型配置",
    sensitive: "敏感配置",
  }[value] || value;
}

function migrationLevelText(level) {
  return {
    ok: "正常",
    warn: "注意",
    error: "错误",
    unknown: "未知",
  }[level] || "提示";
}

function renderConfigBackups() {
  const box = $("#configBackupList");
  if (!box) return;
  const items = Array.isArray(state.configBackups) ? state.configBackups : [];
  if (!items.length) {
    box.innerHTML = "暂无自动备份。";
    return;
  }
  box.innerHTML = items.map((item) => {
    const sections = Array.isArray(item.included_sections) && item.included_sections.length
      ? item.included_sections.map(migrationSectionLabel).join("、")
      : "旧备份";
    const checksum = item.checksum_ok ? "校验通过" : "未校验";
    return `
      <div class="migration-backup-item">
        <div>
          <b>${escapeHtml(item.name || item.id)}</b>
          <span>${escapeHtml(formatBackupTime(item.exported_at || item.mtime))} · ${escapeHtml(item.version || "未知版本")} · ${escapeHtml(checksum)}</span>
          <small>${escapeHtml(sections)}</small>
        </div>
        <button type="button" data-config-restore="${escapeHtml(item.id)}">恢复</button>
      </div>
    `;
  }).join("");
}

function renderConfigImportChecks() {
  const box = $("#configImportChecks");
  if (!box) return;
  const checks = Array.isArray(state.configLastChecks) ? state.configLastChecks : [];
  if (!checks.length) {
    box.innerHTML = "导入后会在这里显示轻量检查结果。";
    return;
  }
  box.innerHTML = checks.map((item) => `
    <div class="migration-check-item ${escapeHtml(item.level || "ok")}">
      <b>${escapeHtml(item.title || migrationLevelText(item.level))}</b>
      <span>${escapeHtml(item.detail || "")}</span>
    </div>
  `).join("");
}

function renderConfigMigrationPreview() {
  const box = $("#configMigrationPreview");
  if (!box) return;
  const modeSelect = $("#configImportMode");
  const conflictSelect = $("#configImportConflict");
  if (conflictSelect) {
    conflictSelect.disabled = (modeSelect?.value || "merge") === "replace";
  }
  const preview = state.configImportPreview;
  if (!state.configImportPackage) {
    box.innerHTML = "还没有选择备份或快照文件。";
    $("#previewConfigImportBtn").disabled = true;
    $("#applyConfigImportBtn").disabled = true;
    return;
  }
  $("#previewConfigImportBtn").disabled = false;
  $("#applyConfigImportBtn").disabled = !preview;
  if (!preview) {
    box.innerHTML = "已选择备份/快照文件，先点“预览导入”看看会改动哪些内容。";
    return;
  }
  const sections = Array.isArray(preview.sections) ? preview.sections : [];
  if (preview.legacy_snapshot && modeSelect && modeSelect.value === "replace") {
    modeSelect.value = "merge";
    if (conflictSelect) conflictSelect.disabled = false;
  }
  const sectionHtml = sections.length
    ? sections.map((item) => `
        <span>
          <b>${escapeHtml(item.label || item.key)}</b>
          ${Number(item.count || 0)} 条
          <small>${escapeHtml(migrationDiffText(item))}</small>
        </span>
      `).join("")
    : "<em>没有可迁移资料段</em>";
  const configDiff = preview.config_diff || {};
  const compatibility = preview.compatibility || {};
  const checksumLine = preview.checksum
    ? (preview.checksum_ok ? "文件校验：通过" : (preview.checksum_bypassed ? "文件校验：失败，已按风险选项继续" : "文件校验：失败"))
    : "文件校验：旧备份未提供";
  const checksumWarn = preview.checksum_bypassed
    ? `<p class="migration-warn">这份备份的校验值与当前内容不一致。仅当你确认文件只是被手动脱敏或删改敏感字段、且 JSON 内容完整时，才继续导入。</p>`
    : "";
  const compatibilityHtml = `
    <p class="migration-note">
      备份来自 ${escapeHtml(compatibility.backup_version || preview.version || "未知")}，当前版本 ${escapeHtml(compatibility.current_version || preview.current_version || "未知")}。
      ${escapeHtml(compatibility.message || "")}
    </p>
    <p class="${compatibility.level === "warn" || preview.checksum_bypassed ? "migration-warn" : "migration-note"}">${escapeHtml(checksumLine)}</p>
    ${checksumWarn}
  `;
  const included = Array.isArray(preview.included_sections) && preview.included_sections.length
    ? `<p class="migration-note">备份包含：${escapeHtml(preview.included_sections.map(migrationSectionLabel).join("、"))}</p>`
    : "";
  const legacy = preview.legacy_snapshot
    ? `<p class="migration-warn">这是旧版页面快照，只会按合并方式导入可识别的配置、名单、开关和模型指向；页面里的私聊/群聊摘要不会写回数据文件。</p>`
    : "";
  const ignored = Array.isArray(preview.ignored) && preview.ignored.length
    ? `<p class="migration-warn">已忽略 ${preview.ignored.length} 个未知字段：${escapeHtml(preview.ignored.slice(0, 8).join("、"))}</p>`
    : "";
  box.innerHTML = `
    <div class="migration-preview-top">
      <b>备份版本 ${escapeHtml(preview.version || "未知")}</b>
      <span>${escapeHtml(formatBackupTime(preview.exported_at))}</span>
    </div>
    <div class="migration-counts">
      <span>配置 ${Number(preview.config_count || 0)} 项 <small>${escapeHtml(migrationDiffText(configDiff))}</small></span>
      <span>开关 ${Number(preview.features_count || 0)} 项</span>
      <span>模型 ${Number(preview.providers_count || 0)} 项</span>
    </div>
    <div class="migration-section-list">${sectionHtml}</div>
    ${compatibilityHtml}
    ${included}
    ${legacy}
    ${ignored}
    <p class="migration-note">导入前会自动保存当前可迁移配置；Token、缓存、最近消息、审计日志和临时队列不会导入。</p>
  `;
}

async function handleConfigExport() {
  const params = new URLSearchParams();
  params.set("sections", selectedConfigExportSections().join(","));
  const data = await fetchJson(`/config/export?${params.toString()}`);
  const date = new Date().toISOString().slice(0, 10);
  downloadJson(`private-companion-config-${date}.json`, data);
  showToast("配置备份已导出");
}

async function readConfigImportFile(file) {
  const text = await file.text();
  let data = null;
  try {
    data = JSON.parse(text.replace(/^\uFEFF/, ""));
  } catch (error) {
    throw new Error("备份文件不是有效 JSON");
  }
  state.configImportPackage = unwrapConfigPackagePayload(data);
  state.configImportPreview = null;
  renderConfigMigrationPreview();
  showToast("备份/快照文件已读取，请先预览");
}

async function previewConfigImport() {
  if (!state.configImportPackage) {
    showToast("请先选择备份文件", "error");
    return;
  }
  const result = await postJson("/config/import/preview", {
    package: state.configImportPackage,
    allow_checksum_mismatch: allowConfigChecksumMismatch(),
  });
  state.configImportPreview = result;
  renderConfigMigrationPreview();
  showToast("预览完成");
}

async function applyConfigImport() {
  if (!state.configImportPackage || !state.configImportPreview) {
    showToast("请先预览备份内容", "error");
    return;
  }
  const mode = state.configImportPreview?.legacy_snapshot ? "merge" : ($("#configImportMode")?.value || "merge");
  const conflict = $("#configImportConflict")?.value || "use_backup";
  const conflictText = {
    use_backup: "使用备份内容",
    keep_current: "保留当前内容",
    fill_empty: "只补当前空字段",
  }[conflict] || "使用备份内容";
  const message = mode === "replace"
    ? "将覆盖可迁移资料段。已确认要继续吗？"
    : `将合并导入备份内容，字段冲突时：${conflictText}。已确认要继续吗？`;
  if (state.configImportPreview?.checksum_bypassed && !allowConfigChecksumMismatch()) {
    showToast("这份备份校验失败，确认导入前需要保持风险选项勾选", "error");
    return;
  }
  const finalMessage = state.configImportPreview?.checksum_bypassed
    ? `${message}\n\n注意：这份备份校验失败，只建议在确认它只是被手动脱敏/删改敏感字段时继续。`
    : message;
  if (!window.confirm(finalMessage)) return;
  const result = await postJson("/config/import/apply", {
    package: state.configImportPackage,
    mode,
    conflict,
    allow_checksum_mismatch: allowConfigChecksumMismatch(),
  });
  if (!actionResultPersisted(result)) return result;
  state.configImportPreview = null;
  renderConfigMigrationPreview();
  state.configBackups = result.migration_backups || state.configBackups;
  state.configLastChecks = result.post_import_checks || [];
  return result;
}

async function restoreConfigBackup(id) {
  const backupId = String(id || "").trim();
  if (!backupId) return;
  if (!window.confirm(`将从自动备份恢复：${backupId}\n恢复前也会再次备份当前状态。继续吗？`)) return;
  const result = await postJson("/config/restore", { id: backupId });
  if (!actionResultPersisted(result)) return result;
  state.configBackups = result.migration_backups || state.configBackups;
  state.configLastChecks = result.post_import_checks || [];
  return result;
}

async function loadImageCache({ clampPage = true } = {}) {
  const params = new URLSearchParams();
  const pageSize = Math.max(1, Number(state.imageCachePageSize || 36));
  const page = Math.max(1, Number(state.imageCachePage || 1));
  params.set("limit", String(pageSize));
  params.set("offset", String((page - 1) * pageSize));
  if (state.imageCacheFilter) params.set("q", state.imageCacheFilter);
  if (state.imageCacheScope && state.imageCacheScope !== "all") params.set("scope", state.imageCacheScope);
  const requestSeq = ++state.imageCacheRequestSeq;
  const data = await fetchJson(`/image_cache/list?${params.toString()}`);
  if (requestSeq !== state.imageCacheRequestSeq) return data;
  state.imageCacheItems = Array.isArray(data.items) ? data.items : [];
  state.imageCacheTotal = Number(data.total || 0);
  state.imageCacheScopes = Array.isArray(data.scopes) ? data.scopes : [];
  state.imageCacheLoaded = true;
  const totalPages = Math.max(1, Math.ceil(state.imageCacheTotal / pageSize));
  if (clampPage && state.imageCachePage > totalPages) {
    state.imageCachePage = totalPages;
    return loadImageCache({ clampPage: false });
  }
  if (state.selectedImageCacheKey && !state.imageCacheItems.some((item) => item.key === state.selectedImageCacheKey)) {
    state.selectedImageCacheKey = "";
  }
  if (!state.selectedImageCacheKey && state.imageCacheItems[0]) {
    state.selectedImageCacheKey = state.imageCacheItems[0].key;
  }
  renderImageCache();
  return data;
}

async function loadOwnedReactionAssets() {
  const data = await fetchJson("/reaction_assets/list");
  state.ownedReactionAssets = data || { items: [] };
  if (state.activeTab === "image-cache") renderOwnedReactionAssets();
  return data;
}

async function goToImageCachePage(targetPage) {
  const pageSize = Math.max(1, Number(state.imageCachePageSize || 36));
  const pages = Math.max(1, Math.ceil(Number(state.imageCacheTotal || 0) / pageSize));
  const nextPage = Math.min(pages, Math.max(1, Number(targetPage) || 1));
  if (nextPage === state.imageCachePage) return;
  state.imageCachePage = nextPage;
  await loadImageCache();
  $("#imageCacheList")?.scrollTo({ top: 0, behavior: "smooth" });
}

async function loadTroubleshooting(options = {}) {
  const { silent = false, skipExperimentalRender = false } = options;
  const [data, overview] = await Promise.all([
    fetchJson("/troubleshooting"),
    fetchJson("/overview").catch(() => null),
  ]);
  state.troubleshooting = data || null;
  if (overview) {
    state.overview = overview;
    syncExternalCompanionVisibility();
    syncFeatureDraftFromOverview(overview);
  }
  if (!silent) renderTroubleshooting();
  if (state.activeTab === "experimental" && !skipExperimentalRender) renderExperimentalPage();
  return data;
}

async function loadDailyReview(force = false) {
  if (state.lazyLoaded.dailyReview && !force && state.dailyReview) return state.dailyReview;
  const data = await fetchJson("/daily-review");
  state.dailyReview = data || null;
  state.lazyLoaded.dailyReview = true;
  if (state.activeTab === "experimental" && state.experimentalSubpage === "daily-review") renderDailyReview();
  return data;
}

async function loadRealityTouch(force = false) {
  if (!realityCompanionInstalled()) {
    state.realityTouch = null;
    state.realityTouchError = "";
    return null;
  }
  if (state.realityTouchLoading && !force) return state.realityTouch;
  if (state.realityTouch && !force) return state.realityTouch;
  state.realityTouchLoading = true;
  state.realityTouchError = "";
  if (state.activeTab === "reality") {
    renderRealityTouchPage();
  }
  try {
    const data = await fetchJson("/reality-touch");
    state.realityTouch = data || null;
    syncRealityTouchOverviewState(state.realityTouch);
    const users = Array.isArray(data?.users) ? data.users : [];
    if (!users.some((item) => String(item.user_id) === String(state.realityTouchSelectedUserId))) {
      state.realityTouchSelectedUserId = String(users[0]?.user_id || "");
    }
    return data;
  } catch (error) {
    state.realityTouchError = error.message || "读取现实触及状态失败";
    throw error;
  } finally {
    state.realityTouchLoading = false;
    if (state.activeTab === "reality") {
      renderRealityTouchPage();
    }
  }
}

function syncRealityTouchOverviewState(snapshot = null) {
  if (!snapshot || typeof snapshot !== "object") return;
  const enabled = Boolean(snapshot.global_enabled ?? snapshot.configuration?.enabled);
  const pluginStatus = state.overview?.companion_plugins?.reality;
  if (pluginStatus && typeof pluginStatus === "object") pluginStatus.enabled = enabled;
  state.featureDraft = state.featureDraft || {};
  state.featureDraft.enable_experimental_bluetooth_wakeup = enabled;
  if (state.overview?.features) {
    state.overview.features.enable_experimental_bluetooth_wakeup = enabled;
  }
}

function applyOverviewData(overview) {
  if (overview?.multi_persona && typeof overview.multi_persona === "object") {
    const enabled = Boolean(overview.multi_persona.enabled);
    const current = enabled ? selectedPagePersonaId() : "";
    state.multiPersona = {
      ...state.multiPersona,
      ...overview.multi_persona,
      current: enabled ? (current || overview.multi_persona.current || overview.multi_persona.primary || "") : "",
    };
    if (!enabled) persistSelectedPagePersonaId("");
  }
  const activePersonaId = activeBookshelfPersonaId();
  if (state.bookshelfUnlocked && activePersonaId && state.bookshelfPersonaId !== activePersonaId) {
    setBookshelfUnlocked(null);
    state.bookshelfAccessToken = "";
    resetBookshelfSelection();
  }
  const currentUnlockedBookshelf = bookshelfUnlockedForCurrentPersona();
  const unlockedBooks = Array.isArray(currentUnlockedBookshelf?.secret_books)
    ? currentUnlockedBookshelf.secret_books
    : null;
  const overviewBookshelfCount = Number(overview?.bookshelf?.jm_album_count);
  const unlockedBookshelfCount = unlockedBooks
    ? unlockedBooks.filter((item) => item?.kind === "jm_album").length
    : 0;
  if (
    currentUnlockedBookshelf?.unlocked
    && Number.isFinite(overviewBookshelfCount)
    && unlockedBookshelfCount !== overviewBookshelfCount
  ) {
    setBookshelfUnlocked(null);
    clearBookshelfAccessToken();
    resetBookshelfSelection();
  }
  state.overview = overview;
  syncExternalCompanionVisibility();
  if (!state.setupGuideOpen) {
    state.setupGuideDraft = null;
    state.setupGuideProviderTests = {};
  }
  const overviewMemoNotes = overview?.bookshelf?.memo_notes;
  if (overviewMemoNotes && typeof overviewMemoNotes === "object") {
    state.memoNotes = overviewMemoNotes;
    state.lazyLoaded.memoNotes = true;
  }
  // 总览是服务端权威值；旧草稿继续覆盖它会让已切换的模型看起来没有刷新。
  state.providerDraft = {};
  state.ttsProviderDraft = {};
  hydrateTokenStatsFromOverview(overview);
  syncFeatureDraftFromOverview(overview);
  state.personaCommonBaseline = state.multiPersona?.enabled && selectedPagePersonaId()
    ? {
      settings: cloneFeatureStateValue(overview.settings || {}),
      features: cloneFeatureStateValue(overview.features || {}),
      providers: cloneFeatureStateValue(overview.providers || {}),
    }
    : null;
  state.imageApiEndpointDraft = null;
  state.imageApiEndpointSavedFingerprints = photoApiEndpointInitialList(overview?.settings || {})
    .map((endpoint, index) => photoApiEndpointFingerprint(endpoint, index));
  state.providerConfigMode = inferProviderConfigMode(overview);
  state.providerTimeoutDraft = normalizeModelTimeoutOverrides(overview?.settings?.model_timeout_overrides);
  state.providerTokenLimitDraft = normalizeModelTokenLimitOverrides(overview?.settings?.model_token_limit_overrides);
  state.providerFallbackDraft = normalizeModelFallbackOverrides(overview?.settings?.model_fallback_overrides);
  state.pageFontFamily = normalizePageFontFamily(overview?.settings?.page_font_family);
  state.pageTheme = normalizePageTheme(overview?.settings?.page_theme);
  applyPageFontFamily();
  applyPageTheme();
}

function applyPageFontFamily() {
  return window.PrivateCompanionAppearance?.applyFontFamily(state.pageFontFamily) || normalizePageFontFamily(state.pageFontFamily);
}

function normalizePageFontFamily(value) {
  if (window.PrivateCompanionAppearance?.normalizeFontFamily) {
    return window.PrivateCompanionAppearance.normalizeFontFamily(value);
  }
  const font = String(value || "original").trim().toLowerCase();
  return ["original", "yahei", "dengxian", "source_han", "simsun", "kaiti", "fangsong", "cheng"].includes(font)
    ? font
    : "original";
}

async function savePageFontFamily(value) {
  const next = normalizePageFontFamily(value);
  const previous = state.pageFontFamily;
  state.pageFontFamily = next;
  applyPageFontFamily();
  try {
    const result = await postJson("/settings/update", { settings: { page_font_family: next } });
    const persistenceFailed = configPersistenceFailed(result);
    showToast(persistenceFailed ? "页面字体已应用，但配置持久化失败；重启后可能恢复旧值" : "页面字体已保存", persistenceFailed ? "error" : "success");
  } catch (error) {
    state.pageFontFamily = previous;
    applyPageFontFamily();
    showToast(`字体保存失败：${error.message}`, "error");
  }
}

const PAGE_THEMES = [
  { value: "classic", label: "经典蓝", swatch: ["#eef3fb", "#1a4b8c", "#2c6cb0"] },
  { value: "warm", label: "暖阳书房", swatch: ["#faf5ef", "#b86b2e", "#c0793c"] },
  { value: "forest", label: "森林绿径", swatch: ["#eef4ee", "#2d6a4f", "#40916c"] },
  { value: "sakura", label: "樱粉日记", swatch: ["#fdf0f3", "#d4517a", "#fce8ed"] },
  { value: "ocean", label: "深海渐变", swatch: ["#0a1929", "#00b4d8", "#0077b6"] },
  { value: "lavender", label: "薰衣草", swatch: ["#f5f0fa", "#7c5cbf", "#a78bda"] },
  { value: "ink", label: "水墨黑白", swatch: ["#f8f8f6", "#1a1a1a", "#4a4a4a"] },
  { value: "sunset", label: "日落晚霞", swatch: ["#fff4e6", "#e85d3c", "#f4a261"] },
];

function normalizePageTheme(raw) {
  const allowed = PAGE_THEMES.map((t) => t.value);
  const text = String(raw || "classic").trim().toLowerCase();
  return allowed.includes(text) ? text : "classic";
}

function applyPageTheme() {
  const theme = normalizePageTheme(state.pageTheme);
  document.documentElement.dataset.theme = theme;
  try { localStorage.setItem("pc_theme", theme); } catch (e) {}
}

function renderAppearanceSettings() {
  const current = normalizePageTheme(state.pageTheme);
  const grid = document.getElementById("appearanceThemeGrid");
  if (grid) {
    grid.innerHTML = PAGE_THEMES.map((t) => {
      const swatches = t.swatch.map((c) => `<span style="background:${c}"></span>`).join("");
      return `<div class="appearance-theme-option${t.value === current ? " is-active" : ""}" data-theme-value="${t.value}" role="radio" aria-checked="${t.value === current}" tabindex="0">
        <div class="appearance-theme-swatch">${swatches}</div>
        <div class="appearance-theme-label"><span>${escapeHtml(t.label)}</span></div>
      </div>`;
    }).join("");
  }
}

function applyUserGroupLists(users, groups) {
  state.users = Array.isArray(users?.items) ? users.items : [];
  state.groups = Array.isArray(groups?.items) ? groups.items : [];
  state.userGroupListError = "";
  if (!state.selectedUserId && state.users[0]) state.selectedUserId = state.users[0].user_id;
  if (!state.selectedGroupId && state.groups[0]) state.selectedGroupId = state.groups[0].group_id;
}

function renderAfterUserGroupListsLoaded() {
  renderDashboardPulse();
  renderRelationshipChart();
  renderGroupBubbleChart();
  if (state.activeTab === "private") {
    renderUsers();
  } else if (state.activeTab === "learning") {
    renderLearning();
  } else if (state.activeTab === "group") {
    renderGroups();
  } else if (state.activeTab === "memory") {
    renderMemory();
  } else if (state.activeTab === "proactive") {
    renderProactiveCandidates();
  } else if (state.activeTab === "experimental") {
    renderExperimentalPage();
  }
}

async function loadUserGroupLists(requestSeq = loadAllRequestSeq, options = {}) {
  const { showErrors = false, silent = false, force = false } = options;
  if (!force && state.lazyLoaded.userGroupLists) {
    return { users: { items: state.users }, groups: { items: state.groups } };
  }
  if (!force && state.userGroupListPromise) return state.userGroupListPromise;
  state.userGroupListError = "";
  if (!silent && state.activeTab === "learning") renderLearningSummary();
  const promise = (async () => {
    try {
      const [users, groups] = await Promise.all([
        fetchJson("/users?limit=300"),
        fetchJson("/groups?limit=300"),
      ]);
      if (requestSeq !== loadAllRequestSeq) return null;
      applyUserGroupLists(users, groups);
      state.lazyLoaded.userGroupLists = true;
      if (!silent) {
        renderAfterUserGroupListsLoaded();
        const overview = state.overview || {};
        $("#subtitle").textContent = `${overview.plugin?.bot_name || "Private Companion"} · ${new Date().toLocaleString()}`;
      }
      return { users, groups };
    } catch (error) {
      if (requestSeq !== loadAllRequestSeq) return null;
      state.userGroupListError = error.message || "名单读取失败";
      console.warn("[PrivateCompanionPage] 用户/群聊列表加载失败", error);
      if (!silent) {
        const overview = state.overview || {};
        $("#subtitle").textContent = `${overview.plugin?.bot_name || "Private Companion"} · 总览已加载，名单加载失败`;
        if (state.activeTab === "learning") renderLearningSummary();
      }
      if (showErrors) showToast(`名单加载失败：${error.message}`, "error");
      return null;
    }
  })();
  state.userGroupListPromise = promise;
  try {
    return await promise;
  } finally {
    if (state.userGroupListPromise === promise) state.userGroupListPromise = null;
  }
}

function persistExtensionMigrationNoticePreference() {
  const dialog = $("#extensionMigrationNoticeDialog");
  const selected = dialog?.querySelector("input[name=extension_migration_reminder]:checked")?.value;
  if (selected !== "never") return;
  try {
    window.localStorage.setItem(EXTENSION_MIGRATION_NOTICE_STORAGE_KEY, "1");
  } catch (_error) {
    // Embedded page environments may deny storage; the plugin preference is authoritative.
  }
  void fetchJson("/extension-migration-notice/update", {
    method: "POST",
    body: JSON.stringify({ version: EXTENSION_MIGRATION_NOTICE_VERSION, dismissed: true }),
  }).catch((error) => {
    console.warn("[PrivateCompanionPage] 迁移提示偏好持久化失败", error);
  });
}

function bindExtensionMigrationNoticeDialog(dialog) {
  if (!dialog || dialog.dataset.migrationNoticeBound === "1") return;
  dialog.dataset.migrationNoticeBound = "1";
  dialog.addEventListener("close", persistExtensionMigrationNoticePreference);
  dialog.querySelectorAll("[data-extension-migration-close]").forEach((button) => {
    button.addEventListener("click", () => dialog.close());
  });
}

async function openExtensionMigrationNoticeIfNeeded() {
  if (extensionMigrationNoticeChecked) return;
  extensionMigrationNoticeChecked = true;
  const dialog = $("#extensionMigrationNoticeDialog");
  if (!dialog) return;
  // The notice is declared near a tab panel for maintainability, but a modal
  // inside a hidden panel can make the page inert without rendering itself.
  if (dialog.parentElement !== document.body) document.body.append(dialog);
  bindExtensionMigrationNoticeDialog(dialog);
  try {
    if (window.localStorage.getItem(EXTENSION_MIGRATION_NOTICE_STORAGE_KEY) === "1") {
      void fetchJson("/extension-migration-notice/update", {
        method: "POST",
        body: JSON.stringify({ version: EXTENSION_MIGRATION_NOTICE_VERSION, dismissed: true }),
      }).catch(() => {});
      return;
    }
  } catch (_error) {
    // Fall through to the plugin-backed preference for embedded pages.
  }
  try {
    const preference = await fetchJson("/extension-migration-notice");
    if (preference?.dismissed) {
      try {
        window.localStorage.setItem(EXTENSION_MIGRATION_NOTICE_STORAGE_KEY, "1");
      } catch (_error) {
        // The server-side preference is authoritative when storage is unavailable.
      }
      return;
    }
  } catch (error) {
    console.warn("[PrivateCompanionPage] 读取迁移提示偏好失败，按默认策略显示", error);
  }
  const remindChoice = dialog.querySelector('input[name="extension_migration_reminder"][value="remind"]');
  if (remindChoice) remindChoice.checked = true;
  const neverChoice = dialog.querySelector('input[name="extension_migration_reminder"][value="never"]');
  if (neverChoice) neverChoice.checked = false;
  if (dialog.open) return;
  if (typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open", "");
  window.requestAnimationFrame(() => {
    const rect = dialog.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) return;
    if (typeof dialog.close === "function" && dialog.open) dialog.close();
    else dialog.removeAttribute("open");
    console.warn("[PrivateCompanionPage] 迁移提示未能可见渲染，已自动解除模态状态");
  });
}

async function loadAll(options = {}) {
  const requestSeq = ++loadAllRequestSeq;
  const { waitForLists = false } = options;
  cancelUserGroupPrefetch();
  state.lazyLoaded.userGroupLists = false;
  state.userGroupListPromise = null;
  state.userGroupListError = "";
  state.expressionLibrary = null;
  state.expressionLibraryError = "";
  $("#subtitle").textContent = "读取运行态中...";
  try {
    const overview = await fetchJson("/overview");
    if (requestSeq !== loadAllRequestSeq) return;
    applyOverviewData(overview);
    state.overviewRefreshedAt = Date.now();
    renderAll();
    openExtensionMigrationNoticeIfNeeded();
    void restoreBookshelfAccess();
    void ensureTabData(state.activeTab, true);
    $("#subtitle").textContent = `${overview.plugin?.bot_name || "Private Companion"} · 总览已加载`;
    const loadLists = () => {
      if (state.lazyLoaded.userGroupLists) return Promise.resolve(null);
      $("#subtitle").textContent = `${overview.plugin?.bot_name || "Private Companion"} · 正在后台补全名单...`;
      return loadUserGroupLists(requestSeq, { showErrors: true });
    };
    if (waitForLists) {
      await loadLists();
    } else {
      // Let the dashboard become interactive before fetching the larger lists.
      // A tab switch still loads them immediately through ensureTabData().
      scheduleUserGroupPrefetch(() => {
        if (requestSeq === loadAllRequestSeq) void loadLists();
      });
    }
  } catch (error) {
    if (requestSeq !== loadAllRequestSeq) return;
    $("#subtitle").textContent = `加载失败：${error.message}`;
  }
}

function hydrateTokenStatsFromOverview(overview) {
  const tokenStats = overview?.token_stats;
  if (!tokenStats || typeof tokenStats !== "object") return;
  state.tokenStats = tokenStats;
  state.tokenStatsPartial = true;
  state.lazyLoaded.tokenStats = false;
}

function renderAll() {
  scheduleDailyOutfitHydration();
  renderPagePersonaSelector();
  renderStats();
  renderDashboard();
  renderActiveTab(state.activeTab);
  renderSetupGuideOverlay();
}

function renderCreativeCompanionStatus() {
  const target = $("#creativeCompanionStatus");
  if (!target) return;
  const status = state.overview?.companion_plugins?.content || {};
  if (!status.installed) {
    target.textContent = "未安装创作扩展";
    target.dataset.tone = "warn";
  } else if (!status.enabled) {
    target.textContent = "已安装 · 未启用";
    target.dataset.tone = "warn";
  } else if (status.available === false) {
    target.textContent = "已安装 · 当前不可用";
    target.dataset.tone = "error";
  } else {
    target.textContent = "创作扩展已联动";
    target.dataset.tone = "ready";
  }
}

function renderImageRuntimeStatus() {
  const value = state.imageExtensionStatus || {};
  const badge = document.getElementById("imageRuntimeBadge");
  const notice = document.getElementById("imageRuntimeNotice");
  const available = value.available === true;
  const enabled = value.enabled === true;
  if (badge) {
    badge.textContent = available ? "运行中" : enabled ? "等待主插件" : "已停用";
    badge.dataset.tone = available ? "ready" : enabled ? "warn" : "error";
  }
  if (notice) {
    notice.textContent = state.imageExtensionError
      ? `状态读取失败：${state.imageExtensionError}`
      : !value.installed
        ? "未检测到“我会画给你看”扩展。"
        : available
          ? "生图扩展已由陪伴主插件接管，所有页面入口集中在当前面板。"
          : value.reason === "private_companion_required"
            ? "生图扩展尚未连接陪伴主插件。"
            : "生图扩展当前不可用，请检查插件启用状态。";
  }
  const latest = value.last_generation && typeof value.last_generation === "object"
    ? value.last_generation
    : {};
  const setText = (id, text) => {
    const target = document.getElementById(id);
    if (target) target.textContent = String(text ?? "-");
  };
  setText("imageRuntimeEnabled", !value.installed ? "未安装" : enabled ? "已启用" : "已停用");
  setText("imageRuntimeMode", value.state === "managed" ? "陪伴面板接管" : "不可用");
  setText("imageRuntimeCount", Number(value.generation_count || 0));
  setText("imageRuntimeWorkflow", latest.workflow_kind || "暂无记录");
  setText("imageRuntimeBackend", latest.backend || "-");
  setText("imageRuntimeResult", latest.success === true ? "成功" : latest.success === false ? "失败" : "-");
  setText("imageRuntimeNote", latest.note || "-");
  renderImageRuntimeDebug(value);

  const engine = document.getElementById("imageRuntimeEngine");
  if (!engine) return;
  const diagnostics = value.unified_engine && typeof value.unified_engine === "object"
    ? value.unified_engine
    : {};
  const labelMap = {
    mode: "模式",
    backend: "当前后端",
    selected_backend: "当前后端",
    configured: "配置状态",
    valid: "路由校验",
    migration_required: "需要迁移",
    reason: "说明",
  };
  const entries = Object.entries(diagnostics)
    .filter(([, item]) => ["string", "number", "boolean"].includes(typeof item))
    .slice(0, 8);
  engine.innerHTML = entries.length
    ? entries.map(([key, item]) => `<div><dt>${escapeHtml(labelMap[key] || key)}</dt><dd>${escapeHtml(String(item))}</dd></div>`).join("")
    : '<div><dt>诊断</dt><dd>暂无统一引擎摘要</dd></div>';
}

function renderImageRuntimeDebug(value = state.imageExtensionStatus || {}) {
  const debug = value?.photo_debug && typeof value.photo_debug === "object"
    ? value.photo_debug
    : {};
  const badge = document.getElementById("imageRuntimeDebugBadge");
  const hint = document.getElementById("imageRuntimeDebugHint");
  const latestTarget = document.getElementById("imageRuntimeDebugLatest");
  const details = document.getElementById("imageRuntimeDebugDetails");
  const select = document.getElementById("imageRuntimeDebugTraceSelect");
  const log = document.getElementById("imageRuntimeDebugLog");
  const events = Array.isArray(debug.events) ? debug.events : [];
  const traces = Array.isArray(debug.traces) ? debug.traces : [];
  const latest = debug.latest && typeof debug.latest === "object" ? debug.latest : {};
  const debugConfig = value?.debug && typeof value.debug === "object" ? value.debug : {};
  if (badge) {
    badge.textContent = debugConfig.sensitive
      ? "含敏感信息"
      : debug.available ? "已记录" : debug.enabled ? "暂无记录" : "未启用";
    badge.dataset.tone = debugConfig.sensitive ? "error" : debug.available ? "ready" : debug.enabled ? "warn" : "idle";
  }
  if (hint) {
    hint.textContent = debugConfig.sensitive
      ? "当前为 full_with_secrets，展开日志前请确认访问环境安全"
      : debug.available
      ? `最近一次摘要已就绪（${traces.length} 个 Trace），展开后按 Trace 查看完整链路`
      : debug.enabled ? "调试文件已启用，等待下一次生图" : "调试日志未启用";
  }
  if (latestTarget) {
    if (!debug.available) {
      latestTarget.innerHTML = '<span class="muted">暂无生图调试记录</span>';
    } else {
      const trace = String(latest.trace || "");
      const stage = String(latest.stage || "-");
      const status = String(latest.status || "-");
      const time = String(latest.time || latest.ts || "-");
      latestTarget.innerHTML = `
        <div><span>Trace</span><b>${escapeHtml(trace || "-")}</b></div>
        <div><span>最后阶段</span><b>${escapeHtml(stage)}</b></div>
        <div><span>状态</span><b>${escapeHtml(status)}</b></div>
        <div><span>时间</span><b>${escapeHtml(time)}</b></div>`;
    }
  }
  if (!select || !log || !details) return;
  const selected = state.imageDebugTrace || String(latest.trace || traces.at(-1)?.trace || "");
  if (select.dataset.optionsKey !== traces.map((item) => item.trace).join("|")) {
    select.innerHTML = traces.length
      ? traces.slice().reverse().map((item) => {
        const trace = String(item.trace || "");
        const label = `${trace} · ${item.stage || "-"} · ${item.status || "-"}`;
        return `<option value="${escapeHtml(trace)}">${escapeHtml(label)}</option>`;
      }).join("")
      : '<option value="">暂无 Trace</option>';
    select.dataset.optionsKey = traces.map((item) => item.trace).join("|");
  }
  if (selected && traces.some((item) => String(item.trace) === selected)) {
    state.imageDebugTrace = selected;
    select.value = selected;
  } else if (select.options.length) {
    state.imageDebugTrace = select.value;
  }
  if (!details.open) {
    log.textContent = "展开后加载完整事件";
    return;
  }
  state.imageDebugExpanded = true;
  const selectedEvents = events.filter((event) => String(event.trace || "") === state.imageDebugTrace);
  log.textContent = selectedEvents.length
    ? selectedEvents.map((event) => JSON.stringify(event, null, 2)).join("\n\n")
    : "该 Trace 暂无事件";
}

function renderQzonePanel() {
  if (window.PrivateCompanionQzonePanel?.render) {
    window.PrivateCompanionQzonePanel.render({ fetchJson, postJson, showToast, escapeHtml, document });
    return;
  }
  const meta = document.getElementById("qzoneFeedMeta");
  const feed = document.getElementById("qzoneFeed");
  const moduleError = state.lazyScriptErrors.qzonePanel || "";
  const canRetryModule = Number(state.lazyScriptAttempts.qzonePanel || 0) < optionalModuleLoaders.qzonePanel.length;
  if (meta) meta.textContent = moduleError ? "QQ 空间模块加载失败" : "正在加载 QQ 空间模块...";
  if (feed) {
    feed.innerHTML = moduleError
      ? `<div class="empty small">${escapeHtml(moduleError)}<br />${canRetryModule ? `<button type="button" data-optional-module-retry="qzonePanel">重试加载</button>` : "请刷新当前页面。"}</div>`
      : `<div class="empty small">正在按需加载 QQ 空间面板...</div>`;
  }
}

function mergeCreativeWorkspace() {
  const creative = document.getElementById("panel-creative");
  const qzone = document.getElementById("panel-qzone");
  if (!creative || !qzone || qzone.dataset.mergedIntoCreative === "1") return;
  qzone.classList.remove("panel");
  qzone.classList.add("creative-qzone-workspace");
  qzone.dataset.mergedIntoCreative = "1";
  creative.appendChild(qzone);
}

mergeCreativeWorkspace();

function renderActiveTab(tabName = state.activeTab || "dashboard") {
  if (tabName === "private") {
    renderUsers();
  } else if (tabName === "learning") {
    renderLearning();
  } else if (tabName === "group") {
    renderGroups();
  } else if (tabName === "memory") {
    renderMemory();
  } else if (tabName === "proactive") {
    renderProactiveCandidates();
  } else if (tabName === "creative") {
    renderBookshelf();
    renderCreativeCompanionStatus();
    renderQzonePanel();
  } else if (tabName === "image") {
    renderImageRuntimeStatus();
  } else if (tabName === "image-cache") {
    renderImageCache();
  } else if (tabName === "troubleshooting") {
    renderTroubleshooting();
  } else if (tabName === "tokens") {
    renderTokens();
  } else if (tabName === "roleplay") {
    renderModuleSettings();
    renderRoleplayPersonaDraftPanel();
  } else if (tabName === "config") {
    renderConfig();
    renderModuleSettings();
  } else if (tabName === "models") {
    renderProviders();
  } else if (tabName === "experimental") {
    renderExperimentalPage();
  } else if (tabName === "reality") {
    renderRealityTouchPage();
  }
  syncFeatureFooterAction();
}

async function loadDiagnostics(force = false, options = {}) {
  const { skipExperimentalRender = false } = options;
  if (state.lazyLoaded.diagnostics && !force) return state.diagnostics;
  const diagnostics = await fetchJson("/diagnostics");
  state.diagnostics = diagnostics.items || [];
  state.lazyLoaded.diagnostics = true;
  if (state.activeTab === "troubleshooting") {
    renderDiagnostics();
  }
  if (state.activeTab === "experimental" && !skipExperimentalRender) {
    renderExperimentalPage();
  }
  renderDashboardPulse();
  return state.diagnostics;
}

async function refreshExperimentalRuntimeData(force = false) {
  const requestSeq = loadAllRequestSeq;
  await Promise.all([
    loadDiagnostics(force, { skipExperimentalRender: true }).catch(() => null),
    loadTroubleshooting({ silent: true, skipExperimentalRender: true }).catch(() => null),
    loadUserGroupLists(requestSeq, { silent: true, force }).catch(() => null),
  ]);
  if (state.activeTab === "experimental") renderExperimentalPage();
}

function scheduleExperimentalRuntimeRefresh(force = false) {
  state.experimentalRuntimeRefreshForce = Boolean(state.experimentalRuntimeRefreshForce || force);
  if (state.experimentalRuntimeRefreshTimer) {
    clearTimeout(state.experimentalRuntimeRefreshTimer);
  }
  state.experimentalRuntimeRefreshTimer = setTimeout(() => {
    const shouldForce = Boolean(state.experimentalRuntimeRefreshForce);
    state.experimentalRuntimeRefreshForce = false;
    state.experimentalRuntimeRefreshTimer = null;
    refreshExperimentalRuntimeData(shouldForce).catch(() => {});
  }, 120);
}

async function loadTokenStats(force = false) {
  if (state.lazyLoaded.tokenStats && !force && !state.tokenStatsPartial) return state.tokenStats;
  const tokenStats = await fetchJson("/token/stats");
  state.tokenStats = tokenStats || null;
  state.tokenStatsPartial = false;
  state.lazyLoaded.tokenStats = true;
  renderStats();
  if (state.activeTab === "tokens") renderTokens();
  if (state.activeTab === "dashboard") renderDashboardPulse();
  return state.tokenStats;
}

async function loadAvailableProviders(force = false) {
  if (state.lazyLoaded.providers && !force) return state.availableProviders;
  const availableProviders = await fetchJson("/providers/available");
  state.availableProviders = availableProviders.items || [];
  state.availableEmbeddingProviders = availableProviders.embedding_items || [];
  state.availableTtsProviders = availableProviders.tts_items || [];
  state.lazyLoaded.providers = true;
  if (state.activeTab === "models") renderProviders();
  if (state.activeTab === "config") {
    renderConfig();
    renderModuleSettings();
  } else if (state.activeTab === "roleplay") {
    renderModuleSettings();
  }
  return state.availableProviders;
}

async function loadTtsProviderConfigs(force = false) {
  if (state.lazyLoaded.ttsProviderConfigs && !force) return state.ttsProviderConfigs;
  const data = await fetchJson("/tts/providers");
  state.ttsProviderConfigs = Array.isArray(data.items) ? data.items : [];
  state.ttsProviderTemplates = Array.isArray(data.templates) ? data.templates : [];
  state.ttsProviderConfigLoaded = true;
  state.lazyLoaded.ttsProviderConfigs = true;
  const selectedExists = state.ttsProviderConfigs.some((item) => item.id === state.selectedTtsProviderId);
  if (!selectedExists) state.selectedTtsProviderId = state.ttsProviderConfigs[0]?.id || "";
  if (!state.ttsProviderTemplates.some((item) => item.type === state.ttsProviderCreateType)) {
    state.ttsProviderCreateType = state.ttsProviderTemplates[0]?.type || "";
  }
  if (state.activeTab === "models" && state.modelsSection === "tts") renderProviders();
  return state.ttsProviderConfigs;
}

async function loadImageApiStatus(force = false) {
  if (!imageCompanionInstalled()) {
    state.imageApiStatus = null;
    state.lazyLoaded.imageApiStatus = false;
    return null;
  }
  if (state.lazyLoaded.imageApiStatus && !force) return state.imageApiStatus;
  const status = await fetchJson("/image_api/status");
  state.imageApiStatus = status || { items: [] };
  state.lazyLoaded.imageApiStatus = true;
  if (state.activeTab === "models" && state.modelsSection === "image") renderProviders();
  return state.imageApiStatus;
}

async function loadImageExtensionStatus(force = false) {
  if (!imageCompanionInstalled()) {
    state.imageExtensionStatus = null;
    state.imageExtensionError = "";
    state.lazyLoaded.imageExtensionStatus = false;
    return null;
  }
  if (state.lazyLoaded.imageExtensionStatus && !force) return state.imageExtensionStatus;
  state.imageExtensionError = "";
  try {
    state.imageExtensionStatus = await fetchJson("/extensions/image/status");
    state.lazyLoaded.imageExtensionStatus = true;
  } catch (error) {
    state.imageExtensionStatus = null;
    state.imageExtensionError = error?.message || "未知错误";
    throw error;
  } finally {
    if (state.activeTab === "image") renderImageRuntimeStatus();
  }
  return state.imageExtensionStatus;
}

async function loadImageDebug(trace = "") {
  const params = new URLSearchParams({ limit: "240" });
  if (trace) params.set("trace", trace);
  const payload = await fetchJson(`/image/debug?${params.toString()}`);
  if (state.imageExtensionStatus && payload && typeof payload === "object") {
    const summary = state.imageExtensionStatus.photo_debug && typeof state.imageExtensionStatus.photo_debug === "object"
      ? state.imageExtensionStatus.photo_debug
      : {};
    // Keep the collapsed card anchored to the latest generation. The expanded
    // endpoint may be scoped to an older Trace and only owns its event body.
    state.imageExtensionStatus.photo_debug = {
      ...summary,
      ...payload,
      latest: summary.latest && typeof summary.latest === "object" ? summary.latest : payload.latest,
      traces: Array.isArray(payload.traces) ? payload.traces : summary.traces,
    };
  }
  renderImageRuntimeDebug(state.imageExtensionStatus || {});
  return payload;
}

async function loadRoleplayPersonas(force = false) {
  if (state.lazyLoaded.roleplayPersonas && !force) return state.roleplayPersonas;
  const storedPersona = storedPagePersonaId();
  const result = await fetchJson("/roleplay/personas").catch(() => ({ items: [] }));
  state.roleplayPersonas = Array.isArray(result.items) ? result.items : [];
  state.multiPersona = result.multi_persona || { enabled: false, primary: "", profiles: [] };
  const profiles = Array.isArray(state.multiPersona.profiles) ? state.multiPersona.profiles : [];
  const requested = String(state.selectedPersonaId || storedPersona || "").trim();
  const selected = state.multiPersona.enabled
    ? (profiles.includes(requested)
      ? requested
      : (String(result.current || state.multiPersona.primary || profiles[0] || "").trim()))
    : "";
  persistSelectedPagePersonaId(selected);
  state.multiPersona.current = selected;
  if (requested && state.multiPersona.enabled && !profiles.includes(requested)) {
    // A removed profile must not leave a stale page scope in sessionStorage.
    persistSelectedPagePersonaId(selected);
  }
  state.lazyLoaded.roleplayPersonas = true;
  if (state.multiPersona.enabled && selected) {
    await loadPersonaConfigState(selected).catch((error) => {
      console.warn("[PrivateCompanionPage] 读取人格配置状态失败", error);
    });
  } else {
    state.personaConfigState = null;
    state.personaConfigError = "";
  }
  renderPagePersonaSelector();
  const draft = setupGuideDraft();
  if (!draft.personaId) {
    draft.personaId = result.current || result.default || state.roleplayPersonas[0]?.id || "";
  }
  if (state.activeTab === "config") {
    renderConfig();
    renderModuleSettings();
  } else if (state.activeTab === "roleplay") {
    renderModuleSettings();
  }
  return state.roleplayPersonas;
}

async function loadSelectedPersonaOverview(personaId) {
  const selected = String(personaId || "").trim();
  const requestSeq = ++state.personaSelectionRequestSeq;
  const [overview, configState] = await Promise.all([
    fetchJson("/overview", { dedupe: false }),
    state.multiPersona?.enabled && selected
      ? loadPersonaConfigState(selected).catch((error) => {
        state.personaConfigError = error?.message || "读取人格配置状态失败";
        return null;
      })
      : Promise.resolve(null),
  ]);
  if (requestSeq !== state.personaSelectionRequestSeq) return null;
  applyOverviewData(overview);
  if (configState) applyPersonaConfigState(configState);
  state.overviewRefreshedAt = Date.now();
  renderAll();
  const subtitle = document.getElementById("subtitle");
  if (subtitle) {
    subtitle.textContent = `${overview.plugin?.bot_name || "Private Companion"} · 总览已加载`;
  }
  await ensureTabData(state.activeTab, true).catch(() => {});
  const label = selected ? personaDisplayLabel(selected) : "当前人格";
  const source = document.getElementById("configPersonaStatsSource");
  if (source) source.textContent = `${label} · 统计随人格选择更新`;
  return overview;
}

async function loadConfigBackups(force = false) {
  if (state.lazyLoaded.configBackups && !force) return state.configBackups;
  const configBackups = await fetchJson("/config/backups").catch(() => ({ items: [] }));
  state.configBackups = configBackups.items || [];
  state.lazyLoaded.configBackups = true;
  if (state.activeTab === "config") renderConfigBackups();
  return state.configBackups;
}

async function loadMemoNotes(force = false) {
  if (state.lazyLoaded.memoNotes && !force && state.memoNotes) return state.memoNotes;
  const result = await fetchJson("/memo/list");
  applyMemoPayload(result.memo_notes || {});
  if (state.activeTab === "creative") renderBookshelf();
  return state.memoNotes;
}

async function ensureTabData(tabName, force = false) {
  if (tabName === "dashboard") {
    return;
  }
  if (["private", "group", "learning", "memory", "proactive", "experimental"].includes(tabName) && (!state.lazyLoaded.userGroupLists || force)) {
    await loadUserGroupLists(loadAllRequestSeq, { showErrors: true, force });
  }
  if (tabName === "tokens") {
    await loadTokenStats(force);
  } else if (tabName === "creative") {
    await Promise.all([
      loadMemoNotes(force),
      (async () => {
        try {
          await loadOptionalModule("qzonePanel");
        } finally {
          if (state.activeTab === "creative") renderActiveTab("creative");
        }
      })(),
    ]);
  } else if (tabName === "image") {
    renderImageRuntimeStatus();
    await loadImageExtensionStatus(force);
  } else if (tabName === "models") {
    try {
      await Promise.all([
        loadOptionalModule("providerTree"),
        loadAvailableProviders(force),
        loadTtsProviderConfigs(force),
        loadImageApiStatus(force),
      ]);
    } finally {
      if (state.activeTab === "models") renderProviders();
    }
  } else if (tabName === "roleplay") {
    loadAvailableProviders(force).catch(() => {});
  } else if (tabName === "config") {
    await Promise.all([loadConfigBackups(force), loadRoleplayPersonas(force)]);
  } else if (tabName === "image-cache") {
    renderImageCache();
    await Promise.all([loadImageCache(), loadOwnedReactionAssets()]);
  } else if (tabName === "reality") {
    renderRealityTouchPage();
    await loadRealityTouch(force);
  } else if (tabName === "troubleshooting") {
    renderTroubleshooting();
    loadDiagnostics(force).catch(() => {});
    await loadTroubleshooting();
  } else if (tabName === "experimental") {
    renderExperimentalPage();
    await refreshExperimentalRuntimeData(force);
  }
}

