function roleplayMode() {
  if (roleplayModeState === "standard" || roleplayModeState === "freeform") return roleplayModeState;
  const studioMode = document.querySelector(".roleplay-studio")?.dataset.roleplayMode;
  if (studioMode === "standard" || studioMode === "freeform") return studioMode;
  let stored = "";
  try {
    stored = window.localStorage?.getItem(ROLEPLAY_MODE_STORAGE_KEY) || "";
  } catch (error) {
    stored = "";
  }
  return stored === "freeform" ? "freeform" : "standard";
}

function setRoleplayMode(mode) {
  const normalized = mode === "standard" ? "standard" : "freeform";
  roleplayModeState = normalized;
  try {
    window.localStorage?.setItem(ROLEPLAY_MODE_STORAGE_KEY, normalized);
  } catch (error) {
    // 嵌入式拓展页环境可能禁用 localStorage，模式仍可在当前页面内切换。
  }
  const studio = document.querySelector(".roleplay-studio");
  if (studio) studio.dataset.roleplayMode = normalized;
  document.querySelectorAll(".roleplay-mode-switch [data-roleplay-mode]").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.roleplayMode === normalized);
  });
  resizeRoleplayTextareas();
}

function bindRoleplayModeSwitch() {
  setRoleplayMode(roleplayMode());
  document.querySelectorAll(".roleplay-mode-switch [data-roleplay-mode]").forEach((button) => {
    button.addEventListener("click", () => setRoleplayMode(button.dataset.roleplayMode));
  });
  document.querySelectorAll("[data-roleplay-example]").forEach((button) => {
    button.addEventListener("click", () => applyRoleplayExample(button.dataset.roleplayExample));
  });
  const draftButton = document.getElementById("generateRoleplayDraftBtn");
  if (draftButton) draftButton.addEventListener("click", () => generateRoleplayDraftFromPersona(draftButton));
}

function applyRoleplayExample(kind) {
  const example = roleplayExamples[kind];
  if (!example) return;
  setRoleplayMode("standard");
  if (kind === "persona" || kind.startsWith("persona_")) {
    Object.entries(example).forEach(([key, value]) => {
      const control = document.querySelector(`[data-roleplay-persona-part="${key}"]`);
      if (control) control.value = value;
    });
  } else if (kind === "world") {
    Object.entries(example).forEach(([key, value]) => {
      if (key === "translations") return;
      const control = document.querySelector(`[data-roleplay-world-part="${key}"]`);
      if (control) control.value = value;
    });
    Object.entries(example.translations || {}).forEach(([key, value]) => {
      const control = document.querySelector(`[data-roleplay-translation-part="${key}"]`);
      if (control) control.value = value;
    });
  } else if (kind === "user") {
    const nickname = document.querySelector('#roleplayProfileForm [name="default_nickname"]');
    if (nickname) nickname.value = example.nickname || "";
    ["user_gender", "user_age", "user_occupation", "role_relation", "interaction", "extra"].forEach((key) => {
      const control = document.querySelector(`[data-roleplay-user-part="${key}"]`);
      if (control) control.value = example[key] || "";
    });
  }
  const form = document.getElementById("roleplayProfileForm");
  if (form) markModuleFormDirty(form);
  resizeRoleplayTextareas();
}

async function generateRoleplayDraftFromPersona(button) {
  setActionBusy(button, true);
  showToast("正在读取人格并生成导入草稿...");
  try {
    const scopes = selectedRoleplayDraftScopes();
    const result = await postJson("/roleplay/draft_from_persona", { scopes });
    state.roleplayPersonaDraft = result || null;
    renderRoleplayPersonaDraftPanel();
    showToast("导入草稿已生成，请预览后再填入");
  } catch (error) {
    showToast(`生成失败：${error.message}`, "error");
  } finally {
    setActionBusy(button, false);
  }
}

function selectedRoleplayDraftScopes() {
  const scopes = Array.from(document.querySelectorAll("[data-roleplay-draft-scope]:checked"))
    .map((input) => input.dataset.roleplayDraftScope || "")
    .filter(Boolean);
  return scopes.length ? scopes : ["persona"];
}

function renderRoleplayPersonaDraftPanel() {
  const panel = document.getElementById("roleplayPersonaDraftPanel");
  if (!panel) return;
  if (!state.roleplayPersonaDraft) {
    panel.hidden = true;
    panel.innerHTML = "";
    return;
  }
  const disclosure = panel.closest("details.persona-import-panel");
  if (disclosure) disclosure.open = true;
  const result = state.roleplayPersonaDraft;
  const draft = result.draft || {};
  const scopes = Array.isArray(result.scopes) ? result.scopes : [];
  const rows = [
    ...roleplayDraftPartRows(draft.persona_parts, roleplayPersonaParts, "角色资料"),
    ...roleplayDraftPartRows(draft.world_parts, roleplayWorldParts, "世界观资料"),
    ...roleplayDraftPartRows(draft.user_parts, roleplayVisionParts, "用户与关系"),
    ...roleplayTranslationParts.map((label) => ["翻译", label, draft.translations?.[label] || ""]).filter(([, , value]) => String(value || "").trim()),
  ];
  const imageHint = String(draft.image_self_recognition_hint || "").trim();
  if (imageHint) rows.push(["识图", "图片自我识别线索", imageHint]);
  const notes = Array.isArray(draft.notes) ? draft.notes.filter(Boolean) : [];
  panel.hidden = false;
  panel.innerHTML = `
    <header>
      <div>
        <b>导入预览</b>
        <span>${escapeHtml(roleplayDraftScopeLabel(scopes))} · ${escapeHtml(result.persona_id ? `指定人格：${personaDisplayLabel(result.persona_id)}` : "继承 AstrBot 默认人格")} · ${escapeHtml(result.provider_id || "主模型")} · 来源 ${escapeHtml(result.source_chars || 0)} 字</span>
      </div>
      <div class="persona-draft-panel-actions">
        <button type="button" data-roleplay-draft-apply="empty">填入空白项</button>
        <button type="button" data-roleplay-draft-apply="overwrite" class="soft">覆盖当前草稿</button>
        <button type="button" data-roleplay-draft-close class="ghost">收起预览</button>
      </div>
    </header>
    <p>${escapeHtml(result.source_preview || "已读取主回复人格。")} </p>
    ${rows.length ? `
      <div class="persona-draft-grid">
        ${rows.map(([group, label, value]) => `
          <section>
            <small>${escapeHtml(group)}</small>
            <b>${escapeHtml(label)}</b>
            <p>${escapeHtml(value)}</p>
          </section>
        `).join("")}
      </div>
    ` : `<div class="empty small">当前人格中没有提取到足够明确的世界知识字段。可以补充更具体的角色或世界观设定后再试。</div>`}
    ${notes.length ? `<div class="persona-draft-notes">${notes.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</div>` : ""}
  `;
  panel.querySelector("[data-roleplay-draft-close]")?.addEventListener("click", () => {
    panel.hidden = true;
  });
  panel.querySelectorAll("[data-roleplay-draft-apply]").forEach((control) => {
    control.addEventListener("click", () => {
      const overwrite = control.dataset.roleplayDraftApply === "overwrite";
      if (overwrite && !requireSecondClick(control, "roleplay-draft-overwrite", "再次点击会覆盖当前世界知识工作台里对应范围的草稿", "再次点击覆盖")) {
        return;
      }
      applyRoleplayPersonaDraft(overwrite);
    });
  });
}

function roleplayDraftPartRows(source, parts, group) {
  const data = source && typeof source === "object" ? source : {};
  return parts
    .map(([key, label]) => [group, label, data[key] || ""])
    .filter(([, , value]) => String(value || "").trim());
}

function roleplayDraftScopeLabel(scopes) {
  const selected = new Set(scopes || []);
  const labels = [
    selected.has("persona") ? "角色资料" : "",
    selected.has("world") ? "世界观资料" : "",
    selected.has("user") ? "用户与关系" : "",
  ].filter(Boolean);
  return labels.length ? `范围：${labels.join("、")}` : "范围：角色资料";
}

function applyRoleplayPersonaDraft(overwrite = false) {
  const draft = state.roleplayPersonaDraft?.draft || {};
  const scopes = new Set(Array.isArray(state.roleplayPersonaDraft?.scopes) ? state.roleplayPersonaDraft.scopes : ["persona"]);
  setRoleplayMode("standard");
  let changed = 0;
  if (scopes.has("persona")) {
    roleplayPersonaParts.forEach(([key]) => {
      changed += fillRoleplayDraftControl(`[data-roleplay-persona-part="${key}"]`, draft.persona_parts?.[key], overwrite);
    });
    changed += fillRoleplayDraftControl('#roleplayProfileForm [name="private_image_self_recognition_hint"]', draft.image_self_recognition_hint, overwrite);
  }
  if (scopes.has("world")) {
    roleplayWorldParts.forEach(([key]) => {
      changed += fillRoleplayDraftControl(`[data-roleplay-world-part="${key}"]`, draft.world_parts?.[key], overwrite);
    });
    roleplayTranslationParts.forEach((label) => {
      changed += fillRoleplayDraftControl(`[data-roleplay-translation-part="${label}"]`, draft.translations?.[label], overwrite);
    });
  }
  if (scopes.has("user")) {
    changed += fillRoleplayDraftControl('#roleplayProfileForm [name="default_nickname"]', draft.user_parts?.nickname, overwrite);
    roleplayVisionParts.forEach(([key]) => {
      if (key === "nickname") return;
      changed += fillRoleplayDraftControl(`[data-roleplay-user-part="${key}"]`, draft.user_parts?.[key], overwrite);
    });
  }
  syncRoleplayStandardFieldsToFreeform();
  const form = document.getElementById("roleplayProfileForm");
  if (changed && form) markModuleFormDirty(form);
  showToast(changed ? `已填入 ${changed} 项，请检查后保存世界知识` : "没有可填入的新字段");
}

function fillRoleplayDraftControl(selector, value, overwrite = false) {
  const text = String(value || "").trim();
  if (!text) return 0;
  const control = document.querySelector(selector);
  if (!control) return 0;
  if (!overwrite && String(control.value || "").trim()) return 0;
  control.value = text;
  return 1;
}

function extractLabeledValue(text, labels, label) {
  const lines = String(text || "").split(/\r?\n/);
  const labelSet = new Set(labels);
  const collected = [];
  let active = false;
  for (const rawLine of lines) {
    const line = rawLine.trim();
    const matched = labels.find((item) => line.startsWith(`${item}：`) || line.startsWith(`${item}:`));
    if (matched) {
      if (active) break;
      active = matched === label;
      if (active) collected.push(line.replace(new RegExp(`^${escapeRegExp(label)}[：:]\\s*`), ""));
      continue;
    }
    if (active) {
      if (labelSet.has(line.replace(/[：:].*$/, ""))) break;
      collected.push(rawLine);
    }
  }
  return collected.join("\n").trim();
}

function extractTranslationValue(text, label) {
  const pattern = new RegExp(`^\\s*${escapeRegExp(label)}\\s*(?:=|：|:)\\s*(.+?)\\s*$`);
  for (const line of String(text || "").split(/\r?\n/)) {
    const match = line.match(pattern);
    if (match) return match[1].trim();
  }
  return "";
}

function hydrateRoleplayPartGroup(sourceName, attr, parts) {
  const text = document.querySelector(`#roleplayProfileForm [name="${sourceName}"]`)?.value || "";
  const labels = parts.map(([, label]) => label);
  parts.forEach(([key, label]) => {
    const control = document.querySelector(`[${attr}="${key}"]`);
    if (!control) return;
    let value = extractLabeledValue(text, labels, label);
    if (!value && roleplayLabelAliases[label]) {
      const aliasLabels = [...labels, ...roleplayLabelAliases[label]];
      for (const alias of roleplayLabelAliases[label]) {
        value = extractLabeledValue(text, aliasLabels, alias);
        if (value) break;
      }
    }
    control.value = value;
  });
}

function syncRoleplayCoreFieldsFromPersona() {
  const personaText = document.querySelector('#roleplayProfileForm [name="schedule_persona_prompt"]')?.value || "";
  const labels = roleplayPersonaParts.map(([, label]) => label);
  const nameFromStandard = String(document.querySelector('[data-roleplay-persona-part="name"]')?.value || "").trim();
  const styleFromStandard = String(document.querySelector('[data-roleplay-persona-part="personality"]')?.value || "").trim();
  const name = nameFromStandard || extractLabeledValue(personaText, labels, "姓名");
  const style = styleFromStandard || extractLabeledValue(personaText, labels, "性格描述");
  const botNameInput = document.querySelector('#roleplayProfileForm [name="bot_name"]');
  const defaultStyleInput = document.querySelector('#roleplayProfileForm [name="default_style"]');
  if (botNameInput && name) botNameInput.value = name;
  if (defaultStyleInput && style) defaultStyleInput.value = style;
}

function hydrateRoleplayUserFields() {
  const primaryText = document.querySelector('#roleplayProfileForm [name="roleplay_user_profile_prompt"]')?.value || "";
  const text = primaryText;
  const legacyPersonaText = document.querySelector('#roleplayProfileForm [name="schedule_persona_prompt"]')?.value || "";
  const labels = roleplayVisionParts.map(([, label]) => label);
  roleplayVisionParts.forEach(([key, label]) => {
    if (key === "nickname") {
      const nickname = extractLabeledValue(text, labels, label);
      const control = document.querySelector('#roleplayProfileForm [name="default_nickname"]');
      if (control && nickname && !String(control.value || "").trim()) control.value = nickname;
      return;
    }
    const control = document.querySelector(`[data-roleplay-user-part="${key}"], [data-roleplay-vision-part="${key}"]`);
    if (!control) return;
    let value = extractLabeledValue(text, labels, label);
    if (!value && label === "是角色的XX") {
      value = extractLabeledValue(legacyPersonaText, ["身份", "年龄感", "生活处境", "与用户关系", "说话风格", "能力边界", "禁区"], label);
      if (!value) value = extractLabeledValue(legacyPersonaText, ["身份", "年龄感", "生活处境", "与用户关系", "说话风格", "能力边界", "禁区"], "与用户关系");
    }
    control.value = value;
  });
}

function hydrateRoleplayStandardFields() {
  hydrateRoleplayPartGroup("schedule_persona_prompt", "data-roleplay-persona-part", roleplayPersonaParts);
  hydrateRoleplayPartGroup("schedule_worldview_prompt", "data-roleplay-world-part", roleplayWorldParts);
  hydrateRoleplayUserFields();
  syncRoleplayCoreFieldsFromPersona();
  const translationText = document.querySelector('#roleplayProfileForm [name="worldview_adaptation_prompt"]')?.value || "";
  roleplayTranslationParts.forEach((label) => {
    const control = document.querySelector(`[data-roleplay-translation-part="${label}"]`);
    if (control) control.value = extractTranslationValue(translationText, label);
  });
  setRoleplayMode(roleplayMode());
}

function composeLabeledParts(attr, parts) {
  const lines = [];
  parts.forEach(([key, label]) => {
    const control = document.querySelector(`[${attr}="${key}"]`);
    const value = String(control?.value || "").trim();
    if (value) lines.push(`${label}：${value}`);
  });
  return lines.join("\n");
}

function composeRoleplayUserParts() {
  const lines = [];
  roleplayVisionParts.forEach(([key, label]) => {
    if (key === "nickname") {
      const value = String(document.querySelector('#roleplayProfileForm [name="default_nickname"]')?.value || "").trim();
      if (value) lines.push(`${label}：${value}`);
      return;
    }
    const control = document.querySelector(`[data-roleplay-user-part="${key}"], [data-roleplay-vision-part="${key}"]`);
    const value = String(control?.value || "").trim();
    if (value) lines.push(`${label}：${value}`);
  });
  return lines.join("\n");
}

function composeTranslationParts() {
  const lines = [];
  roleplayTranslationParts.forEach((label) => {
    const control = document.querySelector(`[data-roleplay-translation-part="${label}"]`);
    const value = String(control?.value || "").trim();
    if (value) lines.push(`${label} = ${value}`);
  });
  return lines.join("\n");
}

function syncRoleplayStandardFieldsToFreeform() {
  if (roleplayMode() !== "standard") return;
  const mappings = [
    ["schedule_persona_prompt", composeLabeledParts("data-roleplay-persona-part", roleplayPersonaParts)],
    ["schedule_worldview_prompt", composeLabeledParts("data-roleplay-world-part", roleplayWorldParts)],
    ["worldview_adaptation_prompt", composeTranslationParts()],
    ["roleplay_user_profile_prompt", composeRoleplayUserParts()],
  ];
  mappings.forEach(([name, value]) => {
    const target = document.querySelector(`#roleplayProfileForm [name="${name}"]`);
    if (target) target.value = value;
  });
  syncRoleplayCoreFieldsFromPersona();
}

const newsSourcePresets = [
  ["BBC中文", "https://feeds.bbci.co.uk/zhongwen/simp/rss.xml"],
  ["Google新闻中文", "https://news.google.com/rss?hl=zh-CN&gl=CN&ceid=CN:zh-Hans"],
  ["Solidot", "https://www.solidot.org/index.rss"],
  ["Hacker News", "https://hnrss.org/frontpage"],
  ["MIT Technology Review", "https://www.technologyreview.com/feed/"],
  ["Ars Technica", "https://feeds.arstechnica.com/arstechnica/index"],
  ["B站 AI早报", "bilibili:285286947"],
];

function parseNewsSources(raw) {
  return splitNewsSourceLines(raw).map((line) => {
    const original = line;
    let text = line.trim();
    if (!text) return null;
    const enabled = !text.startsWith("#");
    if (!enabled) text = text.replace(/^#+\s*/, "");
    let name = "";
    let target = text;
    if (text.includes("|")) {
      [name, target] = text.split("|", 2);
    }
    target = String(target || "").trim();
    name = String(name || "").trim();
    if (!target) return null;
    const lowerTarget = target.toLowerCase();
    const type = lowerTarget.startsWith("bvid:") || target.includes("bilibili.com/video/")
      ? "bilibili_video"
      : (lowerTarget.startsWith("bilibili:") || target.includes("space.bilibili.com") ? "bilibili" : "rss");
    return { enabled, name, target, type, original };
  }).filter(Boolean);
}

function splitNewsSourceLines(raw) {
  const text = String(raw || "").trim();
  if (!text) return [];
  const normalLines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (normalLines.length !== 1) return normalLines;
  const line = normalLines[0];
  const markers = Array.from(line.matchAll(/(?:^|\s+)(#?\s*[^|\n]+?)\|(?=(?:https?:\/\/|bilibili:|bvid:))/gi));
  if (markers.length <= 1) return normalLines;
  return markers.map((match, index) => {
    const start = match.index + match[0].length;
    const end = index + 1 < markers.length ? markers[index + 1].index : line.length;
    const name = String(match[1] || "").trim();
    const target = line.slice(start, end).trim();
    return `${name}|${target}`.trim();
  }).filter(Boolean);
}

function newsSourceTypeLabel(type) {
  if (type === "bilibili") return "B站 UP";
  if (type === "bilibili_video") return "B站视频";
  return "新闻源";
}

function newsSourcePlaceholder(type) {
  if (type === "bilibili") return "bilibili:UID 或空间链接";
  if (type === "bilibili_video") return "bvid:BV... 或视频链接";
  return "https://...rss.xml";
}

function serializeNewsSources(items) {
  return items
    .filter((item) => item && String(item.target || "").trim())
    .map((item) => {
      const body = `${String(item.name || "").trim() || newsSourceTypeLabel(item.type)}|${String(item.target || "").trim()}`;
      return item.enabled === false ? `# ${body}` : body;
    })
    .join("\n");
}

function newsSourceItemsFromDom() {
  return Array.from(document.querySelectorAll("[data-news-source-item]")).map((row) => ({
    enabled: Boolean(row.querySelector("[data-news-source-enabled]")?.checked),
    name: row.querySelector("[data-news-source-name]")?.value || "",
    type: row.querySelector("[data-news-source-type]")?.value || "rss",
    target: row.querySelector("[data-news-source-target]")?.value || "",
  }));
}

function syncNewsSourcesRaw() {
  const raw = $("#newsSourcesRaw");
  const manager = $("#newsSourceManager");
  if (!raw || !manager) return;
  raw.value = serializeNewsSources(newsSourceItemsFromDom());
  markModuleFormDirty(raw.closest("form"));
}

function renderNewsSourceManager(items = null) {
  const raw = $("#newsSourcesRaw");
  const manager = $("#newsSourceManager");
  if (!raw || !manager) return;
  const sources = items || parseNewsSources(raw.value);
  manager.innerHTML = `
    <div class="news-source-head">
      <div>
        <b>新闻源</b>
        <span>RSS/Atom、B 站 UP 主源或单条 B 站视频，最多读取前 12 个启用项。</span>
      </div>
      <div class="news-source-actions">
        <button type="button" data-news-source-add="rss">添加 RSS</button>
        <button type="button" data-news-source-add="bilibili">添加 B站 UP</button>
        <button type="button" data-news-source-add="bilibili_video">添加 B站视频</button>
        <button type="button" data-news-source-reset>恢复默认</button>
      </div>
    </div>
    <div class="news-source-list">
      ${sources.map((item, index) => `
        <article class="news-source-row" data-news-source-item="${index}">
          <label class="source-enable"><input type="checkbox" data-news-source-enabled ${item.enabled === false ? "" : "checked"} /> <span>${item.enabled === false ? "停用" : "启用"}</span></label>
          <input data-news-source-name type="text" value="${escapeHtml(item.name)}" placeholder="来源名称" />
          <select data-news-source-type>
            <option value="rss"${item.type === "rss" ? " selected" : ""}>RSS/Atom</option>
            <option value="bilibili"${item.type === "bilibili" ? " selected" : ""}>B站 UP</option>
            <option value="bilibili_video"${item.type === "bilibili_video" ? " selected" : ""}>B站视频</option>
          </select>
          <input data-news-source-target type="text" value="${escapeHtml(item.target)}" placeholder="${newsSourcePlaceholder(item.type)}" />
          <button type="button" data-news-source-remove="${index}">移除</button>
        </article>
      `).join("") || `<div class="empty small">还没有新闻源，可以添加 RSS、B 站 UP 主源或单条 B 站视频。</div>`}
    </div>
  `;
}

function resetNewsSourcesToDefault() {
  const items = newsSourcePresets.map(([name, target]) => ({
    enabled: true,
    name,
    target,
    type: target.startsWith("bilibili:") ? "bilibili" : "rss",
  }));
  const raw = $("#newsSourcesRaw");
  if (raw) raw.value = serializeNewsSources(items);
  renderNewsSourceManager(items);
  syncNewsSourcesRaw();
}

const segmentedPreviewExamples = {
  simple: "我刚才趴在窗边看了一会儿雨，玻璃上全是细细的水线。\n忽然想起你说今天会很忙，所以来轻轻报个到。",
  complex: "刚刷到一条有意思的 AI 早报，里面提到“模型更新。成本下降。工具链变多”这几件事。\n我把文字版链接先夹在这里：https://www.bilibili.com/video/BV1n77f6mE9m/\n还有（括号里的句号。和补充说明。都应该被完整保留），所以我想晚点整理成几句自己的想法再跟你说。",
};

function decodeSegmentedWordToken(value) {
  const raw = String(value ?? "");
  const trimmed = raw.trim();
  const lower = trimmed.toLowerCase();
  if (["<space>", "{space}", "[space]", "\\s", "\\u0020", "空格"].includes(lower)) return " ";
  if (["<newline>", "{newline}", "[newline]", "\\n", "换行"].includes(lower)) return "\n";
  if (["<tab>", "{tab}", "[tab]", "\\t", "tab"].includes(lower)) return "\t";
  if (["<comma>", "{comma}", "[comma]", "comma", "英文逗号"].includes(lower)) return ",";
  if (["<zh_comma>", "{zh_comma}", "[zh_comma]", "zh_comma", "中文逗号", "逗号"].includes(lower)) return "，";
  return raw;
}

function parseSegmentedWordList(value) {
  if (Array.isArray(value)) {
    return value.map(decodeSegmentedWordToken).filter((item) => item !== "");
  }
  const raw = String(value ?? "");
  const parts = raw.includes("\n") || raw.includes("\r")
    ? raw.split(/\r?\n/)
    : raw.split(/[,、]+/);
  return parts
    .map(decodeSegmentedWordToken)
    .filter((item) => item !== "");
}

const segmentedWidthVariantGroups = [
  [",", "，"], [".", "．", "。"], ["?", "？"], ["!", "！"], [";", "；"], [":", "："], ["~", "～"],
  ["(", "（"], [")", "）"], ["[", "［"], ["]", "］"], ["{", "｛"], ["}", "｝"], ["<", "＜"], [">", "＞"],
  ["\"", "＂"], ["'", "＇"], ["\\", "＼"], ["/", "／"], ["|", "｜"], ["+", "＋"], ["-", "－"], ["=", "＝"],
  ["*", "＊"], ["&", "＆"], ["%", "％"], ["#", "＃"], ["@", "＠"], ["$", "＄"], ["^", "＾"], ["_", "＿"],
];

function expandSegmentedWidthVariantWords(words) {
  const expanded = [...new Set((words || []).filter((item) => item !== ""))];
  const present = new Set(expanded);
  segmentedWidthVariantGroups.forEach((variants) => {
    if (!variants.some((variant) => present.has(variant))) return;
    variants.forEach((variant) => {
      if (present.has(variant)) return;
      expanded.push(variant);
      present.add(variant);
    });
  });
  return expanded;
}

function decodeSegmentedReplacementToken(value, replacement = false) {
  const raw = String(value ?? "");
  const trimmed = raw.trim();
  const lower = trimmed.toLowerCase();
  const aliases = new Map([
    ["<space>", " "], ["{space}", " "], ["[space]", " "], ["空格", " "],
    ["<newline>", "\n"], ["{newline}", "\n"], ["[newline]", "\n"], ["换行", "\n"],
    ["<tab>", "\t"], ["{tab}", "\t"], ["[tab]", "\t"], ["tab", "\t"],
    ["<empty>", ""], ["{empty}", ""], ["[empty]", ""], ["空内容", ""], ["删除", ""],
  ]);
  if (aliases.has(lower) && (replacement || !["<empty>", "{empty}", "[empty]", "空内容", "删除"].includes(lower))) {
    return aliases.get(lower);
  }
  return trimmed.replace(/\\n/g, "\n").replace(/\\t/g, "\t");
}

function parseSegmentedReplacementRules(value) {
  const rawRules = Array.isArray(value)
    ? value
    : String(value ?? "").split(/\r?\n/).filter((line) => line.trim());
  const pairs = [];
  rawRules.slice(0, 80).forEach((rawRule) => {
    let oldValue = "";
    let newValue = "";
    if (rawRule && typeof rawRule === "object") {
      oldValue = rawRule.from ?? rawRule.old ?? rawRule.source ?? "";
      newValue = rawRule.to ?? rawRule.new ?? rawRule.replacement ?? "";
    } else {
      const rule = String(rawRule ?? "");
      const separator = ["=>", "＝>", "→", "->"].find((item) => rule.includes(item));
      if (!separator) return;
      const separatorIndex = rule.indexOf(separator);
      oldValue = rule.slice(0, separatorIndex);
      newValue = rule.slice(separatorIndex + separator.length);
    }
    const oldText = decodeSegmentedReplacementToken(oldValue, false);
    const newText = decodeSegmentedReplacementToken(newValue, true);
    if (!oldText || oldText.length > 200 || newText.length > 500) return;
    pairs.push([oldText, newText]);
  });
  return pairs;
}

function applySegmentedPreviewReplacements(value, rules) {
  const pairs = parseSegmentedReplacementRules(rules);
  const original = String(value || "");
  if (!pairs.length || !original) return [original, 0];
  const protectedPattern = /<(?:image|img|video|record|audio|file)\b[^>]*(?:>.*?<\/(?:image|img|video|record|audio|file)>|\/?>)|<tts\b[^>]*>.*?<\/tts>|<[^>\n]{1,240}\bpath="[^"]{1,500}"[^>\n]*>|<[^>\n]{1,240}\b(?:url|src)="[^"]{1,500}"[^>\n]*>|\b(?:https?:\/\/|www\.)[A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]+/gis;
  let cursor = 0;
  let output = "";
  let replacementCount = 0;
  const replacePlain = (source) => {
    let next = String(source || "");
    pairs.forEach(([oldText, newText]) => {
      const count = Math.max(0, next.split(oldText).length - 1);
      if (!count) return;
      next = next.split(oldText).join(newText);
      replacementCount += count;
    });
    return next;
  };
  let match = null;
  while ((match = protectedPattern.exec(original)) !== null) {
    output += replacePlain(original.slice(cursor, match.index));
    output += match[0];
    cursor = match.index + match[0].length;
  }
  output += replacePlain(original.slice(cursor));
  return [output, replacementCount];
}

function escapeRegex(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function segmentedProtectedCleanupChunks(value) {
  const protectedPattern = /<(?:image|img|video|record|audio|file)\b[^>]*(?:>.*?<\/(?:image|img|video|record|audio|file)>|\/?>)|<tts\b[^>]*>.*?<\/tts>|<[^>\n]{1,240}\bpath="[^"]{1,500}"[^>\n]*>|<[^>\n]{1,240}\b(?:url|src)="[^"]{1,500}"[^>\n]*>|\b(?:https?:\/\/|www\.)[A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]+/gis;
  const bracketPairs = { "(": ")", "（": "）", "[": "]", "【": "】", "{": "}", "「": "」", "『": "』", "《": "》" };
  const bracketOpeners = new Set(Object.keys(bracketPairs));
  const quotePairs = { "\"": "\"", "“": "”", "'": "'", "‘": "’" };
  const chunks = [];
  let current = "";
  let protectedChunk = false;
  const bracketStack = [];
  let quoteClose = "";
  const text = String(value || "");
  let lastIndex = 0;
  const flush = () => {
    if (current) chunks.push([current, protectedChunk]);
    current = "";
  };
  const feedPlain = (part) => [...String(part || "")].forEach((char) => {
    if (!protectedChunk && bracketOpeners.has(char)) {
      flush();
      protectedChunk = true;
      bracketStack.push(bracketPairs[char]);
      current += char;
      return;
    }
    if (!protectedChunk && quotePairs[char]) {
      flush();
      protectedChunk = true;
      quoteClose = quotePairs[char];
      current += char;
      return;
    }
    current += char;
    if (!protectedChunk) return;
    if (quoteClose) {
      if (char === quoteClose) {
        quoteClose = "";
        if (!bracketStack.length) {
          flush();
          protectedChunk = false;
        }
      }
      return;
    }
    if (bracketOpeners.has(char)) {
      bracketStack.push(bracketPairs[char]);
    } else if (bracketStack.length && char === bracketStack[bracketStack.length - 1]) {
      bracketStack.pop();
      if (!bracketStack.length) {
        flush();
        protectedChunk = false;
      }
    }
  });
  let match = null;
  while ((match = protectedPattern.exec(text)) !== null) {
    feedPlain(text.slice(lastIndex, match.index));
    flush();
    chunks.push([match[0], true]);
    lastIndex = match.index + match[0].length;
  }
  feedPlain(text.slice(lastIndex));
  flush();
  return chunks;
}

function protectSegmentedUrls(value) {
  const replacements = {};
  const parts = segmentedProtectedCleanupChunks(value).map(([chunk, protectedChunk]) => {
    if (!protectedChunk) return chunk;
    const token = `PCSEGTOKEN${Object.keys(replacements).length}X`;
    replacements[token] = chunk;
    return token;
  });
  return [parts.join(""), replacements];
}

function restoreSegmentedUrls(value, replacements) {
  let restored = String(value || "");
  Object.entries(replacements || {}).forEach(([token, original]) => {
    restored = restored.split(token).join(original);
  });
  return restored;
}

function segmentedProtectedSplitWordCount(value, splitWords) {
  const words = Array.isArray(splitWords) ? splitWords.filter((item) => item !== "") : [];
  if (!words.length) return 0;
  let count = 0;
  segmentedProtectedCleanupChunks(value).forEach(([chunk, protectedChunk]) => {
    if (!protectedChunk) return;
    words.forEach((word) => {
      if (!word) return;
      count += Math.max(0, String(chunk).split(word).length - 1);
    });
  });
  return count;
}

function splitSegmentedWordsOutsideProtected(value, splitWords) {
  const words = [...new Set((splitWords || []).filter((item) => item !== ""))]
    .sort((left, right) => right.length - left.length);
  if (!words.length) return [String(value || "")];
  const urlPattern = /^(?:https?:\/\/|www\.)/i;
  const protectedStartsWithSplitWord = (chunk) => {
    const stripped = String(chunk || "").trimStart();
    return words.some((word) => stripped.startsWith(word));
  };
  const segments = [];
  let current = "";
  const pushCurrent = () => {
    if (current) segments.push(current);
    current = "";
  };
  const feedPlain = (chunk) => {
    const text = String(chunk || "");
    let index = 0;
    while (index < text.length) {
      const matched = words.find((word) => text.startsWith(word, index));
      if (matched) {
        let delimiter = matched;
        if (matched === ".") {
          let end = index + matched.length;
          while (end < text.length && text[end] === ".") {
            delimiter += text[end];
            end += 1;
          }
          current += delimiter;
          pushCurrent();
          index = end;
          continue;
        }
        if (["…", "~", "～"].includes(matched)) {
          let end = index + matched.length;
          while (end < text.length && text.startsWith(matched, end)) {
            delimiter += matched;
            end += matched.length;
          }
          current += delimiter;
          pushCurrent();
          index = end;
          continue;
        }
        current += delimiter;
        pushCurrent();
        index += matched.length;
      } else {
        current += text[index];
        index += 1;
      }
    }
  };
  segmentedProtectedCleanupChunks(value).forEach(([chunk, protectedChunk]) => {
    if (protectedChunk) {
      if (current && protectedStartsWithSplitWord(chunk)) pushCurrent();
      current += chunk;
      if (urlPattern.test(String(chunk || "").trim())) pushCurrent();
    } else {
      feedPlain(chunk);
    }
  });
  pushCurrent();
  return segments;
}

function segmentedVisibleLen(value) {
  return String(value || "").replace(/\s+/g, "").length;
}

function segmentedIsSoftShort(value, minChars) {
  const cleaned = String(value || "").replace(/\s+/g, " ").trim();
  if (!cleaned) return false;
  const body = cleaned.replace(/[。！？!?…~～,.，、\s]+$/g, "");
  if (segmentedVisibleLen(cleaned) <= Math.max(1, minChars)) return true;
  if (/(?:\.{2,}|…{1,}|~{2,}|～{2,})$/.test(cleaned)) return false;
  return new Set(["哈哈", "哈", "嗯", "唔", "诶", "欸", "啊", "呀", "我也觉得", "确实", "真的", "对吧", "不是", "那个", "还有"]).has(body);
}

function segmentedJoinPair(left, right) {
  const lhs = String(left || "").trim();
  const rhs = String(right || "").trim();
  if (!lhs) return rhs;
  if (!rhs) return lhs;
  if (/[！？!?]$/.test(lhs)) return `${lhs} ${rhs}`.trim();
  let softened = lhs.replace(/[。…~～]+$/g, "，").replace(/[!?！？]+$/g, "，");
  if (!/[，,、\s]$/.test(softened)) softened += "，";
  return `${softened}${rhs.replace(/^\s+/, "")}`;
}

function segmentedControlValue(root, key) {
  const control = root?.querySelector?.(`[name="${key}"], [data-feature-param="${key}"], [data-feature-detail-toggle="${key}"]`);
  if (!control) {
    if (Object.prototype.hasOwnProperty.call(state.featureDraft || {}, key)) return toBool(state.featureDraft[key]);
    return state.overview?.settings?.[key];
  }
  if (control.type === "checkbox") return Boolean(control.checked);
  if (control.type === "number") return Number(control.value || 0);
  return control.value;
}

function segmentedPreviewValues(root = document) {
  const settings = state.overview?.settings || {};
  const keys = [
    "enable_segmented_proactive_reply",
    "segmented_proactive_scope",
    "segmented_proactive_chat_scope",
    "enable_segmented_proactive_chat_profiles",
    "segmented_proactive_threshold",
    "segmented_proactive_min_segment_chars",
    "segmented_proactive_max_segments",
    "segmented_proactive_send_as_forward",
    "segmented_proactive_voice_strategy",
    "segmented_proactive_image_strategy",
    "segmented_proactive_at_strategy",
    "segmented_proactive_face_strategy",
    "segmented_proactive_component_order",
    "reaction_expression_delivery_mode",
    "segmented_proactive_other_strategy",
    "segmented_proactive_split_mode",
    "segmented_proactive_match_width_variants",
    "segmented_proactive_regex",
    "segmented_proactive_split_words",
    "enable_segmented_proactive_content_cleanup",
    "segmented_proactive_content_cleanup_scope",
    "segmented_proactive_content_cleanup_rule",
    "segmented_proactive_content_cleanup_words",
    "enable_segmented_proactive_content_replacement",
    "segmented_proactive_content_replacements",
    "segmented_proactive_interval_method",
    "segmented_proactive_interval_min",
    "segmented_proactive_interval_max",
    "segmented_proactive_log_base",
  ];
  const values = {};
  keys.forEach((key) => {
    const value = segmentedControlValue(root, key);
    values[key] = value == null ? settings[key] : value;
  });
  values.enable_segmented_proactive_reply = toBool(values.enable_segmented_proactive_reply);
  const masterSegmentedEnabled = values.enable_segmented_proactive_reply;
  values.segmented_proactive_send_as_forward = toBool(values.segmented_proactive_send_as_forward);
  values.segmented_proactive_match_width_variants = values.segmented_proactive_match_width_variants == null
    ? true
    : toBool(values.segmented_proactive_match_width_variants);
  values.enable_segmented_proactive_content_cleanup = toBool(values.enable_segmented_proactive_content_cleanup);
  values.enable_segmented_proactive_content_replacement = toBool(values.enable_segmented_proactive_content_replacement);
  values.segmented_proactive_content_cleanup_scope = String(values.segmented_proactive_content_cleanup_scope || "all");
  values.segmented_proactive_split_words = String(values.segmented_proactive_split_words ?? "");
  values.segmented_proactive_content_cleanup_words = String(values.segmented_proactive_content_cleanup_words ?? "");
  values.segmented_proactive_content_replacements = Array.isArray(values.segmented_proactive_content_replacements)
    ? values.segmented_proactive_content_replacements
    : String(values.segmented_proactive_content_replacements ?? "");
  const chatType = String(root?.querySelector?.("[data-segmented-preview-chat-type]")?.value || "private");
  values.segmented_proactive_preview_chat_type = chatType;
  if (toBool(values.enable_segmented_proactive_chat_profiles)) {
    const prefix = `segmented_proactive_${chatType}_`;
    ["enabled", "scope", "threshold", "min_segment_chars", "max_segments", "send_as_forward", "interval_method", "interval_min", "interval_max", "log_base"].forEach((name) => {
      const key = `${prefix}${name}`;
      const value = segmentedControlValue(root, key);
      if (value != null) values[`segmented_proactive_${name}`] = value;
    });
    if (values.segmented_proactive_enabled != null) {
      values.enable_segmented_proactive_reply = masterSegmentedEnabled && toBool(values.segmented_proactive_enabled);
      values.segmented_proactive_chat_scope = chatType;
    }
  }
  return values;
}

function simulateSegmentedProactive(text, values) {
  let normalized = String(text || "").trim();
  if (!normalized) return { segments: [], status: "请输入一段主动消息示例。" };
  if (!values.enable_segmented_proactive_reply) {
    return { segments: [normalized], status: "主动分段未开启，真实发送会保持一整条。" };
  }
  let replacementCount = 0;
  if (values.enable_segmented_proactive_content_replacement) {
    const [replaced, count] = applySegmentedPreviewReplacements(
      normalized,
      values.segmented_proactive_content_replacements,
    );
    if (count > 0 && replaced.trim()) {
      normalized = replaced.trim();
      replacementCount = count;
    }
  }
  const threshold = Math.max(20, Number(values.segmented_proactive_threshold || 500));
  if (normalized.length > threshold) {
    const replacementText = replacementCount ? `已完成 ${replacementCount} 处内容替换；` : "";
    return { segments: [normalized], status: `${replacementText}文本长度 ${normalized.length} 超过阈值 ${threshold}，真实发送不会分段。` };
  }
  const splitMode = String(values.segmented_proactive_split_mode || "regex");
  const scope = String(values.segmented_proactive_scope || "proactive_only");
  const chatScope = String(values.segmented_proactive_chat_scope || "all");
  const cleanupEnabled = Boolean(values.enable_segmented_proactive_content_cleanup);
  const cleanupScope = String(values.segmented_proactive_content_cleanup_scope || "all");
  const minChars = Math.max(1, Number(values.segmented_proactive_min_segment_chars || 8));
  const maxSegments = Math.max(1, Number(values.segmented_proactive_max_segments || 3));
  const cleanupWords = values.segmented_proactive_match_width_variants
    ? expandSegmentedWidthVariantWords(parseSegmentedWordList(values.segmented_proactive_content_cleanup_words))
    : parseSegmentedWordList(values.segmented_proactive_content_cleanup_words);
  const [protectedNormalized, protectedUrls] = protectSegmentedUrls(normalized);
  let protectedSplitHits = 0;
  let cleanupRegex = null;
  if (cleanupEnabled && splitMode !== "words" && values.segmented_proactive_content_cleanup_rule) {
    cleanupRegex = new RegExp(String(values.segmented_proactive_content_cleanup_rule), "g");
  }
  const cleanSegment = (segment) => {
    const original = String(segment || "");
    let cleaned = "";
    const stripTrailingWords = (value, words) => {
      let next = String(value || "").trimEnd();
      const sortedWords = Array.from(new Set(words.filter((word) => word !== ""))).sort((a, b) => b.length - a.length);
      let changed = true;
      while (changed && next) {
        changed = false;
        for (const word of sortedWords) {
          if (next.endsWith(word)) {
            next = next.slice(0, -word.length).trimEnd();
            changed = true;
            break;
          }
        }
      }
      return next;
    };
    const stripTrailingRegex = (value, pattern) => {
      let next = String(value || "").trimEnd();
      if (!pattern) return next;
      let changed = true;
      while (changed && next) {
        changed = false;
        const matches = Array.from(next.matchAll(pattern));
        const trailing = matches.reverse().find((match) => match.index != null && match.index + match[0].length === next.length && match[0].length > 0);
        if (trailing) {
          next = next.slice(0, trailing.index).trimEnd();
          changed = true;
        }
      }
      return next;
    };
    segmentedProtectedCleanupChunks(original).forEach(([chunk, protectedChunk]) => {
      if (protectedChunk || !cleanupEnabled) {
        cleaned += chunk;
        return;
      }
      let next = chunk;
      if (splitMode === "words") {
        if (cleanupScope === "trailing") {
          next = stripTrailingWords(next, cleanupWords);
        } else {
          cleanupWords.forEach((word) => {
            if (word !== "") next = next.split(word).join("");
          });
        }
      } else if (cleanupRegex) {
        next = cleanupScope === "trailing" ? stripTrailingRegex(next, cleanupRegex) : next.replace(cleanupRegex, "");
      }
      cleaned += next;
    });
    return restoreSegmentedUrls(cleaned.trim(), protectedUrls);
  };
  let rawSegments = [];
  try {
    if (splitMode === "words") {
      const splitWords = values.segmented_proactive_match_width_variants
        ? expandSegmentedWidthVariantWords(parseSegmentedWordList(values.segmented_proactive_split_words))
        : parseSegmentedWordList(values.segmented_proactive_split_words);
      if (!splitWords.includes("\n")) splitWords.push("\n");
      if (!splitWords.length) return { segments: [normalized], status: "分段模式为 words，但分段词为空。" };
      protectedSplitHits = segmentedProtectedSplitWordCount(normalized, splitWords);
      rawSegments = splitSegmentedWordsOutsideProtected(normalized, splitWords);
    } else {
      const pattern = new RegExp(String(values.segmented_proactive_regex || ".*?[。？！~…\\n]+|.+$"), "gms");
      rawSegments = protectedNormalized.match(pattern) || [];
    }
  } catch (error) {
    return { segments: [normalized], error: `分段规则无法解析：${error.message}` };
  }
  let segments = rawSegments.map(cleanSegment).filter(Boolean);
  if (segments.length > 1) {
    const merged = [];
    let index = 0;
    while (index < segments.length) {
      let current = segments[index];
      while (
        index + 1 < segments.length &&
        (segmentedVisibleLen(current) < minChars || segmentedIsSoftShort(current, minChars) || merged.length >= Math.max(0, maxSegments - 1))
      ) {
        current = segmentedJoinPair(current, segments[index + 1]);
        index += 1;
      }
      if (merged.length && (segmentedVisibleLen(current) < minChars || segmentedIsSoftShort(current, minChars))) {
        merged[merged.length - 1] = segmentedJoinPair(merged[merged.length - 1], current);
      } else {
        merged.push(current);
      }
      index += 1;
    }
    if (merged.length > maxSegments) {
      const kept = merged.slice(0, maxSegments - 1);
      let tail = merged[maxSegments - 1];
      merged.slice(maxSegments).forEach((item) => {
        tail = segmentedJoinPair(tail, item);
      });
      segments = kept.concat(tail);
    } else {
      segments = merged;
    }
  }
  if (!segments.length || (segments.length <= 1 && !cleanupEnabled)) {
    return { segments: [normalized], status: "当前规则没有产生有效分段，真实发送会保持一整条。" };
  }
  const scopeText = scope === "all_llm" ? "插件主动与普通 LLM 纯文本回复都会使用此规则" : "仅插件主动消息使用此规则";
  const chatScopeText = chatScope === "private" ? "；仅私聊生效" : chatScope === "group" ? "；仅群聊生效" : "";
  const sendText = values.segmented_proactive_send_as_forward && segments.length > 1 ? "；真实发送会优先打包成合并消息" : "";
  const protectedText = protectedSplitHits ? `；${protectedSplitHits} 个分隔符位于括号/引号/网址内，已按保护规则跳过` : "";
  const replacementText = replacementCount ? `；已完成 ${replacementCount} 处内容替换` : "";
  return { segments, status: `预计发送 ${segments.length} 段；${scopeText}${chatScopeText}${sendText}${protectedText}${replacementText}。` };
}

function normalizeSegmentedComponentStrategy(value, fallback = "separate") {
  const aliases = {
    embed: "inline",
    embedded: "inline",
    same_message: "inline",
    standalone: "separate",
    separate_before: "separate",
    separate_after: "separate",
    follow_previous: "previous",
    follow_next: "next",
  };
  const normalized = aliases[String(value || "").trim().toLowerCase()] || String(value || "").trim().toLowerCase();
  return ["inline", "separate", "previous", "next"].includes(normalized) ? normalized : fallback;
}

const segmentedComponentOrderDefault = Object.freeze(["voice", "at", "text", "face", "image", "other", "reaction"]);
const segmentedComponentOrderLabels = Object.freeze({
  voice: "语音",
  at: "@",
  text: "正文",
  face: "平台表情",
  image: "图片",
  other: "附件",
  reaction: "表情包",
});

function normalizeSegmentedComponentOrder(value) {
  let source = value;
  if (typeof source === "string") {
    const raw = source.trim();
    if (!raw) source = [];
    else {
      try {
        const parsed = JSON.parse(raw);
        source = Array.isArray(parsed) ? parsed : raw.split(/[\s,，、]+/);
      } catch {
        source = raw.split(/[\s,，、]+/);
      }
    }
  }
  if (!Array.isArray(source)) source = [];
  const result = [];
  source.forEach((item) => {
    const kind = String(item || "").trim().toLowerCase();
    if (Object.prototype.hasOwnProperty.call(segmentedComponentOrderLabels, kind) && !result.includes(kind)) result.push(kind);
  });
  segmentedComponentOrderDefault.forEach((kind) => {
    if (!result.includes(kind)) result.push(kind);
  });
  return result;
}

function segmentedComponentOrderEditorHtml(value, accessibility = {}) {
  const order = normalizeSegmentedComponentOrder(value);
  const editorAttrs = featureSettingAccessibilityAttrs(accessibility);
  const items = order.map((kind, index) => `
    <div class="segmented-order-item" data-order-kind="${escapeHtml(kind)}" draggable="true" tabindex="0" role="listitem" aria-label="${escapeHtml(`${index + 1}. ${segmentedComponentOrderLabels[kind]}`)}">
      <button type="button" class="segmented-order-drag" data-order-drag title="拖动排序" aria-label="拖动${escapeHtml(segmentedComponentOrderLabels[kind])}">⋮⋮</button>
      <span class="segmented-order-swatch is-${escapeHtml(kind)}" aria-hidden="true"></span>
      <b>${escapeHtml(segmentedComponentOrderLabels[kind])}</b>
      <span class="segmented-order-actions">
        <button type="button" data-order-move="up" title="上移" aria-label="上移${escapeHtml(segmentedComponentOrderLabels[kind])}">↑</button>
        <button type="button" data-order-move="down" title="下移" aria-label="下移${escapeHtml(segmentedComponentOrderLabels[kind])}">↓</button>
      </span>
    </div>
  `).join("");
  return `
    <div class="segmented-order-editor" data-segmented-component-order-editor${editorAttrs}>
      <textarea data-feature-param="segmented_proactive_component_order" hidden aria-hidden="true">${escapeHtml(JSON.stringify(order))}</textarea>
      <div class="segmented-order-toolbar">
        <span>拖动或使用箭头调整先后</span>
        <button type="button" data-order-reset title="恢复默认顺序">恢复默认</button>
      </div>
      <div class="segmented-order-list" data-order-list role="list" aria-label="组件先后顺序">${items}</div>
      <p class="segmented-order-lock-note"><span aria-hidden="true">↳</span> 引用固定跟随第一段正文</p>
      <span class="segmented-order-live" data-order-live aria-live="polite"></span>
    </div>
  `;
}

function bindSegmentedComponentOrderEditor(root = document) {
  root.querySelectorAll?.("[data-segmented-component-order-editor]").forEach((editor) => {
    if (editor.dataset.segmentedOrderBound) return;
    editor.dataset.segmentedOrderBound = "1";
    const hidden = editor.querySelector("[data-feature-param='segmented_proactive_component_order']");
    const list = editor.querySelector("[data-order-list]");
    const live = editor.querySelector("[data-order-live]");
    if (!hidden || !list) return;
    const moveItem = (item, delta) => {
      const items = [...list.querySelectorAll("[data-order-kind]")];
      const index = items.indexOf(item);
      const target = index + delta;
      if (index < 0 || target < 0 || target >= items.length) return false;
      if (delta < 0) list.insertBefore(item, items[target]);
      else list.insertBefore(items[target], item);
      return true;
    };
    const sync = (message = "") => {
      const order = [...list.querySelectorAll("[data-order-kind]")].map((item) => item.dataset.orderKind);
      hidden.value = JSON.stringify(normalizeSegmentedComponentOrder(order));
      list.querySelectorAll("[data-order-kind]").forEach((item, index) => {
        item.setAttribute("aria-label", `${index + 1}. ${segmentedComponentOrderLabels[item.dataset.orderKind] || item.dataset.orderKind}`);
      });
      rememberFeatureParamDraft(hidden);
      markFeatureDetailDirty();
      if (live && message) live.textContent = message;
      renderSegmentedPreview();
    };
    editor.querySelector("[data-order-reset]")?.addEventListener("click", () => {
      const current = [...list.querySelectorAll("[data-order-kind]")];
      const byKind = new Map(current.map((item) => [item.dataset.orderKind, item]));
      segmentedComponentOrderDefault.forEach((kind) => {
        const item = byKind.get(kind);
        if (item) list.appendChild(item);
      });
      sync("已恢复默认顺序");
    });
    list.querySelectorAll("[data-order-kind]").forEach((item) => {
      item.querySelectorAll("[data-order-move]").forEach((button) => {
        button.addEventListener("click", () => {
          const moved = moveItem(item, button.dataset.orderMove === "up" ? -1 : 1);
          if (moved) sync(`${segmentedComponentOrderLabels[item.dataset.orderKind]}已${button.dataset.orderMove === "up" ? "上移" : "下移"}`);
        });
      });
      item.addEventListener("keydown", (event) => {
        if (!["ArrowUp", "ArrowDown"].includes(event.key)) return;
        event.preventDefault();
        const moved = moveItem(item, event.key === "ArrowUp" ? -1 : 1);
        if (moved) {
          item.focus();
          sync(`${segmentedComponentOrderLabels[item.dataset.orderKind]}已${event.key === "ArrowUp" ? "上移" : "下移"}`);
        }
      });
      item.addEventListener("dragstart", (event) => {
        item.classList.add("is-dragging");
        event.dataTransfer?.setData("text/plain", item.dataset.orderKind || "");
        if (event.dataTransfer) event.dataTransfer.effectAllowed = "move";
      });
      item.addEventListener("dragend", () => {
        item.classList.remove("is-dragging");
        const current = [...list.querySelectorAll("[data-order-kind]")].map((entry) => entry.dataset.orderKind);
        if (hidden.value !== JSON.stringify(normalizeSegmentedComponentOrder(current))) {
          sync(`${segmentedComponentOrderLabels[item.dataset.orderKind]}已移动`);
        }
      });
      item.addEventListener("dragover", (event) => {
        event.preventDefault();
        const dragging = list.querySelector(".is-dragging");
        if (!dragging || dragging === item) return;
        const rect = item.getBoundingClientRect();
        const sameRow = event.clientY >= rect.top && event.clientY <= rect.bottom;
        const insertBefore = sameRow
          ? event.clientX < rect.left + rect.width / 2
          : event.clientY < rect.top + rect.height / 2;
        list.insertBefore(dragging, insertBefore ? item : item.nextSibling);
      });
      item.addEventListener("drop", (event) => {
        event.preventDefault();
        const dragging = list.querySelector(".is-dragging");
        if (dragging) sync(`${segmentedComponentOrderLabels[dragging.dataset.orderKind]}已移动`);
      });
    });
  });
}

function segmentedComponentPreviewPlan(values, segments) {
  if (!(segments || []).length) return { chunks: [], hasMedia: false };
  const order = normalizeSegmentedComponentOrder(values.segmented_proactive_component_order);
  const itemForKind = {
    voice: { kind: "voice", label: "语音" },
    at: { kind: "at", label: "@" },
    face: { kind: "face", label: "平台表情" },
    image: { kind: "image", label: "图片" },
    other: { kind: "other", label: "附件" },
    reaction: { kind: "reaction", label: "表情包" },
  };
  const units = [];
  order.forEach((kind) => {
    if (kind === "text") {
      (segments || []).forEach((segment, index) => units.push([{ kind: "text", label: `正文 ${index + 1}`, title: String(segment || "") }]));
    } else if (itemForKind[kind]) units.push([itemForKind[kind]]);
  });
  const chunks = [];
  const pendingNext = [];
  units.forEach((unit) => {
    const item = unit[0];
    if (item.kind === "text") {
      chunks.push([...pendingNext.splice(0), ...unit]);
      return;
    }
    const strategyKey = item.kind === "reaction" ? "reaction_expression_delivery_mode" : `segmented_proactive_${item.kind}_strategy`;
    const fallback = item.kind === "at" || item.kind === "face" ? "inline" : "separate";
    let strategy = item.kind === "reaction" && String(values.reaction_expression_delivery_mode || "separate_after") !== "same_message"
      ? "separate"
      : normalizeSegmentedComponentStrategy(values[strategyKey], fallback);
    if (strategy === "separate") chunks.push([...unit]);
    else if (strategy === "previous") {
      if (chunks.length) chunks[chunks.length - 1].push(...unit);
      else chunks.push([...unit]);
    } else if (strategy === "next") pendingNext.push(...unit);
    else if (chunks.length && chunks[chunks.length - 1].some((entry) => entry.kind === "text")) chunks[chunks.length - 1].push(...unit);
    else pendingNext.push(...unit);
  });
  if (pendingNext.length) chunks.push([...pendingNext]);
  const textTarget = chunks.findIndex((chunk) => chunk.some((item) => item.kind === "text"));
  if (textTarget >= 0) chunks[textTarget].unshift({ kind: "reply", label: "引用" });
  return { chunks, hasMedia: true };
}

function segmentedPreviewPanelHtml() {
  return `
    <section class="segmented-preview-panel wide-field" data-segmented-preview-panel>
      <header>
        <div>
          <h4>分段效果预览</h4>
        </div>
        <div class="segmented-preview-actions">
          <label class="segmented-preview-chat-type"><span>预览会话</span><select data-segmented-preview-chat-type><option value="private">私聊</option><option value="group">群聊</option></select></label>
          <button type="button" data-segmented-example="simple">简单示例</button>
          <button type="button" data-segmented-example="complex">复杂示例</button>
        </div>
      </header>
      <textarea data-segmented-preview-input rows="4"></textarea>
      <div data-segmented-preview-output class="segmented-preview-output"></div>
    </section>
  `;
}

function renderSegmentedPreview(panel = null) {
  const targetPanels = panel ? [panel] : Array.from(document.querySelectorAll("[data-segmented-preview-panel], .segmented-preview-panel"));
  targetPanels.forEach((previewPanel) => {
    const input = previewPanel.querySelector("[data-segmented-preview-input], #segmentedPreviewInput");
    const output = previewPanel.querySelector("[data-segmented-preview-output], #segmentedPreviewOutput");
    if (!input || !output) return;
    const root = previewPanel.closest("[data-feature-param-form]") || document;
    if (!input.value) input.value = segmentedPreviewExamples.simple;
    let result;
    try {
      result = simulateSegmentedProactive(input.value, segmentedPreviewValues(root));
    } catch (error) {
      result = { segments: [], error: error.message };
    }
    if (result.error) {
      output.innerHTML = `<div class="segmented-preview-error">${escapeHtml(result.error)}</div>`;
      return;
    }
    const segments = result.segments || [];
    const componentPlan = segmentedComponentPreviewPlan(segmentedPreviewValues(root), segments);
    const componentFlow = componentPlan.chunks.map((chunk, chunkIndex) => `
      <span class="segmented-component-message" role="listitem" aria-label="第 ${chunkIndex + 1} 条消息">
        ${chunk.map((item) => `<span class="segmented-component-chip is-${escapeHtml(item.kind)}"${item.title ? ` title="${escapeHtml(item.title)}"` : ""}>${escapeHtml(item.label)}</span>`).join('<span class="segmented-component-plus">+</span>')}
      </span>
    `).join('<span class="segmented-component-separator" aria-hidden="true">|</span>');
    const forwardComponentNote = segmentedPreviewValues(root).segmented_proactive_send_as_forward
      ? "含组件时不会打包为纯文本合并转发"
      : "竖线表示下一条独立消息";
    output.innerHTML = `
      <div class="segmented-preview-summary">
        <span>${escapeHtml(result.status || "")}</span>
        <span>原文 ${escapeHtml(String(input.value || "").length)} 字</span>
        <span>保护：网址内部不拆，链接结束可断；括号 / 双引号内部不拆</span>
        <span>空格可写作 &lt;space&gt; 或 空格</span>
      </div>
      <section class="segmented-component-preview" aria-live="polite">
        <header>
          <b>组件发送顺序</b>
          <span>${escapeHtml(forwardComponentNote)}</span>
        </header>
        <div class="segmented-component-flow" role="list">${componentFlow}</div>
      </section>
      <div class="segmented-preview-list">
        ${segments.map((segment, index) => `
          <section class="segmented-preview-segment">
            <b>${escapeHtml(index + 1)}</b>
            <p>${escapeHtml(segment)}</p>
          </section>
        `).join("")}
      </div>
    `;
  });
}

function segmentedConfigControlShell(control) {
  return control?.closest?.(".feature-param-row, label, .toggle-row") || null;
}

function updateSegmentedConfigVisibility(root = document) {
  const values = segmentedPreviewValues(root);
  const mode = String(values.segmented_proactive_split_mode || "regex");
  const cleanupEnabled = Boolean(values.enable_segmented_proactive_content_cleanup);
  const intervalMethod = String(values.segmented_proactive_interval_method || "log");
  const independentProfiles = toBool(values.enable_segmented_proactive_chat_profiles);
  const privateEnabled = toBool(segmentedControlValue(root, "segmented_proactive_private_enabled"));
  const groupEnabled = toBool(segmentedControlValue(root, "segmented_proactive_group_enabled"));
  const privateIntervalMethod = String(segmentedControlValue(root, "segmented_proactive_private_interval_method") || "log");
  const groupIntervalMethod = String(segmentedControlValue(root, "segmented_proactive_group_interval_method") || "log");
  const visibility = {
    segmented_proactive_chat_scope: !independentProfiles,
    segmented_proactive_scope: !independentProfiles,
    segmented_proactive_threshold: !independentProfiles,
    segmented_proactive_min_segment_chars: !independentProfiles,
    segmented_proactive_max_segments: !independentProfiles,
    segmented_proactive_send_as_forward: !independentProfiles,
    segmented_proactive_interval_method: !independentProfiles,
    segmented_proactive_interval_min: !independentProfiles && intervalMethod === "random",
    segmented_proactive_interval_max: !independentProfiles && intervalMethod === "random",
    segmented_proactive_log_base: !independentProfiles && intervalMethod === "log",
    segmented_proactive_private_enabled: independentProfiles,
    segmented_proactive_private_scope: independentProfiles && privateEnabled,
    segmented_proactive_private_threshold: independentProfiles && privateEnabled,
    segmented_proactive_private_min_segment_chars: independentProfiles && privateEnabled,
    segmented_proactive_private_max_segments: independentProfiles && privateEnabled,
    segmented_proactive_private_send_as_forward: independentProfiles && privateEnabled,
    segmented_proactive_private_interval_method: independentProfiles && privateEnabled,
    segmented_proactive_private_interval_min: independentProfiles && privateEnabled && privateIntervalMethod === "random",
    segmented_proactive_private_interval_max: independentProfiles && privateEnabled && privateIntervalMethod === "random",
    segmented_proactive_private_log_base: independentProfiles && privateEnabled && privateIntervalMethod === "log",
    segmented_proactive_group_enabled: independentProfiles,
    segmented_proactive_group_scope: independentProfiles && groupEnabled,
    segmented_proactive_group_threshold: independentProfiles && groupEnabled,
    segmented_proactive_group_min_segment_chars: independentProfiles && groupEnabled,
    segmented_proactive_group_max_segments: independentProfiles && groupEnabled,
    segmented_proactive_group_send_as_forward: independentProfiles && groupEnabled,
    segmented_proactive_group_interval_method: independentProfiles && groupEnabled,
    segmented_proactive_group_interval_min: independentProfiles && groupEnabled && groupIntervalMethod === "random",
    segmented_proactive_group_interval_max: independentProfiles && groupEnabled && groupIntervalMethod === "random",
    segmented_proactive_group_log_base: independentProfiles && groupEnabled && groupIntervalMethod === "log",
    segmented_proactive_regex: mode === "regex",
    segmented_proactive_match_width_variants: mode === "words",
    segmented_proactive_split_words: mode === "words",
    segmented_proactive_content_cleanup_scope: cleanupEnabled,
    segmented_proactive_content_cleanup_rule: cleanupEnabled && mode === "regex",
    segmented_proactive_content_cleanup_words: cleanupEnabled && mode === "words",
    segmented_proactive_content_replacements: Boolean(values.enable_segmented_proactive_content_replacement),
  };
  Object.entries(visibility).forEach(([key, visible]) => {
    root.querySelectorAll(`[name="${key}"], [data-feature-param="${key}"]`).forEach((control) => {
      const shell = segmentedConfigControlShell(control);
      if (shell) shell.classList.toggle("segmented-config-hidden", !visible);
    });
  });
}

function bindSegmentedPreview(root = document) {
  const scope = root || document;
  bindSegmentedComponentOrderEditor(scope);
  scope.querySelectorAll("[data-segmented-preview-panel], .segmented-preview-panel").forEach((panel) => {
    const input = panel.querySelector("[data-segmented-preview-input], #segmentedPreviewInput");
    if (input && !input.dataset.segmentedPreviewBound) {
      input.dataset.segmentedPreviewBound = "1";
      input.addEventListener("input", () => renderSegmentedPreview(panel));
    }
    panel.querySelectorAll("[data-segmented-example]").forEach((button) => {
      if (button.dataset.segmentedPreviewBound) return;
      button.dataset.segmentedPreviewBound = "1";
      button.addEventListener("click", () => {
        if (!input) return;
        input.value = segmentedPreviewExamples[button.dataset.segmentedExample] || segmentedPreviewExamples.simple;
        renderSegmentedPreview(panel);
      });
    });
  });
  const controls = scope.querySelectorAll('[name^="segmented_proactive_"], [name="reaction_expression_delivery_mode"], [name="enable_segmented_proactive_reply"], [name="enable_segmented_proactive_content_cleanup"], [name="enable_segmented_proactive_content_replacement"], [data-feature-param^="segmented_proactive_"], [data-feature-param="reaction_expression_delivery_mode"], [data-feature-param="enable_segmented_proactive_content_cleanup"], [data-feature-param="enable_segmented_proactive_content_replacement"], [data-feature-detail-toggle="enable_segmented_proactive_reply"]');
  controls.forEach((control) => {
    if (control.dataset.segmentedConfigBound) return;
    control.dataset.segmentedConfigBound = "1";
    const handler = () => {
      const owner = control.closest("[data-feature-param-form]") || scope;
      updateSegmentedConfigVisibility(owner);
      renderSegmentedPreview();
    };
    control.addEventListener("input", handler);
    control.addEventListener("change", handler);
  });
  scope.querySelectorAll("[data-segmented-preview-chat-type]").forEach((control) => {
    if (control.dataset.segmentedPreviewChatTypeBound) return;
    control.dataset.segmentedPreviewChatTypeBound = "1";
    control.addEventListener("change", () => renderSegmentedPreview());
  });
  scope.querySelectorAll("[data-feature-param-form]").forEach((form) => updateSegmentedConfigVisibility(form));
  renderSegmentedPreview();
}

function normalizeGroupIdList(value) {
  const source = Array.isArray(value) ? value.join("\n") : String(value || "");
  const seen = new Set();
  return source
    .split(/[\s,，;；、]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .filter((item) => {
      if (seen.has(item)) return false;
      seen.add(item);
      return true;
    });
}

function accessDraftFromForm(group = {}) {
  const whitelistInput = $("#groupWhitelist");
  const blacklistInput = $("#groupBlacklist");
  return {
    mode: $("#groupAccessMode")?.value || group.access_mode || "whitelist",
    whitelist: new Set(normalizeGroupIdList(whitelistInput ? whitelistInput.value : group.whitelist || [])),
    blacklist: new Set(normalizeGroupIdList(blacklistInput ? blacklistInput.value : group.blacklist || [])),
  };
}

function writeAccessDraft(draft) {
  $("#groupAccessMode").value = draft.mode || "whitelist";
  $("#groupWhitelist").value = [...draft.whitelist].join("\n");
  $("#groupBlacklist").value = [...draft.blacklist].join("\n");
}

function groupAllowedByDraft(groupId, draft) {
  const id = String(groupId || "");
  return draft.mode === "blacklist" ? !draft.blacklist.has(id) : draft.whitelist.has(id);
}

function groupListMark(groupId, draft) {
  const id = String(groupId || "");
  if (draft.whitelist.has(id) && draft.blacklist.has(id)) return "白名单 + 黑名单";
  if (draft.whitelist.has(id)) return "白名单";
  if (draft.blacklist.has(id)) return "黑名单";
  return "未列入";
}

function renderAccessManager(group) {
  const draft = accessDraftFromForm(group);
  const mode = draft.mode === "blacklist" ? "blacklist" : "whitelist";
  $("#groupAccessMode").value = mode;
  document.querySelectorAll("[name='groupAccessModeChoice']").forEach((input) => {
    input.checked = input.value === mode;
  });

  const knownGroups = state.groups || [];
  const allowedCount = knownGroups.filter((item) => groupAllowedByDraft(item.group_id, draft)).length;
  const blockedCount = Math.max(0, knownGroups.length - allowedCount);
  const warning = mode === "whitelist" && draft.whitelist.size === 0
    ? "未观察任何群"
    : mode === "blacklist" && draft.blacklist.size === 0
      ? "未拦截群"
      : "已配置";
  $("#accessSummary").innerHTML = `
    <section class="access-summary-card ${mode}">
      <span>当前模式</span>
      <b>${escapeHtml(mode === "blacklist" ? "黑名单" : "白名单")}</b>
      <small>${escapeHtml(warning)}</small>
    </section>
    <section class="access-summary-card ok">
      <span>允许群</span>
      <b>${escapeHtml(allowedCount)}</b>
      <small>已记录群</small>
    </section>
    <section class="access-summary-card blocked">
      <span>拦截群</span>
      <b>${escapeHtml(blockedCount)}</b>
      <small>已记录群</small>
    </section>
    <section class="access-summary-card">
      <span>名单规模</span>
      <b>${escapeHtml(draft.whitelist.size)} / ${escapeHtml(draft.blacklist.size)}</b>
      <small>白名单 / 黑名单</small>
    </section>
  `;

  $("#accessQuickGroups").innerHTML = knownGroups.length
    ? knownGroups.map((item) => {
      const groupId = String(item.group_id || "");
      const inWhite = draft.whitelist.has(groupId);
      const inBlack = draft.blacklist.has(groupId);
      const allowed = groupAllowedByDraft(groupId, draft);
      return `
        <section class="access-group-card ${allowed ? "ok" : "blocked"}">
          <div>
            <b>${escapeHtml(groupId)}</b>
            <span>${escapeHtml(allowed ? "允许" : "拦截")} · ${escapeHtml(groupListMark(groupId, draft))}</span>
            <small>消息 ${escapeHtml(item.message_count || 0)} · 最近 ${escapeHtml(item.last_seen || "未知")}</small>
          </div>
          <div class="access-group-actions">
            <button type="button" data-access-action="white" data-access-group="${escapeHtml(groupId)}">${escapeHtml(inWhite ? "移出白名单" : "加入白名单")}</button>
            <button type="button" data-access-action="black" data-access-group="${escapeHtml(groupId)}">${escapeHtml(inBlack ? "移出黑名单" : "加入黑名单")}</button>
          </div>
        </section>
      `;
    }).join("")
    : `<div class="empty small">暂无群聊记录</div>`;

  renderListCoverage(group, draft);
}

function renderListCoverage(group, draft = null) {
  const access = draft || {
    mode: group.access_mode || "whitelist",
    whitelist: new Set(normalizeGroupIdList(group.whitelist || [])),
    blacklist: new Set(normalizeGroupIdList(group.blacklist || [])),
  };
  const rows = state.groups.map((item) => {
    const groupId = String(item.group_id || "");
    const allowed = groupAllowedByDraft(groupId, access);
    return `
      <div class="coverage-item ${allowed ? "ok" : "blocked"}">
        <b>${escapeHtml(groupId)}</b>
        <span>${escapeHtml(allowed ? "允许" : "拦截")} · ${escapeHtml(groupListMark(groupId, access))}</span>
      </div>
    `;
  });
  $("#listCoverage").innerHTML = rows.length ? rows.join("") : `<div class="empty small">暂无群聊记录</div>`;
}

function featureEnabledForFilter(key) {
  return toBool(state.featureDraft?.[key]) || featureTemporarilyUnlockedByProactiveOnly(key);
}

function featureMatchesStatusFilter(key, status = state.featureStatusFilter) {
  if (status === "enabled") return featureEnabledForFilter(key);
  if (status === "disabled") return !featureEnabledForFilter(key);
  return true;
}

function featureMatchesQueryFilter(key, query) {
  if (!query) return true;
  const stageText = featureStagesForKey(key)
    .flatMap((stage) => [featureStageLabel(stage), featureStageLabel(stage, true)])
    .join(" ");
  return `${featureSearchText(key)} ${featureGroupForKey(key)} ${stageText}`.toLowerCase().includes(query);
}

const imageGenerationFeatureUses = {
  enable_photo_text_action: "主动/用户生图",
  enable_qzone_integration: "空间配图",
  enable_creative_writing: "作品封面",
};

function imageGenerationFeatureUse(key) {
  return imageGenerationFeatureUses[topLevelFeatureKey(key)] || "";
}

function featureMatchesDomainFilter(key, domain = state.featureDomainFilter) {
  if (domain === "all") return true;
  if (domain === "image_generation") {
    return anyImageGeneratorInstalled() && Boolean(imageGenerationFeatureUse(key));
  }
  return featureGroupForKey(key) === domain;
}

function featureMatchesCurrentFilters(key, { ignore = "" } = {}) {
  const query = ($("#featureFilter")?.value || "").trim().toLowerCase();
  if (ignore !== "query" && !featureMatchesQueryFilter(key, query)) return false;
  if (ignore !== "domain" && !featureMatchesDomainFilter(key)) return false;
  if (ignore !== "stage" && state.featureStageFilter !== "all" && !featureStagesForKey(key).includes(state.featureStageFilter)) return false;
  if (ignore !== "status" && !featureMatchesStatusFilter(key)) return false;
  return true;
}

function renderFeatureFilterControls(groups, allKeys, visibleCount) {
  const domainOptions = [
    { title: "all", label: "全部领域" },
    ...(anyImageGeneratorInstalled() ? [{ title: "image_generation", label: "生图", capability: true }] : []),
    ...groups.map((group) => ({ title: group.title, label: group.title })),
  ];
  $("#featureDomainFilters").innerHTML = domainOptions.map((option) => {
    const count = allKeys.filter((key) => (
      featureMatchesDomainFilter(key, option.title)
      && featureMatchesCurrentFilters(key, { ignore: "domain" })
    )).length;
    const active = state.featureDomainFilter === option.title;
    return `<button type="button" data-feature-domain-filter="${escapeHtml(option.title)}" class="${[active ? "is-active" : "", option.capability ? "is-capability" : ""].filter(Boolean).join(" ")}" role="tab" aria-selected="${active ? "true" : "false"}"><span>${escapeHtml(option.label)}</span><small>${count}</small></button>`;
  }).join("");

  const stageOptions = [{ id: "all", label: "全部阶段" }, ...featureStageDefinitions];
  $("#featureStageFilters").innerHTML = stageOptions.map((option) => {
    const count = allKeys.filter((key) => (
      (option.id === "all" || featureStagesForKey(key).includes(option.id))
      && featureMatchesCurrentFilters(key, { ignore: "stage" })
    )).length;
    const active = state.featureStageFilter === option.id;
    return `<button type="button" data-feature-stage-filter="${escapeHtml(option.id)}" class="${active ? "is-active" : ""}" aria-pressed="${active ? "true" : "false"}"><span>${escapeHtml(option.label)}</span><small>${count}</small></button>`;
  }).join("");

  const statusOptions = [
    { id: "all", label: "全部状态" },
    { id: "enabled", label: "已开启" },
    { id: "disabled", label: "已关闭" },
  ];
  $("#featureStatusFilters").innerHTML = statusOptions.map((option) => {
    const count = allKeys.filter((key) => featureMatchesStatusFilter(key, option.id) && featureMatchesCurrentFilters(key, { ignore: "status" })).length;
    const active = state.featureStatusFilter === option.id;
    return `<button type="button" data-feature-status-filter="${escapeHtml(option.id)}" class="${active ? "is-active" : ""}" aria-pressed="${active ? "true" : "false"}"><span>${escapeHtml(option.label)}</span><small>${count}</small></button>`;
  }).join("");

  const result = $("#featureFilterResult");
  if (result) result.innerHTML = `<b>${visibleCount}</b><span>/ ${allKeys.length} 项</span>`;
}

function bindFeatureFilterControls() {
  document.querySelectorAll("[data-feature-domain-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.featureDomainFilter = button.dataset.featureDomainFilter || "all";
      renderFeatureSwitches();
    });
  });
  document.querySelectorAll("[data-feature-stage-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.featureStageFilter = button.dataset.featureStageFilter || "all";
      renderFeatureSwitches();
    });
  });
  document.querySelectorAll("[data-feature-status-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.featureStatusFilter = button.dataset.featureStatusFilter || "all";
      renderFeatureSwitches();
    });
  });
}

function renderFeatureSwitches() {
  if (
    state.featureDetailSubpage === "photo_reference_library"
    && (state.photoReferenceSubmitting || state.photoReferenceAddDialogOpen)
  ) return;
  const filter = ($("#featureFilter")?.value || "").trim().toLowerCase();
  renderIsolationModeCards();
  renderPassiveInjectionPositionForm();
  const knownKeys = new Set(featureGroups.flatMap((group) => group.keys));
  const extraKeys = Object.keys(state.featureDraft || {}).filter((key) => !knownKeys.has(key) && visibleFeatureSwitchKey(key));
  const groups = extraKeys.length
    ? [...featureGroups, { title: "其他", note: "来自配置但暂未归入固定分组的开关。", keys: extraKeys }]
    : featureGroups;
  const overviewSettings = state.overview?.settings || {};
  const intensity = state.overview?.proactive_intensity || {};
  const intensitySearchText = "主动强度预设 主动触达 proactive_intensity_preset 私聊主动 群聊唤醒 群主动插话";
  const visibleDraftKeys = visibleTopLevelFeatureKeys(state.featureDraft || {});
  const total = visibleDraftKeys.length;
  const enabled = visibleDraftKeys.filter((key) => toBool(state.featureDraft[key])).length;
  const proactiveLocked = visibleDraftKeys.filter((key) => featureLockedByProactiveOnlyMode(key)).length;
  const riskyEnabled = ["enable_group_interjection", "enable_bilibili_boredom_watch", isPrivateReadingAvailable() ? "enable_private_reading_boredom_read" : "", isPrivateReadingAvailable() ? "enable_private_reading_ask_recommendation" : "", "enable_goodnight_screen_check", "enable_unanswered_screen_peek_followup"]
    .filter((key) => toBool(state.featureDraft[key])).length;
  const activeSafeFeatureKeys = safeFeatureKeys.filter((key) => !featureLockedByProactiveOnlyMode(key));
  $("#featureSwitchSummary").innerHTML = `
    <section class="feature-summary-card ok">
      <span>已开启</span>
      <b>${escapeHtml(enabled)} / ${escapeHtml(total)}</b>
      <small>当前主开关</small>
    </section>
    <section class="feature-summary-card">
      <span>基础安全项</span>
      <b>${escapeHtml(activeSafeFeatureKeys.filter((key) => toBool(state.featureDraft[key])).length)} / ${escapeHtml(activeSafeFeatureKeys.length)}</b>
      <small>${escapeHtml(proactiveOnlyModeEnabled() ? "已排除模式锁定项" : "隐私、记忆、回复稳定性")}</small>
    </section>
    <section class="feature-summary-card ${riskyEnabled ? "warn" : ""}">
      <span>${escapeHtml(proactiveOnlyModeEnabled() ? "模式锁定" : "高主动子项")}</span>
      <b>${escapeHtml(proactiveOnlyModeEnabled() ? proactiveLocked : riskyEnabled)}</b>
      <small>${escapeHtml(proactiveOnlyModeEnabled() ? "被动能力已关闭" : "含详情页子开关")}</small>
    </section>
  `;

  if (embeddedFeatureParentByKey[state.selectedFeatureKey]) {
    state.selectedFeatureKey = embeddedFeatureParentByKey[state.selectedFeatureKey];
  }
  if (state.selectedFeatureKey !== "enable_photo_text_action") {
    state.featureDetailSubpage = "";
    state.photoReferenceManagerDraft = null;
  }
  const standaloneFeatureKeys = new Set(["enable_proactive_only_mode", "enable_multi_persona_mode"]);
  if (state.selectedFeatureKey && !standaloneFeatureKeys.has(state.selectedFeatureKey) && !visibleFeatureSwitchKey(state.selectedFeatureKey)) {
    state.selectedFeatureKey = "";
  }
  if (state.selectedFeatureKey && Object.prototype.hasOwnProperty.call(state.featureDraft || {}, state.selectedFeatureKey)) {
    beginFeatureDetailSession(state.selectedFeatureKey);
  }
  const inFeatureDetail = Boolean(state.selectedFeatureKey && Object.prototype.hasOwnProperty.call(state.featureDraft || {}, state.selectedFeatureKey));
  const filterWorkspace = $("#featureFilterWorkspace");
  if (filterWorkspace) filterWorkspace.hidden = inFeatureDetail;
  syncFeatureFooterAction();
  if (inFeatureDetail) {
    const result = $("#featureFilterResult");
    if (result) result.innerHTML = `<span>${escapeHtml(featureGroupForKey(state.selectedFeatureKey))}</span><b>${escapeHtml(featureStageLabel(featureStagesForKey(state.selectedFeatureKey)[0], true))}</b>`;
    const multiPersonaDetail = state.selectedFeatureKey === "enable_multi_persona_mode";
    $("#featureFlags").innerHTML = multiPersonaDetail
      ? multiPersonaFeatureDetailPage()
      : featureDetailPage(state.selectedFeatureKey);
    if (multiPersonaDetail) renderPersonaConfigManagement();
    captureFeatureDetailBaselineFromDom($("#featureFlags"));
    bindFeatureDetailActions();
    syncFeatureFooterAction();
    return;
  }

  const filteredKeys = visibleDraftKeys.filter((key) => featureMatchesCurrentFilters(key));
  renderFeatureFilterControls(groups, visibleDraftKeys, filteredKeys.length);
  bindFeatureFilterControls();

  const intensityVisible = (
    (!filter || intensitySearchText.toLowerCase().includes(filter))
    && ["all", "通用能力"].includes(state.featureDomainFilter)
    && ["all", "background"].includes(state.featureStageFilter)
    && (state.featureStatusFilter === "all" || (state.featureStatusFilter === "enabled") === Boolean(intensity?.enabled))
  );

  const board = groups.map((group) => {
    if (!["all", "image_generation", group.title].includes(state.featureDomainFilter)) return "";
    const visibleKeys = group.keys.filter((key) => {
      if (!visibleFeatureSwitchKey(key)) return false;
      return featureMatchesCurrentFilters(key);
    });
    const hasIntensityCard = group.title === "通用能力" && intensityVisible;
    if (!visibleKeys.length && !hasIntensityCard) return "";
    const groupEnabled = visibleKeys.filter((key) => toBool(state.featureDraft[key])).length;
    const groupMeta = visibleKeys.length ? `${groupEnabled} / ${visibleKeys.length}` : "设置项";
    const prefix = hasIntensityCard
      ? proactiveIntensityCommonSettingCard(overviewSettings, intensity)
      : "";
    return `
      <section class="feature-switch-group">
        <header>
          <div>
            <b>${escapeHtml(group.title)}</b>
            <span>${escapeHtml(group.note || "")}</span>
          </div>
          <small>${escapeHtml(groupMeta)}</small>
        </header>
        <div class="feature-switch-list">
          ${prefix}
          ${visibleKeys.map((key) => featureSwitchItem(key)).join("")}
        </div>
      </section>
    `;
  }).filter(Boolean).join("");
  $("#featureFlags").innerHTML = board || `<div class="feature-filter-empty"><b>没有匹配的功能开关</b><span>可以调整领域、作用阶段、状态或搜索词。</span><button type="button" data-feature-filter-reset>清除筛选</button></div>`;
  document.querySelectorAll("[data-feature-key]").forEach((input) => {
    input.addEventListener("change", () => {
      state.featureDraft[input.dataset.featureKey] = input.checked;
      renderFeatureSwitches();
    });
  });
  document.querySelectorAll("[data-feature-open]").forEach((button) => {
    button.addEventListener("click", () => {
      state.selectedFeatureKey = button.dataset.featureOpen || "";
      renderFeatureSwitches();
    });
  });
  document.querySelectorAll("[data-persona-follow-key]").forEach((button) => {
    button.addEventListener("click", async (event) => {
      event.stopPropagation();
      if (!consumePersonaFollowConfirmation(button)) return;
      await followPersonaSetting(button.dataset.personaFollowKey, button);
    });
  });
  document.querySelectorAll("[data-feature-card-open]").forEach((card) => {
    const openDetail = () => {
      state.selectedFeatureKey = card.dataset.featureCardOpen || "";
      renderFeatureSwitches();
    };
    card.addEventListener("click", (event) => {
      if (event.target.closest("button, input, label, select, textarea, a")) return;
      openDetail();
    });
  });
  document.querySelector("[data-feature-filter-reset]")?.addEventListener("click", () => {
    state.featureDomainFilter = "all";
    state.featureStageFilter = "all";
    state.featureStatusFilter = "all";
    if ($("#featureFilter")) $("#featureFilter").value = "";
    renderFeatureSwitches();
  });
  bindProactiveOnlyTempUnlockActions($("#featureFlags"));
  bindProactiveIntensityCommonSetting();
}

function proactiveIntensityCommonSettingCard(settings = {}, intensity = {}) {
  const current = String(state.featureAuxiliaryDraft?.proactive_intensity_preset || settings.proactive_intensity_preset || intensity.preset || "off");
  const enabled = Boolean(intensity?.enabled);
  const effective = intensity?.effective || {};
  const interestProbability = Math.round(Number(effective.group_wakeup_interest_probability || 0) * 100);
  const maxDailyText = effective.max_daily_messages_text || formatProactiveLimit(effective.max_daily_messages, effective.max_daily_messages_unlimited);
  const interjectLimitText = effective.group_interject_max_daily_text || formatProactiveLimit(effective.group_interject_max_daily, effective.group_interject_max_daily_unlimited);
  const detail = enabled
    ? `预设层当前有效：私聊 ${formatProactiveDailyQuota(effective.max_daily_messages, effective.max_daily_messages_unlimited, maxDailyText)}，空闲 ${effective.idle_minutes ?? "-"} 分钟，最小间隔 ${effective.min_interval_minutes ?? "-"} 分钟；用户级覆盖与未回应倍率会在私聊用户详情显示。群唤醒冷却 ${effective.group_wakeup_cooldown_seconds ?? "-"} 秒，兴趣唤醒 ${interestProbability}%，群插话间隔 ${effective.group_interject_min_interval_minutes ?? "-"} 分钟，群插话上限 ${interjectLimitText}${effective.ignore_token_soft_limit ? "；最高档忽略 Token 软限额降载" : ""}。`
    : "关闭时完全沿用手动参数，不改变私聊、群聊唤醒或群主动插话频率。";
  return `
    <section class="feature-switch-item feature-setting-inline ${enabled ? "on" : "off"}">
      <div class="feature-switch-body">
        <button type="button" class="feature-switch-text" data-jump-tab="troubleshooting">
          <b>主动强度预设</b>
          <small>proactive_intensity_preset</small>
        </button>
        <div class="feature-switch-meta">
          <span class="feature-state-text">${escapeHtml(enabled ? (intensity.label || current) : "关闭：手动参数")}</span>
          <span class="feature-lock-note">影响私聊主动、群聊唤醒和群主动插话；排障页会显示当前覆盖项。</span>
        </div>
        <div class="feature-lock-related">${escapeHtml(detail)}</div>
      </div>
      <form class="feature-inline-setting-form" data-proactive-intensity-form>
        <select name="proactive_intensity_preset">
          ${[
            ["off", "关闭：手动参数"],
            ["balanced", "标准偏主动"],
            ["high_private", "私聊高频"],
            ["high_group", "群聊活跃"],
            ["live", "在线陪伴：不省成本"],
          ].map(([value, label]) => `<option value="${escapeHtml(value)}"${current === value ? " selected" : ""}>${escapeHtml(label)}</option>`).join("")}
        </select>
        <button type="submit">保存</button>
      </form>
    </section>
  `;
}

function bindProactiveIntensityCommonSetting() {
  document.querySelectorAll("[data-proactive-intensity-form]").forEach((form) => {
    const select = form.querySelector('[name="proactive_intensity_preset"]');
    const syncDraft = () => {
      state.featureAuxiliaryDraft = {
        ...(state.featureAuxiliaryDraft || {}),
        proactive_intensity_preset: select?.value || "off",
      };
      state.featureAuxiliaryDirty = true;
      syncFeatureFooterAction();
    };
    select?.addEventListener("change", syncDraft);
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      syncDraft();
      await saveFeatureSwitchChanges(
        form.querySelector("button[type='submit']"),
        "已保存主动强度预设",
      );
    });
  });
}

function syncFeatureFooterAction() {
  const actions = $("#featureSaveActions");
  const button = $("#saveFeaturesBtn");
  const backButton = $("#featureBackBtn");
  const status = $("#featureSaveState");
  if (!actions || !button) return;
  const onConfigPage = state.activeTab === "config";
  actions.hidden = !onConfigPage;
  if (!onConfigPage) return;
  const inDetail = Boolean(state.selectedFeatureKey && Object.prototype.hasOwnProperty.call(state.featureDraft || {}, state.selectedFeatureKey));
  const dirty = hasUnsavedFeatureChanges();
  const busy = Boolean(state.featureSaveInProgress || state.photoReferenceSubmitting);
  actions.classList.toggle("in-detail", inDetail);
  actions.classList.toggle("has-unsaved", dirty);
  if (backButton) backButton.hidden = !inDetail;
  if (backButton) backButton.disabled = busy;
  if (backButton) backButton.textContent = state.featureDetailSubpage === "photo_reference_library" ? "返回生图设置" : "返回功能列表";
  if (status) status.textContent = busy ? "正在保存更改" : dirty ? "有未保存更改" : "更改已保存";
  button.textContent = busy ? "处理中..." : state.featureDetailSubpage === "photo_reference_library" ? "保存参考图库" : inDetail ? "保存更改" : "保存功能开关";
  button.disabled = busy || !dirty;
}

function renderIsolationModeCards() {
  const root = $("#proactiveOnlyModeCard");
  if (!root) return;
  const key = "enable_proactive_only_mode";
  const checked = toBool(state.featureDraft[key]);
  const proactiveChat = state.overview?.proactive_chat || {};
  const proactiveChatState = proactiveChat.enabled
    ? (proactiveChat.runtime_mode_label || (proactiveChat.installed ? "发送前兼容" : "等待运行实例"))
    : "联动已关闭";
  const proactiveChatTone = proactiveChat.deep_active ? "on" : proactiveChat.runtime_degraded ? "error" : proactiveChat.installed ? "paused" : "off";
  const proactiveRuntimeVersion = String(proactiveChat.runtime_version || "未知").replace(/^v/i, "");
  const proactiveRuntimeMeta = proactiveChat.deep_active
    ? `v${proactiveRuntimeVersion} · 已接管 ${Number(proactiveChat.runtime_method_count || 0)} 个关键方法`
    : (proactiveChat.runtime_last_error || proactiveChat.runtime_last_event || "");
  root.innerHTML = `
    <div class="proactive-mode-stack">
      <div class="proactive-mode-settings-row">
        <section class="proactive-mode-card ${checked ? "on" : "off"}">
          <label class="feature-toggle-hit proactive-mode-toggle" aria-label="${escapeHtml(featureLabel(key))}">
            <input type="checkbox" data-proactive-only-mode-toggle ${checked ? "checked" : ""}>
            <span class="feature-toggle-visual"></span>
          </label>
          <div class="proactive-mode-main">
            <div class="proactive-mode-heading-row">
              <div class="proactive-mode-kicker">兼容与隔离</div>
              <span class="proactive-chat-status ${escapeHtml(proactiveChatTone)}">Proactive Chat · ${escapeHtml(proactiveChatState)}</span>
            </div>
            <h3>${escapeHtml(featureLabel(key))}</h3>
            <p>只让本插件负责主动私聊调度、生成和发送；普通私聊/群聊放行给 AstrBot 默认主链或其他插件。</p>
            ${proactiveRuntimeMeta ? `<small class="proactive-mode-runtime">${escapeHtml(proactiveRuntimeMeta)}</small>` : ""}
            <small class="proactive-mode-code">${escapeHtml(key)}</small>
          </div>
          <button type="button" class="proactive-mode-detail proactive-mode-button soft" data-feature-open="${escapeHtml(key)}">查看说明</button>
        </section>
      </div>
    </div>
  `;
  root.querySelector("[data-proactive-only-mode-toggle]")?.addEventListener("change", (event) => {
    state.featureDraft[key] = Boolean(event.target.checked);
    renderFeatureSwitches();
  });
  root.querySelectorAll("[data-feature-open]").forEach((button) => {
    button.addEventListener("click", () => {
      state.selectedFeatureKey = button.dataset.featureOpen || "";
      renderFeatureSwitches();
    });
  });

}


function renderPassiveInjectionPositionForm() {
  const form = $("#passiveInjectionPositionForm");
  if (!form) return;
  const settings = state.overview?.settings || {};
  const select = form.querySelector('[name="passive_injection_position"]');
  if (select) select.value = String(settings.passive_injection_position || "prompt");
  if (form.dataset.bound) return;
  form.dataset.bound = "1";
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const value = form.querySelector('[name="passive_injection_position"]')?.value || "prompt";
    await runAction(
      () => postJson("/settings/update", { settings: { passive_injection_position: value } }),
      "已保存动态提示词注入位置",
      form.querySelector("button[type='submit']"),
    );
  });
}

function bodyMonitorBatchSummary(batch = {}) {
  const received = Math.max(0, Number(batch.received || 0));
  const accepted = Math.max(0, Number(batch.accepted || 0));
  const skipped = Math.max(0, Number(batch.skipped || 0));
  const duplicate = Math.max(0, Number(batch.duplicate || 0));
  const expired = Math.max(0, Number(batch.expired || 0));
  if (![received, accepted, skipped, duplicate, expired].some(Boolean)) return "暂无批次记录";
  return `拉取 ${received} · 入选 ${accepted} · 跳过 ${skipped} · 重复 ${duplicate} · 过期 ${expired}`;
}

function normalizeMultiPersonaIds(value) {
  const items = Array.isArray(value)
    ? value
    : String(value || "").split(/[\s,，、]+/);
  return Array.from(new Set(items.map((item) => String(item || "").trim()).filter(Boolean)));
}

function multiPersonaConfigIds(root = document) {
  const checkedIds = Array.from(root?.querySelectorAll?.("[data-multi-persona-profile]:checked") || [])
    .map((item) => String(item.value || "").trim())
    .filter(Boolean);
  const primary = configuredPrimaryPersonaId();
  return Array.from(new Set([
    ...normalizeMultiPersonaIds(state.overview?.settings?.multi_persona_ids),
    ...normalizeMultiPersonaIds(state.featureDetailParamDraft?.multi_persona_ids),
    ...checkedIds,
    primary,
  ].filter(Boolean)));
}

function configuredMultiPersonaIds(root = document) {
  return Array.from(new Set([
    ...multiPersonaConfigIds(root),
    ...normalizeMultiPersonaIds(state.multiPersona?.profiles),
  ]));
}

const MULTI_PERSONA_MIGRATION_KEYS = Object.freeze([
  "daily_plan",
  "daily_state",
  "bot_diaries",
  "users",
  "groups",
  "memo_notes",
  "token_usage",
]);

function multiPersonaLegacyRoutingNotice() {
  const status = state.multiPersona || {};
  const raw = status.legacy_routing
    ?? status.legacy_binding_warning
    ?? status.legacy_window_bindings_warning
    ?? status.legacy_warning;
  if (!raw) return "";
  const item = typeof raw === "object" ? raw : { ignored: true, message: String(raw) };
  const ignored = Boolean(item.ignored ?? true);
  const count = Math.max(0, Number(item.count || 0));
  const warningCode = String(item.warning_code || "").trim();
  const backupPath = String(item.backup_path || "").trim();
  const message = String(item.message || "").trim();
  if (!ignored && !count && !warningCode && !backupPath && !message) return "";
  return `
    <article class="feature-detail-card multi-persona-legacy-routing" role="status">
      <h3>旧插件窗口绑定已停用</h3>
      <p>${escapeHtml(message || `检测到 ${count || "若干"} 条旧绑定；当前仅由 AstrBot 决定会话人格，插件不会再读取或修改这些绑定。`)}</p>
      ${backupPath ? `<span>备份位置：<code>${escapeHtml(backupPath)}</code></span>` : ""}
      ${warningCode ? `<small>${escapeHtml(warningCode)}</small>` : ""}
    </article>
  `;
}

function multiPersonaMigrationDetailCard() {
  const settings = state.overview?.settings || {};
  const primary = configuredPrimaryPersonaId() || String(state.multiPersona?.primary || "").trim();
  const enabledIds = new Set([
    ...normalizeMultiPersonaIds(state.multiPersona?.enabled_ids),
    ...normalizeMultiPersonaIds(settings.multi_persona_ids),
  ]);
  if (primary) enabledIds.add(primary);
  const configuredProfiles = new Set(
    normalizeMultiPersonaIds(state.multiPersona?.configured_profiles),
  );
  const ids = Array.from(new Set([
    primary,
    ...Array.from(configuredProfiles),
  ].filter((id) => id && enabledIds.has(id) && (id === primary || configuredProfiles.has(id)))));
  const legacyRoutingNotice = multiPersonaLegacyRoutingNotice();
  const options = ids.map((id) => `<option value="${escapeHtml(id)}">${escapeHtml(personaDisplayLabel(id))}</option>`).join("");
  if (ids.length < 2) {
    return `${legacyRoutingNotice}
      <article class="feature-detail-card">
        <h3>人格资料迁移</h3>
        <p>保存至少两个人格后，这里会显示按功能迁移资料的入口。</p>
      </article>
    `;
  }
  const keys = [
    ["daily_plan", "日程"],
    ["daily_state", "状态"],
    ["bot_diaries", "日记"],
    ["users", "用户资料"],
    ["groups", "群资料"],
    ["memo_notes", "备忘录"],
    ["token_usage", "Token 记录"],
  ];
  return `${legacyRoutingNotice}
    <article class="feature-detail-card multi-persona-migration-card">
      <h3>人格资料迁移</h3>
      <p>从已启用且已建立配置的人格复制选中的资料；目标人格的缓存会同步清理，避免旧人格上下文残留。</p>
      <div class="multi-persona-migration-selects">
        <label><span>来源人格</span><select data-migrate-source>${options}</select></label>
        <label><span>目标人格</span><select data-migrate-target>${options}</select></label>
      </div>
      <div class="multi-persona-choice-list compact">
        ${keys.map(([key, label]) => `<label><input type="checkbox" value="${key}" data-migrate-key checked><span>${label}</span></label>`).join("")}
      </div>
      <button type="button" class="feature-param-save" data-migrate-submit>迁移选中资料并清理缓存</button>
    </article>
  `;
}

function bodyMonitorFeatureDetailCard() {
  const key = "enable_body_monitor_integration";
  const status = state.overview?.body_monitor_integration || {};
  const settings = state.overview?.settings || {};
  const persistedEnabled = toBool(status.enabled ?? settings[key]);
  const draftEnabled = toBool(state.featureDraft?.[key] ?? persistedEnabled);
  const dirty = draftEnabled !== persistedEnabled;
  const stateName = String(status.state || (persistedEnabled ? "initializing" : "disabled"));
  const stateLabels = {
    connected: "已连接",
    disabled: "联动已关闭",
    error: "联动异常",
    incompatible: "接口版本不兼容",
    initializing: "正在初始化",
    missing: "未安装 Body Monitor",
  };
  const stateText = status.state_text || stateLabels[stateName] || (persistedEnabled ? "正在初始化" : "联动已关闭");
  const lastPull = status.last_pull_text || (Number(status.last_pull_at || 0) > 0 ? formatRecentTime(status.last_pull_at, "-") : "尚未拉取");
  const versionText = Number(status.api_version || 0) > 0
    ? `v${Number(status.api_version)} / v${Number(status.supported_api_version || 1)}`
    : `期望 v${Number(status.supported_api_version || 1)}`;
  return `
    <article class="feature-detail-card">
      <h3>Body Monitor 运行状态</h3>
      <dl>
        ${dirty ? `<div><dt>待保存</dt><dd>将${draftEnabled ? "开启" : "关闭"}健康事件联动</dd></div>` : ""}
        <div><dt>联动状态</dt><dd>${escapeHtml(stateText)}</dd></div>
        <div><dt>最近拉取</dt><dd>${escapeHtml(lastPull)}</dd></div>
        <div><dt>接口版本</dt><dd>${escapeHtml(versionText)}</dd></div>
        <div><dt>最近批次</dt><dd>${escapeHtml(bodyMonitorBatchSummary(status.last_batch || {}))}</dd></div>
        ${status.error ? `<div><dt>错误</dt><dd>${escapeHtml(status.error)}</dd></div>` : ""}
      </dl>
    </article>
  `;
}

function groupMemberSafetyManagerCardHtml() {
  const groups = Array.isArray(state.groups) ? state.groups : [];
  const selectedId = groups.some((group) => String(group.group_id) === String(state.selectedGroupId))
    ? String(state.selectedGroupId)
    : String(groups[0]?.group_id || "");
  const options = groups.map((group) => {
    const id = String(group.group_id || "");
    const label = `${groupDisplayName(group)} · ${groupIdText(group)}`;
    return `<option value="${escapeHtml(id)}"${id === selectedId ? " selected" : ""}>${escapeHtml(label)}</option>`;
  }).join("");
  const blockedCount = groups.reduce((sum, group) => sum + Number(group.member_safety_blocked_count || 0), 0);
  return `
    <article class="feature-detail-card group-safety-manager-launch">
      <div class="group-safety-manager-launch-copy">
        <span class="module-badge">MEMBER CONTROL</span>
        <h3>成员名单管理</h3>
        <p>按群查看观察中、已静默和已豁免成员，支持手动静默、解除、清除风险次数与设置豁免。</p>
        <small>当前已记录 ${escapeHtml(groups.length)} 个群 · 自动静默 ${escapeHtml(blockedCount)} 人。这里只控制 Bot 是否响应，不会调用平台禁言。</small>
      </div>
      <div class="group-safety-manager-launch-actions">
        <label>
          <span>目标群聊</span>
          <select data-group-safety-manage-group${groups.length ? "" : " disabled"}>
            ${groups.length ? options : '<option value="">暂无已观测群聊</option>'}
          </select>
        </label>
        <button type="button" data-group-safety-manage-open>${groups.length ? "打开成员管理" : "读取群列表"}</button>
      </div>
    </article>
  `;
}

function featureSwitchItem(key) {
  const checked = toBool(state.featureDraft[key]);
  const locked = featureLockedByProactiveOnlyMode(key);
  const tempUnlocked = featureTemporarilyUnlockedByProactiveOnly(key);
  const displayOn = checked || tempUnlocked;
  const related = proactiveOnlyRelatedUnlocks(key);
  let stateText = locked ? (tempUnlocked ? "临时放行" : "已锁定") : checked ? "开启" : "关闭";
  if (!locked && key === "enable_custom_relationship_stage_policy") {
    const settings = state.overview?.settings || {};
    const count = normalizeRelationshipPolicy(settings.relationship_stage_policy).length || 8;
    stateText = checked
      ? `已启用 · ${count} 阶段｜关系上限 ${relationshipStageCapLabel(settings.relationship_positive_stage_cap_key)}｜互动上限 ${normalInteractionCapLabel(settings.normal_interaction_band_cap)}`
      : "已关闭 · 不记账、不注入关系表达、不影响画像";
  }
  const lockNote = tempUnlocked ? "已临时放行，关闭仅保留主动能力后清空" : "仅保留主动能力中，原配置保留";
  const relatedText = related.length ? `建议同步：${related.map((item) => item.label || item.key).join("、")}` : "";
  const stageTags = featureStagesForKey(key)
    .map((stage) => `<span data-feature-stage="${escapeHtml(stage)}">${escapeHtml(featureStageLabel(stage, true))}</span>`)
    .join("");
  const imageUse = state.featureDomainFilter === "image_generation" ? imageGenerationFeatureUse(key) : "";
  const sourceBadge = personaSourceBadgeHtml(key, { compact: true });
  const followButton = personaConfigIsOverride(key)
    ? `<button type="button" class="persona-follow-button" data-persona-follow-key="${escapeHtml(key)}" title="恢复跟随主人格">恢复跟随</button>`
    : "";
  return `
    <section class="feature-switch-item has-feature-detail ${displayOn ? "on" : "off"} ${locked ? "locked" : ""}" data-feature-card-open="${escapeHtml(key)}" title="${escapeHtml(locked ? "仅保留主动能力开启时，本功能在本插件普通被动链路中被跳过，原配置会保留。" : featureDescription(key))}">
      <label class="feature-toggle-hit" aria-label="${escapeHtml(featureLabel(key))}">
        <input type="checkbox" data-feature-key="${escapeHtml(key)}" ${displayOn ? "checked" : ""} ${locked ? "disabled" : ""}>
        <span class="feature-toggle-visual"></span>
      </label>
      <div class="feature-switch-body">
        <button type="button" class="feature-switch-text" data-feature-open="${escapeHtml(key)}">
          <b>${escapeHtml(featureLabel(key))}</b>
          <small>${escapeHtml(featurePublicKey(key))}</small>
          <span class="feature-open-hint">查看配置 <span aria-hidden="true">›</span></span>
        </button>
        <div class="feature-stage-tags" aria-label="作用阶段">${imageUse ? `<span class="feature-image-use">${escapeHtml(imageUse)}</span>` : ""}${stageTags}</div>
        <div class="feature-switch-meta">
          <span class="feature-state-text">${escapeHtml(stateText)}</span>
          ${sourceBadge}
          ${followButton}
          ${locked ? `<span class="feature-lock-note">${escapeHtml(lockNote)}</span>` : ""}
        </div>
        ${locked && relatedText ? `<div class="feature-lock-related">${escapeHtml(relatedText)}</div>` : ""}
      </div>
      ${locked ? `<button type="button" class="feature-temp-unlock-btn" data-proactive-temp-unlock="${escapeHtml(key)}" data-action="${tempUnlocked ? "clear" : "unlock"}">${escapeHtml(tempUnlocked ? "取消放行" : "临时放行")}</button>` : ""}
    </section>
  `;
}

function relationshipStageCapLabel(key) {
  return ({ familiar: "熟悉", close: "亲近", intimate: "亲密", deeply_bonded: "深度联结" })[String(key)] || "亲近";
}

function normalInteractionCapLabel(key) {
  return ({ relaxed: "放松", lively: "活泼", warm: "温暖" })[String(key)] || "温暖";
}

function featureGroupForKey(key) {
  if (["enable_proactive_only_mode", "enable_multi_persona_mode"].includes(key)) return "兼容与隔离";
  const parentKey = topLevelFeatureKey(key);
  const group = featureGroups.find((item) => item.keys.includes(parentKey));
  return group ? group.title : "其他";
}

