$("#saveProvidersBtn").addEventListener("click", async () => {
  if (!window.PrivateCompanionProviderTree?.currentProviderValues) {
    showToast("模型配置面板脚本未加载，请刷新拓展页", "error");
    return;
  }
  const values = currentProviderValues();
  const timeoutOverrides = currentProviderTimeoutValues();
  const tokenLimitOverrides = currentProviderTokenLimitValues();
  const fallbackOverrides = currentProviderFallbackValues();
  const deepseekPeak = window.PrivateCompanionProviderTree.currentDeepseekPeakValues({ document, state });
  const modelReplacement = window.PrivateCompanionProviderTree.currentModelReplacementValues({ document, state });
  const provider_config_mode = currentProviderConfigMode();
  const providers = {};
  Object.keys(providerLabels).forEach((key) => {
    if (visibleConfigKey(key) && providerAllowedInCurrentMode(key)) providers[key] = values[key] || "";
  });
  providers.DEEPSEEK_PEAK_REPLACEMENT_PROVIDER_ID = deepseekPeak.provider;
  providers.SENSITIVE_REPLACEMENT_PROVIDER_ID = modelReplacement.sensitiveProvider;
  const saved = await runAction(
    () => postJson("/settings/update", { settings: {
      provider_config_mode,
      model_timeout_overrides: timeoutOverrides,
      model_token_limit_overrides: tokenLimitOverrides,
      model_fallback_overrides: fallbackOverrides,
      model_replacement_scope: modelReplacement.scope,
      model_replacement_rules: modelReplacement.rules,
      enable_sensitive_model_replacement: modelReplacement.sensitiveEnabled,
      sensitive_replacement_keywords: modelReplacement.sensitiveKeywords,
      enable_deepseek_peak_replacement: deepseekPeak.enabled,
      deepseek_peak_windows: deepseekPeak.windows,
      deepseek_peak_timezone: deepseekPeak.timezone,
      deepseek_peak_match_keywords: deepseekPeak.keywords,
    }, providers, overwrite_provider_modes: true }),
    "已保存模型配置，并同步 quick / precision 文本分流；独立识图保持原配置",
    $("#saveProvidersBtn")
  );
  if (!actionResultPersisted(saved)) return;
  state.overview = state.overview || {};
  state.overview.settings = { ...(state.overview.settings || {}), provider_config_mode };
  state.providerDraft = {};
  state.providerTimeoutDraft = { ...timeoutOverrides };
  state.providerTokenLimitDraft = { ...tokenLimitOverrides };
  state.providerFallbackDraft = { ...fallbackOverrides };
  state.overview.settings.model_timeout_overrides = { ...timeoutOverrides };
  state.overview.settings.model_token_limit_overrides = { ...tokenLimitOverrides };
  state.overview.settings.model_fallback_overrides = { ...fallbackOverrides };
  state.overview.settings.model_replacement_scope = modelReplacement.scope;
  state.overview.settings.model_replacement_rules = modelReplacement.rules;
  state.overview.settings.enable_sensitive_model_replacement = modelReplacement.sensitiveEnabled;
  state.overview.settings.sensitive_replacement_keywords = modelReplacement.sensitiveKeywords;
  state.overview.providers = { ...(state.overview.providers || {}), SENSITIVE_REPLACEMENT_PROVIDER_ID: modelReplacement.sensitiveProvider };
  state.providerConfigMode = provider_config_mode;
  renderProviders();
});

$("#saveImageModelsBtn").addEventListener("click", async () => {
  const pane = document.getElementById("modelsImagePane");
  const endpoints = collectPhotoApiEndpointEditor(pane) || photoApiEndpointDraft();
  const photo_generation_backend = document.getElementById("imageGenerationBackend")?.value || "auto";
  const saved = await runAction(
    () => postJson("/settings/update", {
      settings: {
        photo_generation_backend,
        external_image_api_endpoints: endpoints,
      },
    }),
    "已保存并应用生图模型配置",
    $("#saveImageModelsBtn"),
    { reload: false },
  );
  if (!actionResultPersisted(saved)) return;
  state.imageApiEndpointDraft = endpoints.map(normalizePhotoApiEndpoint);
  state.imageApiEndpointSavedFingerprints = state.imageApiEndpointDraft
    .map((endpoint, index) => photoApiEndpointFingerprint(endpoint, index));
  state.imageApiEndpointTestResults = {};
  state.lazyLoaded.imageApiStatus = false;
  await loadImageApiStatus(true).catch((error) => showToast(`刷新生图 API 状态失败：${error.message}`, "error"));
  renderProviders();
});

$("#testAllProvidersBtn").addEventListener("click", async () => {
  if (!window.PrivateCompanionProviderTree?.testProvider) {
    showToast("模型配置面板脚本未加载，请刷新拓展页", "error");
    return;
  }
  for (const key of Object.keys(providerLabels).filter((item) => visibleConfigKey(item) && providerAllowedInCurrentMode(item))) {
    await testProvider(key);
  }
});

document.documentElement.dataset.pcAppLoaded = "1";
window.dispatchEvent(new Event("pc-panel-app-ready"));

async function bootstrapPage() {
  try {
    const bridge = await getReadyPageBridge();
    if (!bridge && !isHttpApiMode()) {
      throw new Error("未检测到 AstrBot 官方插件 Page 桥接，请从 AstrBot 后台的插件拓展页打开");
    }
    await loadAll();
  } catch (error) {
    const subtitle = document.getElementById("subtitle");
    if (subtitle) subtitle.textContent = `加载失败：${error.message}`;
  }
}

void bootstrapPage();
